const EXERCISES = [{"id":"0007","name":"alternate lateral pulldown","name_zh":"交替高位下拉","category":"back","equipment":"cable","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids"],"instructions_zh":["坐在缆绳机上，背部挺直，双脚平放在地面上。","正手握住手柄，握距略宽于肩宽。","稍微向后倾斜，将手柄拉向胸部，将肩胛骨挤压在一起。","在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0007-4IKbhHV.jpg","gif":"media/0007-4IKbhHV.gif","poses":"media/0007-4IKbhHV-poses.jpg"},{"id":"0009","name":"assisted chest dip (kneeling)","name_zh":"辅助跪姿双杠臂屈伸","category":"chest","equipment":"leverage machine","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["将机器调整到您想要的高度，并将膝盖固定在垫子上。","手掌朝下，抓住手柄，双臂完全伸展。","弯曲肘部降低身体，直到上臂与地板平行。","暂停片刻，然后将自己推回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0009-PAgTVaK.jpg","gif":"media/0009-PAgTVaK.gif","poses":"media/0009-PAgTVaK-poses.jpg"},{"id":"0014","name":"assisted motion russian twist","name_zh":"辅助俄罗斯转体","category":"waist","equipment":"medicine ball","target":"abs","muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"instructions_zh":["坐在地上，膝盖弯曲，双脚平放在地板上。","双手将健身球放在胸前。","稍微向后倾斜，收紧腹肌并保持背部挺直。","慢慢地将你的躯干向右扭转，将健身球移向身体的右侧。","暂停片刻，然后将躯干向左扭转，将健身球移向身体左侧。","继续交替进行所需的重复次数。"],"kind":"exercise","img":"media/0014-r7cT9YD.jpg","gif":"media/0014-r7cT9YD.gif","poses":"media/0014-r7cT9YD-poses.jpg"},{"id":"0015","name":"assisted parallel close grip pull-up","name_zh":"辅助窄距平行握引体","category":"back","equipment":"leverage machine","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["将机器调整到您想要的重量和高度。","将双手紧紧握在双杠上，手掌相对。","悬挂在杠上，双臂完全伸展，双脚离开地面。","收紧背部肌肉，将身体拉向杠铃，保持肘部靠近身体。","继续拉，直到下巴高于杠铃。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0015-vrhHa6D.jpg","gif":"media/0015-vrhHa6D.gif","poses":"media/0015-vrhHa6D-poses.jpg"},{"id":"0017","name":"assisted pull-up","name_zh":"辅助引体向上","category":"back","equipment":"leverage machine","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["将机器调整至您所需的体重和高度设置。","正手握住手柄，握距略宽于肩宽。","双臂完全伸展，双脚离开地面。","收紧背部肌肉，将身体拉向手柄，保持肘部靠近身体。","继续拉，直到下巴位于手柄上方。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0017-kiJ4Z2K.jpg","gif":"media/0017-kiJ4Z2K.gif","poses":"media/0017-kiJ4Z2K-poses.jpg"},{"id":"0019","name":"assisted triceps dip (kneeling)","name_zh":"辅助跪姿臂屈伸","category":"upper arms","equipment":"leverage machine","target":"triceps","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"instructions_zh":["将机器调整到您想要的重量和高度。","跪在面向机器的垫子上，双手握住手柄。","弯曲肘部降低身体，保持背部挺直并靠近机器。","在底部暂停片刻，然后将自己推回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0019-J60bN17.jpg","gif":"media/0019-J60bN17.gif","poses":"media/0019-J60bN17-poses.jpg"},{"id":"0024","name":"barbell bench front squat","name_zh":"杠铃托凳前蹲","category":"upper legs","equipment":"barbell","target":"quads","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes","calves"],"instructions_zh":["首先站立，双脚分开与肩同宽，将杠铃放在上胸部，锁骨下方。","正手握住杠铃，保持肘部向上，上臂与地面平行。","弯曲膝盖和臀部，将身体降低到蹲姿，保持背部挺直，挺胸。","在深蹲底部暂停片刻，然后用脚后跟恢复到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0024-Y7YcmIJ.jpg","gif":"media/0024-Y7YcmIJ.gif","poses":"media/0024-Y7YcmIJ-poses.jpg"},{"id":"0025","name":"barbell bench press","name_zh":"杠铃卧推","category":"chest","equipment":"barbell","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","正手握住杠铃，握距略宽于肩宽。","将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。","将杠铃慢慢降低到胸部，保持肘部内收。","当杠铃触及胸部时暂停片刻。","伸展双臂，将杠铃推回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0025-EIeI8Vf.jpg","gif":"media/0025-EIeI8Vf.gif","poses":"media/0025-EIeI8Vf-poses.jpg"},{"id":"0026","name":"barbell bench squat","name_zh":"杠铃凳上深蹲","category":"upper legs","equipment":"barbell","target":"quads","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"instructions_zh":["将杠铃放在深蹲架上，与胸部同高。","背对架子站立，双脚与肩同宽。","弯曲膝盖，将身体降低至蹲姿，保持背部挺直，挺胸。","正手握住杠铃，握距略宽于肩宽。","将杠铃从架子上提起并向后退一步，确保双脚仍与肩同宽。","降低身体蹲下，保持膝盖与脚趾在一条线上。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0026-W9pFVv1.jpg","gif":"media/0026-W9pFVv1.gif","poses":"media/0026-W9pFVv1-poses.jpg"},{"id":"0027","name":"barbell bent over row","name_zh":"杠铃俯身划船","category":"back","equipment":"barbell","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["站立，双脚分开与肩同宽，膝盖稍微弯曲。","臀部向前弯曲，同时保持背部挺直、挺胸。","正手握住杠铃，双手间距略宽于肩宽。","通过收缩肩胛骨并挤压背部肌肉，将杠铃拉向下胸部。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0027-eZyBC3j.jpg","gif":"media/0027-eZyBC3j.gif","poses":"media/0027-eZyBC3j-poses.jpg"},{"id":"0028","name":"barbell clean and press","name_zh":"杠铃高翻推举","category":"upper legs","equipment":"barbell","target":"quads","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes","shoulders","triceps"],"instructions_zh":["双脚分开与肩同宽站立，杠铃放在你面前的地板上。","弯曲膝盖并以臀部为铰链降低并用正手握住杠铃，双手分开略宽于肩宽。","通过脚后跟发力，伸展臀部和膝盖，将杠铃抬离地板，使其靠近身体。","当杠铃到达大腿时，爆发性伸展臀部，耸肩，并将杠铃拉向胸部。","当杠铃到达胸部高度时，迅速将其降至肩部水平，肘部向前，手掌朝上。","从接球位置开始，伸展双臂并将杠铃笔直向上推，将杠铃压过头顶。","将杠铃放回起始位置，然后重复所需的重复次数。"],"kind":"exercise","img":"media/0028-SGY8Zui.jpg","gif":"media/0028-SGY8Zui.gif","poses":"media/0028-SGY8Zui-poses.jpg"},{"id":"0029","name":"barbell clean-grip front squat","name_zh":"杠铃窄握前蹲","category":"upper legs","equipment":"barbell","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"instructions_zh":["首先，双脚分开与肩同宽，将杠铃放在上胸部，肘部向前。","弯曲膝盖并将臀部向后推，降低身体，就像坐在椅子上一样。","下降时保持挺胸、背部挺直，确保膝盖不超过脚趾。","继续降低，直到大腿与地面平行，或者尽可能低。","在底部停顿片刻，然后用脚跟推动站起来，伸展臀部和膝盖。","重复所需的重复次数。"],"kind":"exercise","img":"media/0029-qi996YS.jpg","gif":"media/0029-qi996YS.gif","poses":"media/0029-qi996YS-poses.jpg"},{"id":"0030","name":"barbell close-grip bench press","name_zh":"杠铃窄握卧推","category":"upper arms","equipment":"barbell","target":"triceps","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"instructions_zh":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","紧紧握住杠铃，握距略窄于肩宽。","松开杠铃并将其缓慢降低至胸部，保持肘部靠近身体。","当杠铃触及胸部时暂停片刻。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"],"kind":"exercise","img":"media/0030-J6Dx1Mu.jpg","gif":"media/0030-J6Dx1Mu.gif","poses":"media/0030-J6Dx1Mu-poses.jpg"},{"id":"0031","name":"barbell curl","name_zh":"杠铃弯举","category":"upper arms","equipment":"barbell","target":"biceps","muscle_group":"forearms","secondary_muscles":["forearms"],"instructions_zh":["站直，双脚分开与肩同宽，反手握住杠铃，手掌朝前。","保持肘部靠近躯干，在弯举哑铃时呼气，同时收缩二头肌。","继续抬高杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气，慢慢开始将杠铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0031-25GPyDY.jpg","gif":"media/0031-25GPyDY.gif","poses":"media/0031-25GPyDY-poses.jpg"},{"id":"0032","name":"barbell deadlift","name_zh":"杠铃硬拉","category":"upper legs","equipment":"barbell","target":"glutes","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"instructions_zh":["双脚分开与肩同宽站立，杠铃放在你面前的地面上。","弯曲膝盖并以臀部为铰链，降低躯干，正手握住杠铃，双手分开略宽于肩宽。","当你通过脚后跟将杠铃抬离地面时，保持背部挺直，胸部抬起，伸展臀部和膝盖。","当你站直时，挤压你的臀部并保持你的核心参与。","弯曲臀部和膝盖，将杠铃放回地面，保持背部挺直。","重复所需的重复次数。"],"kind":"exercise","img":"media/0032-ila4NZS.jpg","gif":"media/0032-ila4NZS.gif","poses":"media/0032-ila4NZS-poses.jpg"},{"id":"0033","name":"barbell decline bench press","name_zh":"杠铃下斜卧推","category":"chest","equipment":"barbell","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["躺在倾斜的长凳上，双脚固定，头部低于臀部。","正手握住杠铃，握距略宽于肩宽。","松开杠铃，慢慢将其降低到胸部，保持肘部内收。","在底部停顿片刻，然后将杠铃推回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0033-GrO65fd.jpg","gif":"media/0033-GrO65fd.gif","poses":"media/0033-GrO65fd-poses.jpg"},{"id":"0035","name":"barbell decline close grip to skull press","name_zh":"杠铃下斜窄握臂屈伸","category":"upper arms","equipment":"barbell","target":"triceps","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"instructions_zh":["躺在下斜长凳上，头低于脚，紧紧握住杠铃。","弯曲肘部，将杠铃向前额降低，保持上臂静止。","暂停片刻，然后伸展双臂将杠铃推回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0035-LMGXZn8.jpg","gif":"media/0035-LMGXZn8.gif","poses":"media/0035-LMGXZn8-poses.jpg"},{"id":"0036","name":"barbell decline wide-grip press","name_zh":"杠铃下斜宽握推举","category":"chest","equipment":"barbell","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["躺在倾斜的长凳上，双脚固定，头部低于臀部。","宽握距抓住杠铃，握距略宽于肩宽。","将杠铃降低到胸部，保持肘部向两侧伸出。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"],"kind":"exercise","img":"media/0036-hl8DUh8.jpg","gif":"media/0036-hl8DUh8.gif","poses":"media/0036-hl8DUh8-poses.jpg"},{"id":"0039","name":"barbell front chest squat","name_zh":"杠铃胸前深蹲","category":"upper legs","equipment":"barbell","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"instructions_zh":["首先站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在胸前，双手与肩同宽，肘部向前。","当你将身体降低到蹲姿时，收紧核心并保持挺胸，将臀部向后推并弯曲膝盖。","降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0039-IeTIEqg.jpg","gif":"media/0039-IeTIEqg.gif","poses":"media/0039-IeTIEqg-poses.jpg"},{"id":"0042","name":"barbell front squat","name_zh":"杠铃前蹲","category":"upper legs","equipment":"barbell","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"instructions_zh":["首先站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在肩膀前面，将其放在锁骨和肩膀上。","当你将身体降低到蹲姿时，收紧核心并保持挺胸，将臀部向后推并弯曲膝盖。","降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0042-zG0zs85.jpg","gif":"media/0042-zG0zs85.gif","poses":"media/0042-zG0zs85-poses.jpg"},{"id":"0043","name":"barbell full squat","name_zh":"杠铃全蹲","category":"upper legs","equipment":"barbell","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"instructions_zh":["站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在上背部，将其放在斜方肌或三角肌后束上。","当你开始降低身体时，启动你的核心并保持胸部挺直。","弯曲膝盖和臀部，向后和向下推臀部，就像坐在椅子上一样。","放低身体，直到大腿与地面平行或稍低于地面。","保持膝盖与脚趾对齐，并将重量放在脚后跟上。","通过脚后跟站起来，伸展臀部和膝盖。","重复所需的重复次数。"],"kind":"exercise","img":"media/0043-qXTaZnJ.jpg","gif":"media/0043-qXTaZnJ.gif","poses":"media/0043-qXTaZnJ-poses.jpg"},{"id":"0045","name":"barbell guillotine bench press","name_zh":"杠铃断头台卧推","category":"chest","equipment":"barbell","target":"pectorals","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"instructions_zh":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","正手握住杠铃，握距略宽于肩宽。","慢慢地将杠铃降低到颈部，保持肘部朝外。","当杠铃位于颈部上方时，暂停片刻。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"],"kind":"exercise","img":"media/0045-GXoaSgn.jpg","gif":"media/0045-GXoaSgn.gif","poses":"media/0045-GXoaSgn-poses.jpg"},{"id":"0046","name":"barbell hack squat","name_zh":"杠铃哈克深蹲","category":"upper legs","equipment":"barbell","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"instructions_zh":["首先站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在腿后面，将其放在大腿上部。","弯曲膝盖和臀部，降低身体，保持背部挺直，挺胸。","继续降低，直到大腿与地面平行，或者尽可能低。","暂停片刻，然后用力推动脚后跟，回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0046-5VCj6iH.jpg","gif":"media/0046-5VCj6iH.gif","poses":"media/0046-5VCj6iH-poses.jpg"},{"id":"0047","name":"barbell incline bench press","name_zh":"杠铃上斜卧推","category":"chest","equipment":"barbell","target":"pectorals","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"instructions_zh":["设置一个 45 度角的上斜凳。","躺在长凳上，双脚平放在地上。","正手握住杠铃，握距略宽于肩宽。","松开杠铃并将其缓慢降低至胸部，保持肘部呈 45 度角。","在底部停顿片刻，然后将杠铃推回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0047-3TZduzM.jpg","gif":"media/0047-3TZduzM.gif","poses":"media/0047-3TZduzM-poses.jpg"},{"id":"0048","name":"barbell incline reverse-grip press","name_zh":"杠铃上斜反握推举","category":"upper arms","equipment":"barbell","target":"triceps","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"instructions_zh":["设置一个 45 度角的上斜凳。","仰卧在长凳上，反握抓住杠铃，双手距离略宽于肩宽。","松开杠铃并将其向上胸部降低，保持肘部内收。","在底部停顿片刻，然后将杠铃推回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0048-641mIfk.jpg","gif":"media/0048-641mIfk.gif","poses":"media/0048-641mIfk-poses.jpg"},{"id":"0049","name":"barbell incline row","name_zh":"杠铃上斜划船","category":"back","equipment":"barbell","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["设置一个 45 度角的上斜凳。","脸朝下躺在长凳上，胸部靠在垫子上，双脚平放在地上。","正手握住杠铃，握距略宽于肩宽。","保持背部挺直，核心肌群参与。","将杠铃拉向胸部，将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0049-dmgMp3n.jpg","gif":"media/0049-dmgMp3n.gif","poses":"media/0049-dmgMp3n-poses.jpg"},{"id":"0051","name":"barbell jefferson squat","name_zh":"杠铃杰斐逊深蹲","category":"upper legs","equipment":"barbell","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"instructions_zh":["站立，双脚分开与肩同宽，脚趾稍微外翻。","正手握住杠铃，将其放在身体前部、腰部下方。","左脚向前迈出，右脚向后迈出，双脚分开与肩同宽。","弯曲膝盖，将身体降低至蹲姿，保持背部挺直，挺胸。","脚后跟用力，站回起始位置。","重复该动作，每次重复时交替使用前脚和后脚。"],"kind":"exercise","img":"media/0051-pkSoCW9.jpg","gif":"media/0051-pkSoCW9.gif","poses":"media/0051-pkSoCW9-poses.jpg"},{"id":"0052","name":"barbell jm bench press","name_zh":"杠铃 JM 卧推","category":"upper arms","equipment":"barbell","target":"triceps","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"instructions_zh":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","正手握住杠铃，握距略宽于肩宽。","将杠铃降低到胸部，保持肘部靠近身体。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"],"kind":"exercise","img":"media/0052-ZsiqXYa.jpg","gif":"media/0052-ZsiqXYa.gif","poses":"media/0052-ZsiqXYa-poses.jpg"},{"id":"0053","name":"barbell jump squat","name_zh":"杠铃跳跃深蹲","category":"upper legs","equipment":"barbell","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"instructions_zh":["首先，双脚分开与肩同宽站立，将杠铃放在上背部。","弯曲膝盖并将臀部向后推，将身体降低至蹲姿。","一旦到达深蹲底部，就从地面跳起向上爆发。","跳跃时，伸展臀部、膝盖和脚踝，推动脚趾。","轻轻地回到蹲姿，然后立即重复该动作达到所需的重复次数。"],"kind":"exercise","img":"media/0053-1gFNTZV.jpg","gif":"media/0053-1gFNTZV.gif","poses":"media/0053-1gFNTZV-poses.jpg"},{"id":"0054","name":"barbell lunge","name_zh":"杠铃箭步蹲","category":"upper legs","equipment":"barbell","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"instructions_zh":["首先，双脚分开与肩同宽，将杠铃放在上背部。","右脚向前迈出一步，保持躯干直立。","弯曲右膝降低身体，直到大腿与地面平行。","推动右脚跟回到起始位置。","用左腿重复上述动作，交替腿进行所需的重复次数。"],"kind":"exercise","img":"media/0054-t8iSghb.jpg","gif":"media/0054-t8iSghb.gif","poses":"media/0054-t8iSghb-poses.jpg"},{"id":"0055","name":"barbell lying close-grip press","name_zh":"杠铃仰卧窄握推","category":"upper arms","equipment":"barbell","target":"triceps","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"instructions_zh":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","紧紧握住杠铃，双手与肩同宽，手掌朝向脚部。","将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。","慢慢地将杠铃降低到胸部，保持肘部靠近身体。","当杠铃接触胸部时暂停片刻，然后将其推回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0055-EcaV7aL.jpg","gif":"media/0055-EcaV7aL.gif","poses":"media/0055-EcaV7aL-poses.jpg"},{"id":"0058","name":"barbell lying lifting (on hip)","name_zh":"杠铃仰卧提髋","category":"upper legs","equipment":"barbell","target":"glutes","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"instructions_zh":["仰卧在长凳上，双脚平放在地上，膝盖弯曲。","正手握住杠铃并将其放在臀部上。","收紧臀部，将臀部抬离长凳，直到身体从膝盖到肩膀形成一条直线。","在顶部暂停片刻，然后慢慢将臀部放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0058-SNFfUff.jpg","gif":"media/0058-SNFfUff.gif","poses":"media/0058-SNFfUff-poses.jpg"},{"id":"0063","name":"barbell narrow stance squat","name_zh":"杠铃窄站距深蹲","category":"upper legs","equipment":"barbell","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"instructions_zh":["站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在上背部，将其放在斜方肌或三角肌后束上。","收紧核心并保持挺胸，同时弯曲膝盖并向后推臀部，慢慢降低身体。","继续降低，直到大腿与地面平行或略低于地面。","暂停片刻，然后用力推动脚后跟，回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0063-elhhVgj.jpg","gif":"media/0063-elhhVgj.gif","poses":"media/0063-elhhVgj-poses.jpg"},{"id":"0064","name":"barbell one arm bent over row","name_zh":"杠铃单臂俯身划船","category":"back","equipment":"barbell","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["双脚分开与肩同宽站立，膝盖稍微弯曲，用一只手正握握住杠铃。","臀部向前弯曲，保持背部挺直，头部处于中立位置。","将杠铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。","以受控的方式将杠铃降低回起始位置。","重复所需的重复次数，然后换到另一只手臂。"],"kind":"exercise","img":"media/0064-Jsgsc27.jpg","gif":"media/0064-Jsgsc27.gif","poses":"media/0064-Jsgsc27-poses.jpg"},{"id":"0065","name":"barbell one arm floor press","name_zh":"杠铃单臂地板卧推","category":"upper arms","equipment":"barbell","target":"triceps","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"instructions_zh":["仰卧在地板上，膝盖弯曲，双脚平放在地面上。","用一只手握住杠铃，掌心朝上，将手臂伸直至胸部上方。","慢慢地将杠铃降低到胸部，保持肘部靠近身体。","在底部停顿片刻，然后将杠铃推回到起始位置。","重复所需的重复次数，然后换臂。"],"kind":"exercise","img":"media/0065-vtusOWT.jpg","gif":"media/0065-vtusOWT.gif","poses":"media/0065-vtusOWT-poses.jpg"},{"id":"0066","name":"barbell one arm side deadlift","name_zh":"杠铃单侧硬拉","category":"upper legs","equipment":"barbell","target":"glutes","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","lower back"],"instructions_zh":["双脚分开与肩同宽站立，一只手握住杠铃，正握。","保持背部挺直，核心肌群参与。","臀部弯曲，将杠铃向腿外侧放低，保持手臂伸直，挺胸。","尽可能降低杠铃，同时保持良好的姿势。","暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数，然后换边。"],"kind":"exercise","img":"media/0066-2DxtqHL.jpg","gif":"media/0066-2DxtqHL.gif","poses":"media/0066-2DxtqHL-poses.jpg"},{"id":"0068","name":"barbell one leg squat","name_zh":"杠铃单腿深蹲","category":"upper legs","equipment":"barbell","target":"quads","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"instructions_zh":["双脚分开与肩同宽站立，将杠铃放在上背部。","将一只脚抬离地面并向前伸展，保持与地面平行。","弯曲站立的腿，放低身体，就像坐回椅子上一样，保持挺胸、背部挺直。","降低身体直到大腿与地面平行，然后通过脚后跟推回到起始位置。","重复所需的重复次数，然后换腿并重复。"],"kind":"exercise","img":"media/0068-uKyN64F.jpg","gif":"media/0068-uKyN64F.gif","poses":"media/0068-uKyN64F-poses.jpg"},{"id":"0069","name":"barbell overhead squat","name_zh":"杠铃过顶深蹲","category":"upper legs","equipment":"barbell","target":"quads","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves","core"],"instructions_zh":["站立，双脚分开与肩同宽，脚趾稍微外翻。","宽握距握住杠铃，将其置于头顶，双臂完全伸展。","收紧核心肌群，将身体放低至蹲姿，保持胸部向上，膝盖位于脚趾上方。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0069-gfk9kD4.jpg","gif":"media/0069-gfk9kD4.gif","poses":"media/0069-gfk9kD4-poses.jpg"},{"id":"0070","name":"barbell preacher curl","name_zh":"杠铃托板弯举","category":"upper arms","equipment":"barbell","target":"biceps","muscle_group":"forearms","secondary_muscles":["forearms"],"instructions_zh":["坐在牧师凳上，上臂放在垫子上，胸部靠在支撑物上。","反手握住杠铃，握距略宽于肩宽。","保持上臂静止，呼气并将杠铃向上弯向肩膀。","在顶部暂停片刻，挤压你的二头肌。","吸气并慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0070-qOgPVf6.jpg","gif":"media/0070-qOgPVf6.gif","poses":"media/0070-qOgPVf6-poses.jpg"},{"id":"0071","name":"barbell press sit-up","name_zh":"杠铃推举卷腹","category":"waist","equipment":"barbell","target":"abs","muscle_group":"shoulders","secondary_muscles":["shoulders","chest"],"instructions_zh":["平躺在垫子上，膝盖弯曲，双脚平放在地上。","正手握住杠铃，将其放在胸前。","收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0071-wnEscH8.jpg","gif":"media/0071-wnEscH8.gif","poses":"media/0071-wnEscH8-poses.jpg"},{"id":"0074","name":"barbell rack pull","name_zh":"杠铃架上硬拉","category":"upper legs","equipment":"barbell","target":"glutes","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"instructions_zh":["将杠铃放在膝盖高度的架子上。","双脚分开与肩同宽站立，脚趾稍微向外。","弯曲臀部和膝盖，降低身体高度，正手握住杠铃，双手与肩同宽。","通过伸展臀部和膝盖、向后拉肩膀并在顶部挤压臀部来收紧核心并举起杠铃。","弯曲臀部和膝盖，将杠铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0074-za9Ni4z.jpg","gif":"media/0074-za9Ni4z.gif","poses":"media/0074-za9Ni4z-poses.jpg"},{"id":"0076","name":"barbell rear delt row","name_zh":"杠铃三角肌后束划船","category":"shoulders","equipment":"barbell","target":"delts","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids","biceps"],"instructions_zh":["站立，双脚分开与肩同宽，膝盖稍微弯曲。","正手握住杠铃，双手分开略宽于肩宽。","臀部向前弯曲，保持背部挺直，挺胸。","将杠铃拉向胸部，将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0076-S9zHIvU.jpg","gif":"media/0076-S9zHIvU.gif","poses":"media/0076-S9zHIvU-poses.jpg"},{"id":"0077","name":"barbell rear lunge v. 2","name_zh":"杠铃后箭步蹲（变式）","category":"upper legs","equipment":"barbell","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"instructions_zh":["双脚分开与肩同宽站立，将杠铃放在上背部。","右脚向后退一步，用脚掌着地。","弯曲双膝降低身体，直到左大腿与地面平行。","推动左脚跟返回到起始位置。","换另一条腿重复上述步骤。"],"kind":"exercise","img":"media/0077-62Nw60O.jpg","gif":"media/0077-62Nw60O.gif","poses":"media/0077-62Nw60O-poses.jpg"},{"id":"0078","name":"barbell rear lunge","name_zh":"杠铃后箭步蹲","category":"upper legs","equipment":"barbell","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"instructions_zh":["首先，双脚分开与肩同宽，将杠铃放在上背部。","右脚向后退一步，用脚掌着地。","弯曲双膝降低身体，直到左大腿与地面平行。","推动左脚跟返回到起始位置。","换另一条腿重复上述步骤。"],"kind":"exercise","img":"media/0078-VaP75jl.jpg","gif":"media/0078-VaP75jl.gif","poses":"media/0078-VaP75jl-poses.jpg"},{"id":"0085","name":"barbell romanian deadlift","name_zh":"杠铃罗马尼亚硬拉","category":"upper legs","equipment":"barbell","target":"glutes","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"instructions_zh":["站立，双脚分开与肩同宽，脚趾指向前方。","正手握住杠铃，双手分开略宽于肩宽。","弯曲臀部，保持背部挺直，膝盖稍微弯曲。","将杠铃向地面降低，使其靠近身体。","当你降低杠铃时，感受腿筋的拉伸。","一旦感觉到腿筋拉伸，就将臀部向前推并站直。","在动作的最高点挤压臀部。","将杠铃放回起始位置，然后重复所需的重复次数。"],"kind":"exercise","img":"media/0085-wQ2c4XD.jpg","gif":"media/0085-wQ2c4XD.gif","poses":"media/0085-wQ2c4XD-poses.jpg"},{"id":"0086","name":"barbell seated behind head military press","name_zh":"杠铃坐姿颈后推举","category":"shoulders","equipment":"barbell","target":"delts","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"instructions_zh":["坐在长凳上，背部挺直，双脚平放在地上。","正手握住杠铃，杠铃间距略宽于肩宽。","将杠铃从架子上提起，然后将其降至与肩同高，位于头后。","向上推杠铃，直到手臂完全伸展。","将杠铃降低回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0086-ngPpyRS.jpg","gif":"media/0086-ngPpyRS.gif","poses":"media/0086-ngPpyRS-poses.jpg"},{"id":"0087","name":"barbell seated bradford rocky press","name_zh":"杠铃坐姿布拉德福德推举","category":"shoulders","equipment":"barbell","target":"delts","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"instructions_zh":["坐在长凳上，背部挺直，双脚平放在地上。","正手握住杠铃，杠铃间距略宽于肩宽。","将杠铃举至肩膀高度，保持肘部稍微弯曲并指向前方。","将杠铃推过头顶，充分伸展双臂。","将杠铃降低回肩部高度，然后重复所需的重复次数。"],"kind":"exercise","img":"media/0087-0dCyly0.jpg","gif":"media/0087-0dCyly0.gif","poses":"media/0087-0dCyly0-poses.jpg"},{"id":"0091","name":"barbell seated overhead press","name_zh":"杠铃坐姿过头推举","category":"shoulders","equipment":"barbell","target":"delts","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"instructions_zh":["坐在长凳上，背部挺直，双脚平放在地上。","正手握住杠铃，杠铃间距略宽于肩宽。","将杠铃从架子上提起，并将其置于与肩同高的位置，肘部弯曲，手掌朝前。","充分伸展双臂，将杠铃压过头顶。","在顶部停顿片刻，然后慢慢将杠铃放回肩部水平。","重复所需的重复次数。"],"kind":"exercise","img":"media/0091-kTbSH9h.jpg","gif":"media/0091-kTbSH9h.gif","poses":"media/0091-kTbSH9h-poses.jpg"},{"id":"0097","name":"barbell side split squat v. 2","name_zh":"杠铃侧分腿蹲（变式）","category":"upper legs","equipment":"barbell","target":"quads","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"instructions_zh":["站立，双脚分开比肩宽，脚趾稍微向外。","将杠铃放在上背部，将其放在肩膀上。","右脚向一侧迈出一大步，保持左脚踩地。","弯曲右膝，将身体放低至蹲姿，保持挺胸、背部挺直。","推动右脚跟回到起始位置。","在另一侧重复，左脚迈出。","继续交替进行所需的重复次数。"],"kind":"exercise","img":"media/0097-HUEqZ1y.jpg","gif":"media/0097-HUEqZ1y.gif","poses":"media/0097-HUEqZ1y-poses.jpg"},{"id":"0098","name":"barbell side split squat","name_zh":"杠铃侧分腿蹲","category":"upper legs","equipment":"barbell","target":"quads","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"instructions_zh":["站立，双脚分开比肩宽，脚趾稍微向外。","将杠铃放在上背部，将其放在斜方肌上。","当你将身体降低到蹲姿时，收紧你的核心并保持胸部向上，弯曲膝盖和臀部。","当你下降时，将膝盖向两侧推出，并将体重保持在脚后跟上。","降低直到大腿与地面平行，然后通过脚后跟推回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0098-W31mMjd.jpg","gif":"media/0098-W31mMjd.gif","poses":"media/0098-W31mMjd-poses.jpg"},{"id":"0099","name":"barbell single leg split squat","name_zh":"杠铃单腿分腿蹲","category":"upper legs","equipment":"barbell","target":"quads","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"instructions_zh":["双脚分开与肩同宽站立，将杠铃放在上背部。","单腿向前迈出一大步，保持躯干直立。","弯曲前膝盖和臀部，降低身体，同时保持后腿伸直。","继续降低，直到大腿前侧与地面平行。","暂停片刻，然后推动前脚跟回到起始位置。","重复所需的重复次数，然后换腿。"],"kind":"exercise","img":"media/0099-gGNQmVt.jpg","gif":"media/0099-gGNQmVt.gif","poses":"media/0099-gGNQmVt-poses.jpg"},{"id":"0101","name":"barbell speed squat","name_zh":"杠铃快速深蹲","category":"upper legs","equipment":"barbell","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"instructions_zh":["站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在上背部，将其放在斜方肌或三角肌后束上。","收紧核心肌群，保持挺胸，同时向后和向下降低臀部，就像坐在椅子上一样。","降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。","通过脚跟发力站起来，在顶部挤压臀部。","重复所需的重复次数。"],"kind":"exercise","img":"media/0101-euI1BwR.jpg","gif":"media/0101-euI1BwR.gif","poses":"media/0101-euI1BwR-poses.jpg"},{"id":"0102","name":"barbell squat (on knees)","name_zh":"杠铃跪姿深蹲","category":"upper legs","equipment":"barbell","target":"quads","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"instructions_zh":["首先跪在地上，膝盖分开与臀部同宽，脚趾向前。","将杠铃放在肩膀上，正手握住杠铃，双手分开的距离略大于肩宽。","收紧核心并保持胸部抬起，同时弯曲膝盖慢慢降低身体，保持背部挺直。","继续降低，直到大腿与地面平行，或者尽可能低。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0102-oR7O9LW.jpg","gif":"media/0102-oR7O9LW.gif","poses":"media/0102-oR7O9LW-poses.jpg"},{"id":"0105","name":"barbell standing bradford press","name_zh":"杠铃站姿布拉德福德推举","category":"shoulders","equipment":"barbell","target":"delts","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"instructions_zh":["双脚分开与肩同宽站立，正手握住杠铃于肩前。","将杠铃推过头顶，充分伸展双臂。","将杠铃降低回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0105-dCPESfR.jpg","gif":"media/0105-dCPESfR.gif","poses":"media/0105-dCPESfR-poses.jpg"},{"id":"0116","name":"barbell straight leg deadlift","name_zh":"杠铃直腿硬拉","category":"upper legs","equipment":"barbell","target":"hamstrings","muscle_group":"glutes","secondary_muscles":["glutes","lower back"],"instructions_zh":["站立，双脚分开与肩同宽，脚趾指向前方。","正手握住杠铃，双手分开略宽于肩宽。","弯曲臀部，将杠铃放低至地面，保持背部挺直，膝盖稍微弯曲。","降低杠铃，直到感觉到腿筋拉伸。","启动腿筋和臀肌，将杠铃举回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0116-hrVQWvE.jpg","gif":"media/0116-hrVQWvE.gif","poses":"media/0116-hrVQWvE-poses.jpg"},{"id":"0117","name":"barbell sumo deadlift","name_zh":"杠铃相扑硬拉","category":"upper legs","equipment":"barbell","target":"glutes","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","lower back"],"instructions_zh":["站立，双脚分开比肩宽，脚趾朝外。","将杠铃放在您面前的地面上，位于双脚之间的中心。","弯曲膝盖，降低臀部，保持背部挺直，挺胸，用正手握法抓住杠铃。","启动你的核心并通过你的脚后跟发力，将杠铃抬离地面，同时伸展你的臀部和膝盖。","当你举起时，保持胸部挺直，背部挺直，向前推动臀部以充分锻炼臀部。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置，在整个动作过程中保持控制。","重复所需的重复次数。"],"kind":"exercise","img":"media/0117-KgI0tqW.jpg","gif":"media/0117-KgI0tqW.gif","poses":"media/0117-KgI0tqW-poses.jpg"},{"id":"0118","name":"barbell reverse grip bent over row","name_zh":"杠铃反握俯身划船","category":"back","equipment":"barbell","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["站立，双脚分开与肩同宽，膝盖稍微弯曲。","正手握住杠铃，手掌朝下，双手分开略宽于肩宽。","臀部向前弯曲，保持背部挺直，挺胸，直到躯干几乎与地板平行。","将杠铃拉向下胸部，将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0118-SzX3uzM.jpg","gif":"media/0118-SzX3uzM.gif","poses":"media/0118-SzX3uzM-poses.jpg"},{"id":"0119","name":"barbell upright row v. 2","name_zh":"杠铃直立划船（变式）","category":"shoulders","equipment":"barbell","target":"delts","muscle_group":"traps","secondary_muscles":["traps","biceps"],"instructions_zh":["双脚分开与肩同宽站立，正手握住杠铃，双手分开略宽于肩宽。","让杠铃悬挂在大腿前面，双臂完全伸展。","保持背部挺直，呼气，将杠铃向上举至下巴，用肘部引导。","在顶部停顿片刻，然后吸气，慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0119-83HoW9X.jpg","gif":"media/0119-83HoW9X.gif","poses":"media/0119-83HoW9X-poses.jpg"},{"id":"0120","name":"barbell upright row","name_zh":"杠铃直立划船","category":"shoulders","equipment":"barbell","target":"delts","muscle_group":"traps","secondary_muscles":["traps","biceps"],"instructions_zh":["双脚分开与肩同宽站立，正手握住杠铃，双手分开略宽于肩宽。","让杠铃悬挂在大腿前面，双臂完全伸展。","保持背部挺直，核心收紧，呼气，将杠铃笔直向上举向下巴，用肘部引导。","在顶部停顿片刻，然后吸气，慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0120-UDlhcO8.jpg","gif":"media/0120-UDlhcO8.gif","poses":"media/0120-UDlhcO8-poses.jpg"},{"id":"0121","name":"barbell upright row v. 3","name_zh":"杠铃直立划船（变式二）","category":"shoulders","equipment":"barbell","target":"delts","muscle_group":"traps","secondary_muscles":["traps","biceps"],"instructions_zh":["双脚分开与肩同宽站立，正手握住杠铃，双手分开略宽于肩宽。","让杠铃悬挂在大腿前面，双臂完全伸展。","保持核心收紧，背部挺直，呼气，将杠铃向上举至下巴，用肘部引导。","在顶部暂停片刻，然后吸气，慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0121-fI18Rbc.jpg","gif":"media/0121-fI18Rbc.gif","poses":"media/0121-fI18Rbc-poses.jpg"},{"id":"0122","name":"barbell wide bench press","name_zh":"杠铃宽握卧推","category":"chest","equipment":"barbell","target":"pectorals","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"instructions_zh":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","宽握距抓住杠铃，握距略宽于肩宽。","将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。","慢慢地将杠铃向胸部降低，保持肘部稍微张开。","当杠铃接触胸部时暂停片刻，然后将其推回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0122-JsKq9so.jpg","gif":"media/0122-JsKq9so.gif","poses":"media/0122-JsKq9so-poses.jpg"},{"id":"0123","name":"barbell wide-grip upright row","name_zh":"杠铃宽距直立划船","category":"shoulders","equipment":"barbell","target":"delts","muscle_group":"traps","secondary_muscles":["traps","biceps"],"instructions_zh":["双脚分开与肩同宽站立，正手握住杠铃，双手分开比肩宽。","让杠铃悬挂在大腿前面，双臂完全伸展。","保持背部挺直，呼气，将杠铃向上举至下巴，用肘部引导。","在顶部停顿片刻，然后吸气，慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0123-RgJDRR1.jpg","gif":"media/0123-RgJDRR1.gif","poses":"media/0123-RgJDRR1-poses.jpg"},{"id":"0124","name":"barbell wide squat","name_zh":"杠铃宽站距深蹲","category":"upper legs","equipment":"barbell","target":"quads","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"instructions_zh":["站立，双脚分开比肩宽，脚趾稍微向外。","将杠铃放在上背部，将其放在斜方肌或三角肌后束上。","当你下蹲时，收紧你的核心并保持胸部挺直，将臀部向后推并弯曲膝盖。","降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0124-s7HX1BY.jpg","gif":"media/0124-s7HX1BY.gif","poses":"media/0124-s7HX1BY-poses.jpg"},{"id":"0127","name":"barbell zercher squat","name_zh":"杠铃泽奇深蹲","category":"upper legs","equipment":"barbell","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"instructions_zh":["站立，双脚分开与肩同宽，脚趾稍微外翻。","将杠铃放在肘部的弯曲处，双手握住杠铃以保持稳定。","当你将臀部向后降低到蹲姿时，启动你的核心并保持胸部抬起。","保持膝盖与脚趾对齐，并将重量放在脚后跟上。","在深蹲底部暂停片刻，然后用脚后跟恢复到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0127-LSTChY9.jpg","gif":"media/0127-LSTChY9.gif","poses":"media/0127-LSTChY9-poses.jpg"},{"id":"0129","name":"bench dip (knees bent)","name_zh":"屈膝凳上臂屈伸","category":"upper arms","equipment":"body weight","target":"triceps","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"instructions_zh":["坐在长凳或椅子的边缘，双手抓住臀部旁边的边缘。","将臀部从长凳上滑下来，在身前伸直双腿，脚后跟保持在地面上。","弯曲肘部，将身体放低至地面，保持背部靠近长凳。","在底部暂停片刻，然后将自己推回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0129-RrLske5.jpg","gif":"media/0129-RrLske5.gif","poses":"media/0129-RrLske5-poses.jpg"},{"id":"0139","name":"biceps narrow pull-ups","name_zh":"窄距反手澳式划船","category":"upper arms","equipment":"body weight","target":"biceps","muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"instructions_zh":["悬挂在引体向上杆上，手掌朝向自己，双手与肩同宽。","启动你的核心并将自己拉向杠铃，专注于使用二头肌来抬起你的身体。","在最高点暂停片刻，然后慢慢降低回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0139-50BETrz.jpg","gif":"media/0139-50BETrz.gif","poses":"media/0139-50BETrz-poses.jpg"},{"id":"0140","name":"biceps pull-up","name_zh":"肱二头肌引体向上","category":"upper arms","equipment":"body weight","target":"biceps","muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"instructions_zh":["悬挂在引体向上杆上，手掌背向自己，双手与肩同宽。","启动核心肌群，弯曲肘部将自己拉起，使胸部靠近杠铃。","在动作的最高点暂停，然后慢慢降低回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0140-guT8YnS.jpg","gif":"media/0140-guT8YnS.gif","poses":"media/0140-guT8YnS-poses.jpg"},{"id":"0148","name":"cable alternate shoulder press","name_zh":"绳索交替肩推","category":"shoulders","equipment":"cable","target":"delts","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"instructions_zh":["双脚分开与肩同宽站立，并用正手握住绳索机的手柄。","将双手放在与肩同高的位置，手掌朝前。","保持核心参与并保持背部挺直。","向上并向前按下一个手柄，直到您的手臂完全伸展。","在最高点暂停片刻，然后慢慢将手柄放回起始位置。","用另一只手臂重复上述步骤。","双臂交替进行所需的重复次数。"],"kind":"exercise","img":"media/0148-KHPZL0b.jpg","gif":"media/0148-KHPZL0b.gif","poses":"media/0148-KHPZL0b-poses.jpg"},{"id":"0150","name":"cable bar lateral pulldown","name_zh":"绳索直杆高位下拉","category":"back","equipment":"cable","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"instructions_zh":["将电缆滑轮调整至较高位置并安装直杆。","面向缆绳机坐着，双脚平放在地面上，膝盖稍微弯曲。","正手握住杠铃，握距略宽于肩宽。","稍微向后倾斜，挺胸，保持下背部轻微的拱形。","将杠铃向下拉向胸部，用肘部引导并将肩胛骨挤压在一起。","在动作底部暂停片刻，然后慢慢地将杠铃返回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0150-eYnzaCm.jpg","gif":"media/0150-eYnzaCm.gif","poses":"media/0150-eYnzaCm-poses.jpg"},{"id":"0151","name":"cable bench press","name_zh":"绳索卧推","category":"chest","equipment":"cable","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["将绳索机调整至胸部高度并安装手柄。","背对机器站立，双脚与肩同宽。","正手握住手柄并向前迈一步，以在电缆中产生张力。","将双脚牢牢放在地面上并启动核心。","弯曲肘部，将双手置于肩部水平，保持肘部呈 90 度角。","向前推动手柄，将双臂完全伸展到身前。","暂停片刻，然后慢慢扭转动作，将双手放回肩部水平。","重复所需的重复次数。"],"kind":"exercise","img":"media/0151-7xI5MXA.jpg","gif":"media/0151-7xI5MXA.gif","poses":"media/0151-7xI5MXA-poses.jpg"},{"id":"0153","name":"cable cross-over lateral pulldown","name_zh":"绳索交叉高位下拉","category":"back","equipment":"cable","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"instructions_zh":["将电缆手柄连接到电缆机器两侧与肩同高的位置。","站在机器中间，双脚分开与肩同宽。","正手握住手柄并后退以在电缆中产生张力。","从臀部开始稍微向前倾，保持背部挺直，挺胸。","将手柄向下拉并穿过身体，将肩胛骨挤压在一起。","在动作底部暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0153-OQ1otBN.jpg","gif":"media/0153-OQ1otBN.gif","poses":"media/0153-OQ1otBN-poses.jpg"},{"id":"0157","name":"cable deadlift","name_zh":"绳索硬拉","category":"upper legs","equipment":"cable","target":"glutes","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","lower back"],"instructions_zh":["面对电缆机站立，双脚与肩同宽。","弯曲臀部和膝盖，降低躯干，直到背部与地面平行。","正手握住电缆手柄，保持手臂伸直，肩膀向后。","调动臀肌和腿筋来抬起拉索手柄，伸展臀部并站直。","在顶部暂停片刻，然后慢慢将缆索手柄放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0157-eGDudUV.jpg","gif":"media/0157-eGDudUV.gif","poses":"media/0157-eGDudUV-poses.jpg"},{"id":"0159","name":"cable decline seated wide-grip row","name_zh":"绳索下斜坐姿宽握划船","category":"back","equipment":"cable","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["坐在面向缆绳机的下斜长凳上，双脚牢固地放在脚踏板上。","用宽的正手握法抓住电缆附件，手掌朝下。","稍微向后倾斜，保持背部挺直，核心肌群参与。","将电缆拉向下胸部，将肩胛骨挤压在一起。","在收缩的峰值处暂停片刻，然后慢慢地将电缆释放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0159-kesXOpB.jpg","gif":"media/0159-kesXOpB.gif","poses":"media/0159-kesXOpB-poses.jpg"},{"id":"0160","name":"cable floor seated wide-grip row","name_zh":"绳索坐地宽握划船","category":"back","equipment":"cable","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["坐在地板上，双腿伸直，背部挺直。","将缆绳手柄连接到低滑轮上，并将缆绳机放在您身后。","正手宽握握住手柄，手掌朝下。","稍微向后倾斜，保持背部挺直，挺胸。","将手柄拉向腰部，将肩胛骨挤压在一起。","在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0160-veXwo0D.jpg","gif":"media/0160-veXwo0D.gif","poses":"media/0160-veXwo0D-poses.jpg"},{"id":"0167","name":"cable high row (kneeling)","name_zh":"绳索跪姿高位划船","category":"back","equipment":"cable","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"instructions_zh":["将直杆连接到胸部高度的缆绳机上。","跪在缆绳机前，用正握方式抓住杠铃，双手与肩同宽。","坐在脚后跟上，保持背部挺直，核心肌群参与。","将杠铃拉向上腹部，将肩胛骨挤压在一起。","在动作的最高点暂停片刻，然后慢慢松开杠铃回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0167-ZSJNetl.jpg","gif":"media/0167-ZSJNetl.gif","poses":"media/0167-ZSJNetl-poses.jpg"},{"id":"0169","name":"cable incline bench press","name_zh":"绳索上斜卧推","category":"chest","equipment":"cable","target":"pectorals","muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"instructions_zh":["将长凳调整至 45 度倾斜。","将电缆手柄连接到高滑轮上。","坐在长凳上，面向电缆机，双脚平放在地面上。","正手握住手柄，并将其拉至肩部高度。","向前和向上推动手柄，直到手臂完全伸展。","暂停片刻，然后慢慢将手柄放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0169-Vh0GsK4.jpg","gif":"media/0169-Vh0GsK4.gif","poses":"media/0169-Vh0GsK4-poses.jpg"},{"id":"0172","name":"cable incline pushdown","name_zh":"绳索上斜下压","category":"back","equipment":"cable","target":"lats","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["将直杆连接到高滑轮电缆机上。","背对机器站立，双脚与肩同宽。","正手握住杠铃，双手距离略宽于肩宽。","稍微向前倾并保持背部挺直。","伸展肘部，将杠铃向下拉向大腿。","在底部暂停片刻，然后慢慢地将杠铃返回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0172-1PK5Uo3.jpg","gif":"media/0172-1PK5Uo3.gif","poses":"media/0172-1PK5Uo3-poses.jpg"},{"id":"0174","name":"cable judo flip","name_zh":"绳索柔道翻","category":"waist","equipment":"cable","target":"abs","muscle_group":"obliques","secondary_muscles":["obliques","shoulders"],"instructions_zh":["面对电缆机站立，双脚与肩同宽。","用双手握住电缆手柄，使其与胸部齐平，手掌朝下。","启动你的核心并将你的躯干向右旋转，将电缆拉过你的身体。","当你旋转时，转动后脚并让臀部自然旋转。","充分伸展双臂，将绳索手柄翻转到肩膀上来完成动作。","通过反向运动返回起始位置，将躯干旋转回中心。","在另一侧重复该动作。","继续交替进行所需的重复次数。"],"kind":"exercise","img":"media/0174-MvQPqVW.jpg","gif":"media/0174-MvQPqVW.gif","poses":"media/0174-MvQPqVW-poses.jpg"},{"id":"0177","name":"cable lateral pulldown (with rope attachment)","name_zh":"绳索绳把高位下拉","category":"back","equipment":"cable","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["将绳索附件连接到电缆机的高位置。","面向机器站立，双脚分开与肩同宽。","正手握住绳子，手掌相对。","保持背部挺直并稍微向后倾斜。","将绳子向下拉向身体两侧，将肩胛骨挤压在一起。","在动作的底部停顿片刻。","慢慢释放张力，让绳子回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0177-CuaWCmC.jpg","gif":"media/0177-CuaWCmC.gif","poses":"media/0177-CuaWCmC-poses.jpg"},{"id":"0178","name":"cable lateral raise","name_zh":"绳索侧平举","category":"shoulders","equipment":"cable","target":"delts","muscle_group":"traps","secondary_muscles":["traps","triceps"],"instructions_zh":["双脚分开与肩同宽站立，并用正手握住电缆手柄。","保持双臂伸直，核心肌群参与。","将手臂向两侧举起，直到与地板平行。","在顶部暂停片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0178-goJ6ezq.jpg","gif":"media/0178-goJ6ezq.gif","poses":"media/0178-goJ6ezq-poses.jpg"},{"id":"0180","name":"cable low seated row","name_zh":"绳索低位坐姿划船","category":"back","equipment":"cable","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["坐在机器上，双脚平放在脚踏板上，膝盖稍微弯曲。","正手握住手柄，手掌朝下。","保持背部挺直，稍微向前倾斜，肘部保持轻微弯曲。","将手柄拉向身体，将肩胛骨挤压在一起。","在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0180-hvV79Si.jpg","gif":"media/0180-hvV79Si.gif","poses":"media/0180-hvV79Si-poses.jpg"},{"id":"0189","name":"cable one arm bent over row","name_zh":"绳索单臂俯身划船","category":"back","equipment":"cable","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["面向缆绳机站立，双脚与肩同宽。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","用一只手抓住电缆手柄，手掌朝内，然后完全伸展手臂。","将电缆手柄拉向身体，保持肘部靠近身体一侧，直到手到达下胸部。","暂停片刻，然后慢慢将手臂伸回起始位置。","重复所需的重复次数，然后换边。"],"kind":"exercise","img":"media/0189-EIsE3u8.jpg","gif":"media/0189-EIsE3u8.gif","poses":"media/0189-EIsE3u8-poses.jpg"},{"id":"0193","name":"cable one arm straight back high row (kneeling)","name_zh":"绳索单臂跪姿直背高位划船","category":"back","equipment":"cable","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"instructions_zh":["将手柄连接到腰部高度的缆绳机上。","面向电缆机跪下，用一只手抓住手柄。","保持背部挺直，核心肌群参与。","将手柄拉向胸部，将肩胛骨挤压在一起。","在动作的最高点停顿片刻。","慢慢松开手柄回到起始位置。","重复所需的重复次数。","换边并用另一只手臂重复练习。"],"kind":"exercise","img":"media/0193-WrYPP2g.jpg","gif":"media/0193-WrYPP2g.gif","poses":"media/0193-WrYPP2g-poses.jpg"},{"id":"0196","name":"cable pull through (with rope)","name_zh":"绳索胯下上拉","category":"upper legs","equipment":"cable","target":"glutes","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"instructions_zh":["背对缆绳机站立，双脚与肩同宽。","双手抓住绳索附件并向前迈一步，在绳索中产生张力。","弯曲臀部并降低上身直至与地面平行，保持背部挺直。","启动臀肌和腿筋，将身体拉回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0196-OM46QHm.jpg","gif":"media/0196-OM46QHm.gif","poses":"media/0196-OM46QHm-poses.jpg"},{"id":"0197","name":"cable pulldown (pro lat bar)","name_zh":"绳索宽杆下拉","category":"back","equipment":"cable","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["调整座椅高度，使大腿与地面平行，双脚平放在地板上。","正手握住背阔肌杠铃，握距略宽于肩宽。","坐下来，稍微向后倾斜，保持挺胸、背部挺直。","将杠铃向下拉向胸部，将肩胛骨挤压在一起。","在动作底部暂停片刻，然后慢慢将杠铃释放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0197-qdRxqCj.jpg","gif":"media/0197-qdRxqCj.gif","poses":"media/0197-qdRxqCj-poses.jpg"},{"id":"0198","name":"cable pulldown","name_zh":"绳索高位下拉","category":"back","equipment":"cable","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["调整拉索下拉机，使座椅处于舒适的高度并固定护膝。","坐在座位上，背部挺直，双脚平放在地面上。","正手握住电缆杆，握距略宽于肩宽。","稍微向后倾斜并启动你的核心。","将电缆杆向下拉向胸部，将肩胛骨挤压在一起。","在动作底部暂停片刻，然后慢慢松开杠铃回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0198-RVwzP10.jpg","gif":"media/0198-RVwzP10.gif","poses":"media/0198-RVwzP10-poses.jpg"},{"id":"0199","name":"cable pushdown (straight arm) v. 2","name_zh":"绳索直臂下压（变式）","category":"back","equipment":"cable","target":"lats","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["将直杆连接到高滑轮电缆机上。","面向机器站立，双脚分开与肩同宽，膝盖稍微弯曲。","正手握住杠铃，保持手臂伸直，手掌朝下。","呼气时，收紧核心并保持背部挺直，并将杠铃向下推向大腿。","在底部暂停片刻，然后一边吸气，一边慢慢地将杠铃返回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0199-PskORrA.jpg","gif":"media/0199-PskORrA.gif","poses":"media/0199-PskORrA-poses.jpg"},{"id":"0200","name":"cable pushdown (with rope attachment)","name_zh":"绳索绳把下压","category":"upper arms","equipment":"cable","target":"triceps","muscle_group":"forearms","secondary_muscles":["forearms"],"instructions_zh":["将绳索附件连接到缆绳机上的高滑轮上。","面向机器站立，双脚分开与肩同宽，膝盖稍微弯曲。","正手握住绳子，手掌相对。","在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。","呼气并伸展肘部将绳子向下推，直到手臂完全伸展。","暂停片刻，然后吸气，并让肘部弯曲，慢慢回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0200-dU605di.jpg","gif":"media/0200-dU605di.gif","poses":"media/0200-dU605di-poses.jpg"},{"id":"0201","name":"cable pushdown","name_zh":"绳索下压","category":"upper arms","equipment":"cable","target":"triceps","muscle_group":"forearms","secondary_muscles":["forearms"],"instructions_zh":["将直杆连接到高滑轮电缆机上。","面向机器站立，双脚分开与肩同宽，膝盖稍微弯曲。","正手握住杠铃，双手与肩同宽。","保持肘部靠近身体两侧，上臂保持静止。","呼气并将杠铃向下推，直到肘部完全伸展。","暂停片刻，然后吸气，慢慢地将杠铃返回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0201-3ZflifB.jpg","gif":"media/0201-3ZflifB.gif","poses":"media/0201-3ZflifB-poses.jpg"},{"id":"0202","name":"cable rear delt row (stirrups)","name_zh":"绳索后束划船（环形把手）","category":"shoulders","equipment":"cable","target":"delts","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids","biceps"],"instructions_zh":["将马镫手柄连接到低电缆滑轮上，面向机器站立。","左手抓住手柄，右脚后退一步，身体保持一个轻微的角度。","稍微弯曲膝盖，髋部向前转动，保持背部挺直，核心肌群参与。","左臂伸展，手掌朝下，通过缩回肩胛骨将手柄拉向胸部。","在动作的最高点暂停片刻，挤压肩胛骨。","慢慢地将手柄释放回起始位置，然后重复所需的重复次数。","换边并用右臂重复练习。"],"kind":"exercise","img":"media/0202-yUdIGNs.jpg","gif":"media/0202-yUdIGNs.gif","poses":"media/0202-yUdIGNs-poses.jpg"},{"id":"0203","name":"cable rear delt row (with rope)","name_zh":"绳索后束划船（绳把）","category":"shoulders","equipment":"cable","target":"delts","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids","biceps"],"instructions_zh":["将绳索手柄连接到低滑轮电缆机器上。","面向机器站立，双脚分开与肩同宽。","正手握住绳索手柄，手掌相对。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","保持肘部稍微弯曲，将绳子拉向胸部，将肩胛骨挤压在一起。","在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0203-wqNPGCg.jpg","gif":"media/0203-wqNPGCg.gif","poses":"media/0203-wqNPGCg-poses.jpg"},{"id":"0205","name":"cable rear pulldown","name_zh":"绳索颈后下拉","category":"back","equipment":"cable","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"instructions_zh":["调整拉索机，使滑轮处于最高位置。","面向机器坐着，双脚平放在地面上，膝盖稍微弯曲。","正手握住电缆附件，双手之间的距离略大于肩宽。","稍微向后倾斜，保持背部挺直，挺胸。","将电缆附件向下拉向胸部，将肩胛骨挤压在一起。","在动作底部停顿片刻，然后慢慢松开绳索回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0205-SpsOSXk.jpg","gif":"media/0205-SpsOSXk.gif","poses":"media/0205-SpsOSXk-poses.jpg"},{"id":"0207","name":"cable reverse-grip pushdown","name_zh":"绳索反握下压","category":"upper arms","equipment":"cable","target":"triceps","muscle_group":"forearms","secondary_muscles":["forearms"],"instructions_zh":["将直杆连接到高滑轮电缆机上。","面向机器站立，双脚分开与肩同宽。","反手握住杠铃，手掌朝上，双手与肩同宽。","在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。","使用三头肌，将杠铃向下推，直到手臂完全伸展并且三头肌收缩。","暂停片刻，然后慢慢地将杠铃返回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0207-VjYliFZ.jpg","gif":"media/0207-VjYliFZ.gif","poses":"media/0207-VjYliFZ-poses.jpg"},{"id":"0208","name":"cable reverse-grip straight back seated high row","name_zh":"绳索反握直背坐姿高位划船","category":"back","equipment":"cable","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["坐在面向电缆机的座位上，双脚平放在地板上。","用手握住电缆附件，手掌朝上，双手与肩同宽。","保持背部挺直，并从臀部稍微向前倾斜。","通过缩回肩胛骨并挤压背部肌肉，将电缆拉向躯干。","在收缩的峰值处暂停片刻，然后慢慢地将电缆释放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0208-PNtsX17.jpg","gif":"media/0208-PNtsX17.gif","poses":"media/0208-PNtsX17-poses.jpg"},{"id":"0210","name":"cable reverse wrist curl","name_zh":"绳索反握腕弯举","category":"lower arms","equipment":"cable","target":"forearms","muscle_group":"forearms","secondary_muscles":["forearms","wrists"],"instructions_zh":["将电缆连接到低滑轮上，然后坐在面向电缆机的长凳上。","正手握住电缆手柄，手掌朝下。","将前臂放在大腿上，手腕悬在边缘上。","保持前臂静止，呼气并尽可能向上弯曲手腕。","在顶部暂停片刻，然后吸气并慢慢将手腕放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0210-eYmsEPR.jpg","gif":"media/0210-eYmsEPR.gif","poses":"media/0210-eYmsEPR-poses.jpg"},{"id":"0213","name":"cable seated high row (v-bar)","name_zh":"绳索坐姿高位划船（V杆）","category":"back","equipment":"cable","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"instructions_zh":["坐在缆绳机上，双脚平放在地板上，膝盖稍微弯曲。","正手握住 V 形杆附件，手掌相对，双手与肩同宽。","保持背部挺直，并从臀部稍微向前倾斜。","通过收缩肩胛骨并挤压背部肌肉，将 V 形杆拉向躯干。","在收缩的顶峰停顿片刻，然后慢慢释放张力，回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0213-pwt0pnM.jpg","gif":"media/0213-pwt0pnM.gif","poses":"media/0213-pwt0pnM-poses.jpg"},{"id":"0214","name":"cable seated one arm alternate row","name_zh":"绳索坐姿单臂交替划船","category":"back","equipment":"cable","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["坐在长凳上，面对缆绳机，双脚平放在地面上，膝盖稍微弯曲。","用一只手抓住手柄，并将手臂完全伸展到身前。","将手柄拉向身体，缩回肩胛骨并保持肘部靠近身体两侧。","在动作的最高点暂停片刻，挤压背部肌肉。","慢慢松开手柄回到起始位置。","用另一只手臂重复上述步骤。","双臂交替进行所需的重复次数。"],"kind":"exercise","img":"media/0214-vpp9Ku2.jpg","gif":"media/0214-vpp9Ku2.gif","poses":"media/0214-vpp9Ku2-poses.jpg"},{"id":"0218","name":"cable seated wide-grip row","name_zh":"绳索坐姿宽握划船","category":"back","equipment":"cable","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["坐在电缆划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。","正手宽握握住手柄，手掌朝下。","保持背部挺直，并从臀部稍微向前倾斜。","将手柄拉向下胸部，将肩胛骨挤压在一起。","在收缩高峰时暂停片刻。","慢慢松开手柄回到起始位置，充分伸展双臂。","重复所需的重复次数。"],"kind":"exercise","img":"media/0218-qcY50ZD.jpg","gif":"media/0218-qcY50ZD.gif","poses":"media/0218-qcY50ZD-poses.jpg"},{"id":"0219","name":"cable shoulder press","name_zh":"绳索肩推","category":"shoulders","equipment":"cable","target":"delts","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"instructions_zh":["调整绳索机，使手柄位于肩部高度。","背对机器站立，双脚与肩同宽。","正手握住手柄，将其提升至肩部水平，肘部弯曲并指向外侧。","向上按压手柄，直到手臂完全伸过头顶。","在顶部暂停片刻，然后慢慢将手柄放回至肩部水平。","重复所需的重复次数。"],"kind":"exercise","img":"media/0219-PzQanLE.jpg","gif":"media/0219-PzQanLE.gif","poses":"media/0219-PzQanLE-poses.jpg"},{"id":"0224","name":"cable standing back wrist curl","name_zh":"绳索站姿背后腕弯举","category":"lower arms","equipment":"cable","target":"forearms","muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"instructions_zh":["面向缆绳机站立，双脚与肩同宽。","正手握住电缆手柄，手掌朝下。","保持手臂伸直，肘部靠近身体两侧。","慢慢向上弯曲手腕，将电缆手柄拉向身体。","在顶部暂停片刻，然后慢慢将拉索手柄放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0224-VhX2JdE.jpg","gif":"media/0224-VhX2JdE.gif"},{"id":"0230","name":"cable standing lift","name_zh":"绳索站姿提拉","category":"waist","equipment":"cable","target":"abs","muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"instructions_zh":["面对电缆机站立，双脚与肩同宽。","双手握住电缆手柄并将其置于腰部高度。","在整个练习过程中启动核心并保持背部挺直。","保持手臂伸直，呼气并将电缆手柄向另一侧的肩膀向上提起，同时旋转躯干。","在顶部暂停片刻，然后吸气并慢慢将拉索手柄放回起始位置。","重复所需的重复次数，然后换边。"],"kind":"exercise","img":"media/0230-qFpAkpP.jpg","gif":"media/0230-qFpAkpP.gif","poses":"media/0230-qFpAkpP-poses.jpg"},{"id":"0232","name":"cable standing pulldown (with rope)","name_zh":"绳索站姿下拉（绳把）","category":"upper arms","equipment":"cable","target":"biceps","muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"instructions_zh":["将绳索连接到最高设置的缆绳机上。","面向机器站立，双脚分开与肩同宽。","正手握住绳子，手掌朝下。","在整个练习过程中保持背部挺直并保持核心参与。","将绳子向下拉向大腿，挤压二头肌。","在底部停顿片刻，然后慢慢地将绳子放回原位。","重复所需的重复次数。"],"kind":"exercise","img":"media/0232-CvPn9WV.jpg","gif":"media/0232-CvPn9WV.gif","poses":"media/0232-CvPn9WV-poses.jpg"},{"id":"0233","name":"cable standing rear delt row (with rope)","name_zh":"绳索站姿后束划船（绳把）","category":"shoulders","equipment":"cable","target":"delts","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids","biceps"],"instructions_zh":["面向缆绳机站立，双脚与肩同宽。","用双手握住电缆附件，手掌相对，然后后退以在电缆中产生张力。","保持背部挺直，核心肌群参与。","将电缆拉向您的身体，将肩胛骨挤压在一起。","在运动的最高点停顿片刻，然后慢慢松开绳索回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0233-ZfyAGhK.jpg","gif":"media/0233-ZfyAGhK.gif","poses":"media/0233-ZfyAGhK-poses.jpg"},{"id":"0234","name":"cable standing row (v-bar)","name_zh":"绳索站姿划船（V杆）","category":"back","equipment":"cable","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"instructions_zh":["面对电缆机站立，双脚与肩同宽。","正手握住 V 形杆附件，手掌朝下。","保持背部挺直，核心肌群参与。","将 V 形杆拉向身体，将肩胛骨挤压在一起。","在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0234-4f8RXP8.jpg","gif":"media/0234-4f8RXP8.gif","poses":"media/0234-4f8RXP8-poses.jpg"},{"id":"0237","name":"cable straight arm pulldown (with rope)","name_zh":"绳索直臂下拉（绳把）","category":"back","equipment":"cable","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["将绳索连接到最高设置的缆绳机上。","面向机器站立，双脚分开与肩同宽。","双手抓住绳子，掌心朝下。","将手臂完全伸展到身前，保持肘部稍微弯曲。","收紧背阔肌，慢慢地将绳子向下拉向大腿，保持手臂伸直。","在底部停顿片刻，然后慢慢释放张力，回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0237-DT14T9T.jpg","gif":"media/0237-DT14T9T.gif","poses":"media/0237-DT14T9T-poses.jpg"},{"id":"0238","name":"cable straight arm pulldown","name_zh":"绳索直臂下拉","category":"back","equipment":"cable","target":"lats","muscle_group":"shoulders","secondary_muscles":["shoulders","biceps"],"instructions_zh":["将直杆连接到缆绳机的高滑轮上。","面向机器站立，双脚分开与肩同宽。","正手握住杠铃，保持手臂伸直，手掌朝下。","收紧背阔肌并将杠铃向下拉向大腿，在整个运动过程中保持手臂伸直。","在底部暂停片刻，然后慢慢地将杠铃返回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0238-x69MAlq.jpg","gif":"media/0238-x69MAlq.gif","poses":"media/0238-x69MAlq-poses.jpg"},{"id":"0239","name":"cable straight back seated row","name_zh":"绳索直背坐姿划船","category":"back","equipment":"cable","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","forearms","shoulders"],"instructions_zh":["坐在电缆划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。","正手握住电缆手柄，手掌朝下。","保持背部挺直，并从臀部稍微向前倾斜。","将电缆手柄拉向身体，将肩胛骨挤压在一起。","在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0239-Tq6gbK6.jpg","gif":"media/0239-Tq6gbK6.gif","poses":"media/0239-Tq6gbK6-poses.jpg"},{"id":"0241","name":"cable triceps pushdown (v-bar)","name_zh":"绳索肱三头下压（V杆）","category":"upper arms","equipment":"cable","target":"triceps","muscle_group":"forearms","secondary_muscles":["forearms"],"instructions_zh":["在最高设置下将 V 形杆附件连接到电缆机上。","面对电缆机站立，双脚与肩同宽。","正手握住 V 形杆，手掌朝下，双手与肩同宽。","在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。","收紧三头肌并呼气，同时向下推 V 形杆，直到手臂完全伸展。","在动作的底部暂停片刻，挤压你的三头肌。","吸气，同时缓慢地将 V 形杆返回到起始位置，保持控制。","重复所需的重复次数。"],"kind":"exercise","img":"media/0241-gAwDzB3.jpg","gif":"media/0241-gAwDzB3.gif","poses":"media/0241-gAwDzB3-poses.jpg"},{"id":"0245","name":"cable underhand pulldown","name_zh":"绳索反手高位下拉","category":"back","equipment":"cable","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["调整缆绳机，使下拉杆位于您头部上方的高度。","坐在座椅上，用反手抓住下拉杆，双手分开的距离略大于肩宽。","保持背部挺直并稍微向后倾斜。","将杠铃向下拉向胸部，将肩胛骨挤压在一起。","在动作底部暂停片刻，然后慢慢将杠铃释放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0245-xBYcQHj.jpg","gif":"media/0245-xBYcQHj.gif","poses":"media/0245-xBYcQHj-poses.jpg"},{"id":"0246","name":"cable upright row","name_zh":"绳索直立划船","category":"shoulders","equipment":"cable","target":"delts","muscle_group":"traps","secondary_muscles":["traps","biceps"],"instructions_zh":["双脚分开与肩同宽站立，膝盖稍微弯曲，并用正手握住电缆附件。","在整个练习过程中保持背部挺直，核心肌群参与其中。","用肘部引导，将电缆附件笔直向上拉向下巴。","在顶部暂停片刻，将肩胛骨挤压在一起。","缓慢地将电缆附件放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0246-cALKspW.jpg","gif":"media/0246-cALKspW.gif","poses":"media/0246-cALKspW-poses.jpg"},{"id":"0248","name":"cambered bar lying row","name_zh":"曲杆仰卧划船","category":"back","equipment":"barbell","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["在地板上放一个杠铃，脸朝下躺在长凳上，胸部刚好离开边缘。","向下伸手，正手抓住杠铃，距离略宽于肩宽。","双腿伸直，双脚着地，伸展双臂，将杠铃提离地面。","将杠铃拉向胸部，将肩胛骨挤压在一起。","将杠铃放回起始位置，然后重复所需的重复次数。"],"kind":"exercise","img":"media/0248-R5swFnc.jpg","gif":"media/0248-R5swFnc.gif","poses":"media/0248-R5swFnc-poses.jpg"},{"id":"0251","name":"chest dip","name_zh":"双杠臂屈伸（下胸）","category":"chest","equipment":"body weight","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["将自己置于双杠上，双臂完全伸展，身体伸直。","弯曲肘部，降低身体，直到肩膀低于肘部。","伸直手臂，将自己推回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0251-9WTm7dq.jpg","gif":"media/0251-9WTm7dq.gif","poses":"media/0251-9WTm7dq-poses.jpg"},{"id":"0253","name":"chin-ups (narrow parallel grip)","name_zh":"窄距平行握引体向上","category":"back","equipment":"body weight","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["用狭窄的平行握距悬挂在引体向上杆上，手掌朝向您。","收紧背部肌肉，将身体拉向杠铃杆，保持肘部靠近身体。","继续拉，直到下巴位于杠铃上方。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0253-G70mEAJ.jpg","gif":"media/0253-G70mEAJ.gif","poses":"media/0253-G70mEAJ-poses.jpg"},{"id":"0258","name":"clock push-up","name_zh":"时钟俯卧撑","category":"chest","equipment":"body weight","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"instructions_zh":["从高平板支撑位置开始，双手直接放在肩膀下方，身体呈一条直线。","弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。","当你下降时，将你的身体向左旋转，将你的左臂伸直到侧面。","向上推回到起始位置，同时将身体旋转到中心。","重复俯卧撑，这次将身体向右旋转，并将右臂向侧面伸出。","每次重复时继续交替进行。"],"kind":"exercise","img":"media/0258-CMAxnsG.jpg","gif":"media/0258-CMAxnsG.gif","poses":"media/0258-CMAxnsG-poses.jpg"},{"id":"0259","name":"close-grip push-up","name_zh":"窄距俯卧撑","category":"upper arms","equipment":"body weight","target":"triceps","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"instructions_zh":["从高位平板支撑开始，双手并拢，位于肩膀正下方。","收紧核心，将身体降低到地面，保持肘部靠近身体两侧。","推动手掌以伸展手臂并返回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0259-x6KpKpq.jpg","gif":"media/0259-x6KpKpq.gif","poses":"media/0259-x6KpKpq-poses.jpg"},{"id":"0279","name":"decline push-up","name_zh":"下斜俯卧撑","category":"chest","equipment":"body weight","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["将双手放在地面上，距离略宽于肩宽，双脚放在稳定的表面上。","保持身体从头到脚呈一条直线，锻炼核心肌肉。","弯曲肘部，使胸部靠近地面，使胸部靠近地面。","推动手掌以伸展手臂并返回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0279-i5cEhka.jpg","gif":"media/0279-i5cEhka.gif","poses":"media/0279-i5cEhka-poses.jpg"},{"id":"0283","name":"diamond push-up","name_zh":"钻石俯卧撑","category":"upper arms","equipment":"body weight","target":"triceps","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"instructions_zh":["从高位平板支撑开始，双手并拢，拇指和食指形成菱形。","让你的身体从头到脚保持一条直线，锻炼你的核心和臀部。","将胸部降低至双手形成的菱形，保持肘部靠近身体。","在底部暂停片刻，然后将自己推回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0283-soIB2rj.jpg","gif":"media/0283-soIB2rj.gif","poses":"media/0283-soIB2rj-poses.jpg"},{"id":"0285","name":"dumbbell alternate biceps curl","name_zh":"哑铃交替弯举","category":"upper arms","equipment":"dumbbell","target":"biceps","muscle_group":"forearms","secondary_muscles":["forearms"],"instructions_zh":["站直，双手各握一个哑铃，手掌朝前，双臂完全伸展。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将哑铃放回起始位置。","重复所需的重复次数，交替手臂。"],"kind":"exercise","img":"media/0285-BU15nH4.jpg","gif":"media/0285-BU15nH4.gif","poses":"media/0285-BU15nH4-poses.jpg"},{"id":"0286","name":"dumbbell alternate side press","name_zh":"哑铃交替侧推","category":"shoulders","equipment":"dumbbell","target":"delts","muscle_group":"triceps","secondary_muscles":["triceps","core"],"instructions_zh":["双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高。","将一个哑铃推过头顶，同时将另一个哑铃保持在与肩同高的位置。","将按下的哑铃放回肩部高度，同时将另一个哑铃压过头顶。","继续交替进行所需的重复次数。"],"kind":"exercise","img":"media/0286-izMnLqz.jpg","gif":"media/0286-izMnLqz.gif","poses":"media/0286-izMnLqz-poses.jpg"},{"id":"0287","name":"dumbbell arnold press v. 2","name_zh":"哑铃阿诺德推举（变式）","category":"shoulders","equipment":"dumbbell","target":"delts","muscle_group":"triceps","secondary_muscles":["triceps","upper chest"],"instructions_zh":["坐在有背部支撑的长凳上，双手各握一个哑铃，与肩同高，手掌朝向身体，肘部弯曲。","向上推哑铃，直到手臂完全伸展，手掌朝前。","抬起时旋转手腕，使手掌在动作的最高点朝前。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0287-eOrFCnx.jpg","gif":"media/0287-eOrFCnx.gif","poses":"media/0287-eOrFCnx-poses.jpg"},{"id":"0289","name":"dumbbell bench press","name_zh":"哑铃卧推","category":"chest","equipment":"dumbbell","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","双手各握一个哑铃，手掌朝前，双臂伸至胸部上方。","慢慢地将哑铃降低到胸部两侧，保持肘部呈 90 度角。","暂停片刻，然后将哑铃推回起始位置，完全伸展双臂。","重复所需的重复次数。"],"kind":"exercise","img":"media/0289-SpYC0Kp.jpg","gif":"media/0289-SpYC0Kp.gif","poses":"media/0289-SpYC0Kp-poses.jpg"},{"id":"0290","name":"dumbbell bench seated press","name_zh":"哑铃坐姿推举","category":"shoulders","equipment":"dumbbell","target":"delts","muscle_group":"triceps","secondary_muscles":["triceps","chest"],"instructions_zh":["坐在长凳上，每只手各拿一个哑铃，放在大腿上。","向后倾斜，将哑铃放在胸部两侧，手掌朝前。","向上推哑铃，直到手臂完全伸展。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0290-3d7wHyd.jpg","gif":"media/0290-3d7wHyd.gif","poses":"media/0290-3d7wHyd-poses.jpg"},{"id":"0291","name":"dumbbell bench squat","name_zh":"哑铃凳上深蹲","category":"upper legs","equipment":"dumbbell","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"instructions_zh":["将哑铃放在长凳前的地面上。","背对长凳站立，双脚与肩同宽。","弯曲膝盖和臀部，将自己降低到长凳上，保持胸部挺直，背部挺直。","一旦你的臀部接触到长凳，就用脚后跟站起来，回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0291-mnzcrIB.jpg","gif":"media/0291-mnzcrIB.gif","poses":"media/0291-mnzcrIB-poses.jpg"},{"id":"0292","name":"dumbbell one arm bent-over row","name_zh":"哑铃单臂俯身划船","category":"back","equipment":"dumbbell","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["双脚分开与肩同宽站立，一手握住哑铃，手掌朝向身体。","稍微弯曲膝盖，髋部向前转动，保持背部挺直，核心肌群参与。","让哑铃垂直垂向地板，手臂完全伸展。","将哑铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换边。"],"kind":"exercise","img":"media/0292-C0MA9bC.jpg","gif":"media/0292-C0MA9bC.gif","poses":"media/0292-C0MA9bC-poses.jpg"},{"id":"0293","name":"dumbbell bent over row","name_zh":"哑铃俯身划船","category":"back","equipment":"dumbbell","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["双脚分开与肩同宽站立，膝盖稍微弯曲，双手各握一个哑铃，手掌朝向身体。","臀部向前弯曲，保持背部挺直，核心肌群参与。","让你的手臂垂直垂向地板，肘部稍微弯曲。","将哑铃拉向胸部，将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0293-BJ0Hz5L.jpg","gif":"media/0293-BJ0Hz5L.gif","poses":"media/0293-BJ0Hz5L-poses.jpg"},{"id":"0294","name":"dumbbell biceps curl","name_zh":"哑铃弯举","category":"upper arms","equipment":"dumbbell","target":"biceps","muscle_group":"forearms","secondary_muscles":["forearms"],"instructions_zh":["站直，双手各握一个哑铃，手掌朝前，双臂完全伸展。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将哑铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0294-NbVPDMW.jpg","gif":"media/0294-NbVPDMW.gif","poses":"media/0294-NbVPDMW-poses.jpg"},{"id":"0295","name":"dumbbell clean","name_zh":"哑铃高翻","category":"upper legs","equipment":"dumbbell","target":"glutes","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","calves"],"instructions_zh":["双脚分开与肩同宽站立，双手各握一个哑铃，正握。","弯曲膝盖，降低臀部至下蹲位置，保持背部挺直，挺胸。","爆发性地伸展臀部和膝盖，通过脚后跟跳离地面。","当你跳跃时，耸肩并将哑铃拉向你的肩膀，保持它们靠近你的身体。","在与肩同高的位置抓住哑铃，肘部向前，手掌朝上。","通过反向运动将哑铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0295-7Hg55JG.jpg","gif":"media/0295-7Hg55JG.gif","poses":"media/0295-7Hg55JG-poses.jpg"},{"id":"0296","name":"dumbbell close-grip press","name_zh":"哑铃窄握推举","category":"upper arms","equipment":"dumbbell","target":"triceps","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"instructions_zh":["坐在平坦的长凳上，每只手各拿一个哑铃，放在大腿上。","用你的大腿帮助举起哑铃，一次举起一个哑铃，这样你就可以将它们保持在与肩同宽的位置。","一旦与肩同宽，向前旋转手腕，使手掌背向自己。这将是您的起始位置。","当你吸气时，慢慢地将哑铃降低到你的身边，直到它们与你的胸部齐平。","呼气时，用三头肌将哑铃举回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0296-RxayqAZ.jpg","gif":"media/0296-RxayqAZ.gif","poses":"media/0296-RxayqAZ-poses.jpg"},{"id":"0297","name":"dumbbell concentration curl","name_zh":"哑铃集中弯举","category":"upper arms","equipment":"dumbbell","target":"biceps","muscle_group":"forearms","secondary_muscles":["forearms"],"instructions_zh":["坐在长凳上，双腿分开，一只手拿着哑铃，肘部放在大腿内侧。","完全伸展手臂并用反手握住哑铃。","保持上臂静止，呼气并将重量向上弯向肩膀，同时收缩二头肌。","继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气，慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换臂。"],"kind":"exercise","img":"media/0297-gvsWLQw.jpg","gif":"media/0297-gvsWLQw.gif","poses":"media/0297-gvsWLQw-poses.jpg"},{"id":"0299","name":"dumbbell cuban press","name_zh":"哑铃古巴推举","category":"shoulders","equipment":"dumbbell","target":"delts","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"instructions_zh":["双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高，手掌朝下。","保持核心收紧，肘部稍微弯曲，将哑铃向上举过头顶，直到手臂完全伸展。","旋转手腕，使手掌朝前。","慢慢地将哑铃放回起始位置，同时将手腕旋转回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0299-QfAKy1G.jpg","gif":"media/0299-QfAKy1G.gif","poses":"media/0299-QfAKy1G-poses.jpg"},{"id":"0300","name":"dumbbell deadlift","name_zh":"哑铃硬拉","category":"upper legs","equipment":"dumbbell","target":"glutes","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"instructions_zh":["双脚分开与肩同宽站立，脚趾指向前方。","双手各握一个哑铃，手掌朝向身体，手臂向下伸展。","弯曲臀部和膝盖，将哑铃向地面降低，同时保持背部挺直。","脚跟用力，伸展臀部和膝盖，将哑铃举回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0300-nUwVh7b.jpg","gif":"media/0300-nUwVh7b.gif","poses":"media/0300-nUwVh7b-poses.jpg"},{"id":"0301","name":"dumbbell decline bench press","name_zh":"哑铃下斜卧推","category":"chest","equipment":"dumbbell","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["躺在倾斜的长凳上，双脚固定，头部低于臀部。","双手各握一个哑铃，双臂伸直至胸部上方，手掌朝前。","慢慢地将哑铃降低到胸部两侧，保持肘部呈 90 度角。","将哑铃推回起始位置，充分伸展手臂。","重复所需的重复次数。"],"kind":"exercise","img":"media/0301-DwhEmmE.jpg","gif":"media/0301-DwhEmmE.gif","poses":"media/0301-DwhEmmE-poses.jpg"},{"id":"0303","name":"dumbbell decline hammer press","name_zh":"哑铃下斜锤式推","category":"chest","equipment":"dumbbell","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["躺在倾斜的长凳上，双脚固定，头部低于臀部。","双手各握一个哑铃，手掌相对，双臂伸至胸部上方。","将哑铃降低到胸部两侧，保持肘部稍微弯曲。","将哑铃推回到起始位置，充分伸展手臂。","重复所需的重复次数。"],"kind":"exercise","img":"media/0303-1qrWgZ2.jpg","gif":"media/0303-1qrWgZ2.gif","poses":"media/0303-1qrWgZ2-poses.jpg"},{"id":"0308","name":"dumbbell fly","name_zh":"哑铃飞鸟","category":"chest","equipment":"dumbbell","target":"pectorals","muscle_group":"shoulders","secondary_muscles":["shoulders"],"instructions_zh":["平躺在长凳上，双手各握一个哑铃，手掌相对。","将手臂伸直越过胸部，肘部稍微弯曲。","保持肘部轻微弯曲，将手臂以宽弧线向两侧放低，直到感觉到胸部有拉伸感。","暂停片刻，然后反转动作，将哑铃拉回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0308-yz9nUhF.jpg","gif":"media/0308-yz9nUhF.gif","poses":"media/0308-yz9nUhF-poses.jpg"},{"id":"0313","name":"dumbbell hammer curl","name_zh":"哑铃锤式弯举","category":"upper arms","equipment":"dumbbell","target":"biceps","muscle_group":"forearms","secondary_muscles":["forearms"],"instructions_zh":["站直，双手各持一个哑铃，手掌朝向躯干。","保持肘部靠近躯干，并旋转手掌，直到手掌朝前。","这将是您的起始位置。","现在，保持上臂静止，呼气并卷曲哑铃，同时收缩二头肌。","继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","然后，吸气并慢慢开始将哑铃放回起始位置。","重复建议的重复次数。"],"kind":"exercise","img":"media/0313-slDvUAU.jpg","gif":"media/0313-slDvUAU.gif","poses":"media/0313-slDvUAU-poses.jpg"},{"id":"0314","name":"dumbbell incline bench press","name_zh":"哑铃上斜卧推","category":"chest","equipment":"dumbbell","target":"pectorals","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"instructions_zh":["设置一个 45 度角的上斜凳。","坐在长凳上，双脚平放在地上，背部紧贴长凳。","双手各握一个哑铃，掌心向前，将哑铃举至肩高。","慢慢地将哑铃降低到胸部两侧，保持肘部呈 90 度角。","将哑铃推回起始位置，充分伸展手臂。","重复所需的重复次数。"],"kind":"exercise","img":"media/0314-ns0SIbU.jpg","gif":"media/0314-ns0SIbU.gif","poses":"media/0314-ns0SIbU-poses.jpg"},{"id":"0315","name":"dumbbell incline biceps curl","name_zh":"哑铃上斜弯举","category":"upper arms","equipment":"dumbbell","target":"biceps","muscle_group":"forearms","secondary_muscles":["forearms"],"instructions_zh":["坐在上斜凳上，双手各握一个哑铃，手掌朝前，双臂完全伸展。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将哑铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0315-F3xgbjF.jpg","gif":"media/0315-F3xgbjF.gif","poses":"media/0315-F3xgbjF-poses.jpg"},{"id":"0321","name":"dumbbell incline hammer press","name_zh":"哑铃上斜锤式推","category":"chest","equipment":"dumbbell","target":"pectorals","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"instructions_zh":["将上斜凳设置成 45 度角，坐在上面，双手各握一个哑铃，放在大腿上。","仰卧在长凳上，将哑铃置于与肩同高的位置，手掌相对。","将哑铃向上推离身体，直到手臂完全伸展。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0321-PG1kcIb.jpg","gif":"media/0321-PG1kcIb.gif","poses":"media/0321-PG1kcIb-poses.jpg"},{"id":"0324","name":"dumbbell incline palm-in press","name_zh":"哑铃上斜对握推","category":"chest","equipment":"dumbbell","target":"pectorals","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"instructions_zh":["设置一个 45 度角的上斜凳。","坐在长凳上，双手各握一个哑铃，手掌相对。","将双脚牢牢踩在地面上，并保持背部挺直靠在长凳上。","从与肩同高的哑铃开始，肘部弯曲，手掌相对。","将哑铃向上推离身体，充分伸展手臂。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0324-OVLmUuL.jpg","gif":"media/0324-OVLmUuL.gif","poses":"media/0324-OVLmUuL-poses.jpg"},{"id":"0327","name":"dumbbell incline row","name_zh":"哑铃上斜划船","category":"back","equipment":"dumbbell","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"instructions_zh":["设置一个 45 度角的上斜凳。","双手各握一个哑铃，坐在长凳上，胸部靠在斜坡上。","充分伸展双臂，让哑铃从肩膀上垂直垂下。","将哑铃拉向胸部，将肩胛骨挤压在一起。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0327-7vG5o25.jpg","gif":"media/0327-7vG5o25.gif","poses":"media/0327-7vG5o25-poses.jpg"},{"id":"0334","name":"dumbbell lateral raise","name_zh":"哑铃侧平举","category":"shoulders","equipment":"dumbbell","target":"delts","muscle_group":"traps","secondary_muscles":["traps"],"instructions_zh":["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。","保持背部挺直并启动核心肌群。","将手臂向两侧抬起，直到与地板平行，保持肘部稍微弯曲。","在顶部暂停片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0334-DsgkuIt.jpg","gif":"media/0334-DsgkuIt.gif","poses":"media/0334-DsgkuIt-poses.jpg"},{"id":"0336","name":"dumbbell lunge","name_zh":"哑铃箭步蹲","category":"upper legs","equipment":"dumbbell","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"instructions_zh":["双脚分开与肩同宽站立，每只手各握一个哑铃。","右脚向前迈出一步，将身体降低至弓步位置。","降低身体时保持背部挺直、挺胸。","推动右脚跟回到起始位置。","左腿重复上述动作。","交替腿进行所需的重复次数。"],"kind":"exercise","img":"media/0336-RRWFUcw.jpg","gif":"media/0336-RRWFUcw.gif","poses":"media/0336-RRWFUcw-poses.jpg"},{"id":"0338","name":"dumbbell lying elbow press","name_zh":"哑铃仰卧肘压","category":"upper arms","equipment":"dumbbell","target":"triceps","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"instructions_zh":["平躺在长凳上，双手各握一个哑铃，手掌相对，双臂伸直越过胸部。","弯曲肘部，将哑铃向肩膀方向降低，保持上臂静止。","在底部暂停片刻，然后伸展肘部将哑铃推回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0338-eOCOwIR.jpg","gif":"media/0338-eOCOwIR.gif","poses":"media/0338-eOCOwIR-poses.jpg"},{"id":"0340","name":"dumbbell lying hammer press","name_zh":"哑铃仰卧锤式推","category":"chest","equipment":"dumbbell","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["平躺在长凳上，双手各握一个哑铃，手掌相对，双臂伸直向上。","将哑铃放低至胸部两侧，保持肘部呈 90 度角。","将哑铃推回到起始位置，充分伸展手臂。","重复所需的重复次数。"],"kind":"exercise","img":"media/0340-7gdLIXa.jpg","gif":"media/0340-7gdLIXa.gif","poses":"media/0340-7gdLIXa-poses.jpg"},{"id":"0342","name":"dumbbell lying one arm press v. 2","name_zh":"哑铃仰卧单臂推（变式）","category":"chest","equipment":"dumbbell","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["平躺在长凳上，背部支撑，双脚平放在地面上。","一只手握住哑铃，手掌朝向脚部。","将手臂伸向天花板，保持肘部稍微弯曲。","慢慢地将哑铃向胸部方向降低，保持肘部靠近身体。","在底部暂停片刻，然后将哑铃推回到起始位置。","重复所需的重复次数，然后换到另一只手臂。"],"kind":"exercise","img":"media/0342-K3dIO25.jpg","gif":"media/0342-K3dIO25.gif","poses":"media/0342-K3dIO25-poses.jpg"},{"id":"0343","name":"dumbbell lying one arm press","name_zh":"哑铃仰卧单臂推","category":"chest","equipment":"dumbbell","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["平躺在长凳上，一只手拿着哑铃，双脚平放在地上。","将哑铃举至肩部水平，手掌朝前。","向上推哑铃，直到手臂完全伸展。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换到另一只手臂。"],"kind":"exercise","img":"media/0343-zGSIWQi.jpg","gif":"media/0343-zGSIWQi.gif","poses":"media/0343-zGSIWQi-poses.jpg"},{"id":"0347","name":"dumbbell lying pronation","name_zh":"哑铃仰卧旋前","category":"lower arms","equipment":"dumbbell","target":"forearms","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"instructions_zh":["平躺在长凳上，胸部朝下，双臂伸直向下，每只手各握一个哑铃。","旋转手掌，使手掌朝上。","保持上臂静止，呼气并弯曲哑铃，同时将手掌旋转至面朝下。","吸气并慢慢将哑铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0347-mym4hJo.jpg","gif":"media/0347-mym4hJo.gif","poses":"media/0347-mym4hJo-poses.jpg"},{"id":"0349","name":"dumbbell lying supination","name_zh":"哑铃仰卧旋后","category":"lower arms","equipment":"dumbbell","target":"forearms","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"instructions_zh":["平躺在长凳上，双脚平放在地上。","每只手握住一个哑铃，手掌朝上，双臂完全伸展。","保持上臂不动，收缩前臂，将哑铃向肩膀方向卷曲。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0349-M2Pm3zj.jpg","gif":"media/0349-M2Pm3zj.gif","poses":"media/0349-M2Pm3zj-poses.jpg"},{"id":"0352","name":"dumbbell neutral grip bench press","name_zh":"哑铃对握卧推","category":"upper arms","equipment":"dumbbell","target":"triceps","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"instructions_zh":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","每只手握一个哑铃，中立握法（手掌相对），双臂伸直越过胸部。","慢慢地将哑铃降低到胸部，保持肘部靠近身体。","在底部停顿片刻，然后将哑铃推回起始位置，完全伸展手臂。","重复所需的重复次数。"],"kind":"exercise","img":"media/0352-pP8wP2P.jpg","gif":"media/0352-pP8wP2P.gif","poses":"media/0352-pP8wP2P-poses.jpg"},{"id":"0445","name":"ez barbell anti gravity press","name_zh":"曲杆反重力推举","category":"shoulders","equipment":"ez barbell","target":"delts","muscle_group":"triceps","secondary_muscles":["triceps","chest"],"instructions_zh":["首先，双脚分开与肩同宽站立，并用正手握住杠铃。","将杠铃举至肩膀高度，保持肘部稍微弯曲，手掌朝前。","将杠铃推过头顶，充分伸展双臂。","将杠铃降低回肩部高度，然后重复所需的重复次数。"],"kind":"exercise","img":"media/0445-fprd84i.jpg","gif":"media/0445-fprd84i.gif","poses":"media/0445-fprd84i-poses.jpg"},{"id":"0447","name":"ez barbell curl","name_zh":"曲杆弯举","category":"upper arms","equipment":"ez barbell","target":"biceps","muscle_group":"forearms","secondary_muscles":["forearms"],"instructions_zh":["站直，双脚分开与肩同宽，反手握住 ez 杠铃，手掌朝上。","在整个运动过程中，保持肘部靠近躯干，上臂保持静止。","当你将杠铃向肩膀方向卷曲时呼气，收缩二头肌。","在顶部暂停片刻，然后吸气，慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0447-6TG6x2w.jpg","gif":"media/0447-6TG6x2w.gif","poses":"media/0447-6TG6x2w-poses.jpg"},{"id":"0467","name":"gorilla chin","name_zh":"大猩猩引体向上","category":"waist","equipment":"body weight","target":"abs","muscle_group":"forearms","secondary_muscles":["forearms","biceps"],"instructions_zh":["双脚分开与肩同宽站立，膝盖稍微弯曲。","正手握住引体向上杆，握距略宽于肩宽。","悬挂在杠上，双臂完全伸展，手掌背向自己。","收紧核心肌群，将身体拉向杠铃杆，将下巴置于杠铃上方。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0467-bmwlYvD.jpg","gif":"media/0467-bmwlYvD.gif","poses":"media/0467-bmwlYvD-poses.jpg"},{"id":"0520","name":"kettlebell alternating press","name_zh":"壶铃交替推举","category":"shoulders","equipment":"kettlebell","target":"delts","muscle_group":"triceps","secondary_muscles":["triceps","core"],"instructions_zh":["双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高。","将一只壶铃按过头顶，完全伸展手臂。","将壶铃降低至肩膀高度。","用另一只手臂重复上述步骤。","继续交替手臂进行所需的重复次数。"],"kind":"exercise","img":"media/0520-5KLbZWx.jpg","gif":"media/0520-5KLbZWx.gif","poses":"media/0520-5KLbZWx-poses.jpg"},{"id":"0521","name":"kettlebell alternating renegade row","name_zh":"壶铃交替叛徒划船","category":"back","equipment":"kettlebell","target":"upper back","muscle_group":"core","secondary_muscles":["core","shoulders"],"instructions_zh":["从高平板支撑位置开始，双手握住壶铃，双脚分开与臀部同宽。","收紧核心肌群，保持身体从头到脚跟呈一条直线。","将一个壶铃向上拉向胸部，保持肘部靠近身体。","将壶铃放回起始位置，然后用另一只手臂重复该动作。","继续交替手臂进行所需的重复次数。"],"kind":"exercise","img":"media/0521-b9kqlBy.jpg","gif":"media/0521-b9kqlBy.gif","poses":"media/0521-b9kqlBy-poses.jpg"},{"id":"0524","name":"kettlebell bent press","name_zh":"壶铃弯身推举","category":"waist","equipment":"kettlebell","target":"abs","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps","obliques"],"instructions_zh":["双脚分开与肩同宽站立，右手握住壶铃。","稍微弯曲膝盖，用右臂将壶铃压过头顶，保持肘部锁定。","将躯干向左旋转，将重量转移到左脚上。","弯曲左膝，将躯干压向地面，保持右臂伸过头顶。","当你下降时，眼睛盯着壶铃，胸部抬起。","左手接触地面后，将左脚推入并伸直左腿，推动臀部向前。","当你向前推动臀部时，用你的核心和右臂将壶铃推回到起始位置。","重复所需的重复次数，然后换边。"],"kind":"exercise","img":"media/0524-kjE55n5.jpg","gif":"media/0524-kjE55n5.gif","poses":"media/0524-kjE55n5-poses.jpg"},{"id":"0533","name":"kettlebell front squat","name_zh":"壶铃前蹲","category":"upper legs","equipment":"kettlebell","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"instructions_zh":["站立，双脚分开与肩同宽，脚趾稍微向外。","双手将壶铃放在胸前，靠近身体。","收紧核心并保持挺胸，同时降低臀部和向后倾斜，就像坐在椅子上一样。","降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。","通过脚跟发力站起来，在顶部挤压臀部。","重复所需的重复次数。"],"kind":"exercise","img":"media/0533-DB0n8AG.jpg","gif":"media/0533-DB0n8AG.gif","poses":"media/0533-DB0n8AG-poses.jpg"},{"id":"0534","name":"kettlebell goblet squat","name_zh":"壶铃高脚杯深蹲","category":"upper legs","equipment":"kettlebell","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"instructions_zh":["双脚分开与肩同宽站立，双手握住壶铃靠近胸部。","保持胸部挺直，核心收紧，弯曲膝盖和臀部，将身体降低至蹲姿。","继续降低，直到大腿与地面平行，或者尽可能低。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0534-ZA8b5hc.jpg","gif":"media/0534-ZA8b5hc.gif","poses":"media/0534-ZA8b5hc-poses.jpg"},{"id":"0570","name":"leg pull in flat bench","name_zh":"平凳收腿","category":"waist","equipment":"body weight","target":"abs","muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"instructions_zh":["坐在平坦的长凳上，双腿在身前伸直。","将双手放在臀部旁边的长凳上以获得支撑。","收紧腹肌，将双腿抬离地面，使膝盖靠近胸部。","在顶部暂停片刻，然后慢慢将双腿放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0570-OyoZ3Pu.jpg","gif":"media/0570-OyoZ3Pu.gif","poses":"media/0570-OyoZ3Pu-poses.jpg"},{"id":"0578","name":"lever deadlift","name_zh":"器械硬拉","category":"upper legs","equipment":"leverage machine","target":"glutes","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"instructions_zh":["将座椅高度和脚踏板调整到您想要的位置。","坐在机器上，背部靠在垫子上，双脚平放在脚踏板上。","抓住把手或座椅侧面以保持稳定性。","收紧臀肌和腿筋，并通过脚后跟推动举重。","保持背部挺直，避免圆肩。","在动作的最高点完全伸展臀部，挤压臀部。","以受控的方式降低重量，保持臀肌和腿筋的张力。","重复所需的重复次数。"],"kind":"exercise","img":"media/0578-GUT8I22.jpg","gif":"media/0578-GUT8I22.gif","poses":"media/0578-GUT8I22-poses.jpg"},{"id":"0583","name":"lever kneeling twist","name_zh":"器械跪姿转体","category":"waist","equipment":"leverage machine","target":"abs","muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"instructions_zh":["调整座椅高度，将自己放在机器上，膝盖放在垫子上，上半身朝前。","抓住机器的手柄或侧面以保持稳定性。","保持核心参与，将躯干尽可能舒适地向一侧扭转。","暂停片刻，然后慢慢回到起始位置。","向另一侧重复扭转。","继续交替进行所需的重复次数。"],"kind":"exercise","img":"media/0583-sZOR9EV.jpg","gif":"media/0583-sZOR9EV.gif","poses":"media/0583-sZOR9EV-poses.jpg"},{"id":"0587","name":"lever military press","name_zh":"器械军事推举","category":"shoulders","equipment":"leverage machine","target":"delts","muscle_group":"triceps","secondary_muscles":["triceps","upper chest"],"instructions_zh":["调整座椅高度并将自己放在机器上，背部靠在靠背上。","正手握住手柄，双手之间的距离略大于肩宽。","向上推动手柄，直到手臂完全伸展，但不要锁住肘部。","在顶部暂停片刻，然后慢慢将手柄放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0587-CggQhII.jpg","gif":"media/0587-CggQhII.gif","poses":"media/0587-CggQhII-poses.jpg"},{"id":"0640","name":"one arm slam (with medicine ball)","name_zh":"药球单臂砸地","category":"waist","equipment":"medicine ball","target":"abs","muscle_group":"shoulders","secondary_muscles":["shoulders","back"],"instructions_zh":["双脚分开与肩同宽站立，一只手将健身球放在腰前。","稍微弯曲膝盖并启动核心。","将健身球举过头顶，充分伸展手臂。","用力将药球摔到地上，用你的核心和肩膀产生力量。","抓住弹起的实心球，然后重复所需的重复次数。"],"kind":"exercise","img":"media/0640-jCrtE9b.jpg","gif":"media/0640-jCrtE9b.gif","poses":"media/0640-jCrtE9b-poses.jpg"},{"id":"0643","name":"overhead triceps stretch","name_zh":"过顶肱三头肌拉伸","category":"upper arms","equipment":"body weight","target":"triceps","muscle_group":"shoulders","secondary_muscles":["shoulders"],"instructions_zh":["站立或坐直，双脚分开与肩同宽。","将一只手臂伸过头顶，弯曲肘部，使手伸向对面的肩胛骨。","用另一只手轻轻地将伸出的手臂的肘部拉向头部的另一侧，感受三头肌的拉伸。","保持拉伸 15-30 秒，然后放松。","在另一侧重复。"],"kind":"stretch","img":"media/0643-Z5YStHW.jpg","gif":"media/0643-Z5YStHW.gif","poses":"media/0643-Z5YStHW-poses.jpg"},{"id":"0650","name":"pull-in (on stability ball)","name_zh":"瑜伽球收膝","category":"waist","equipment":"stability ball","target":"abs","muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"instructions_zh":["首先坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。","将双手放在稳定球的两侧以获得支撑。","收紧腹肌，慢慢向前滚动臀部，使膝盖靠近胸部。","在动作的最高点停顿片刻，然后慢慢将双腿伸展回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0650-UQr48Oi.jpg","gif":"media/0650-UQr48Oi.gif","poses":"media/0650-UQr48Oi-poses.jpg"},{"id":"0669","name":"rear deltoid stretch","name_zh":"三角肌后束拉伸","category":"shoulders","equipment":"body weight","target":"delts","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"instructions_zh":["站直，双脚分开与肩同宽。","将右臂伸过胸部，将左手放在右肘上。","轻轻地将右臂拉向左肩，感受右肩的拉伸。","保持拉伸 15-30 秒，然后放松。","在另一侧重复。"],"kind":"stretch","img":"media/0669-xifhB5W.jpg","gif":"media/0669-xifhB5W.gif","poses":"media/0669-xifhB5W-poses.jpg"},{"id":"0680","name":"rope climb","name_zh":"爬绳","category":"back","equipment":"rope","target":"upper back","muscle_group":"forearms","secondary_muscles":["forearms","biceps","shoulders"],"instructions_zh":["面向绳子站立，双脚分开与肩同宽。","用双手抓住绳子，手掌朝向自己。","稍微弯曲膝盖并启动核心。","开始通过交替的双手动作将自己拉上绳子。","用双腿协助向上运动。","继续攀爬，直到到达所需的高度或绳索的顶部。","要下降，请在控制下降的同时反转双手的动作。","重复所需的重复次数。"],"kind":"exercise","img":"media/0680-yaAxcQr.jpg","gif":"media/0680-yaAxcQr.gif","poses":"media/0680-yaAxcQr-poses.jpg"},{"id":"0716","name":"side push neck stretch","name_zh":"侧向颈部拉伸","category":"neck","equipment":"body weight","target":"levator scapulae","muscle_group":"trapezius","secondary_muscles":["trapezius","sternocleidomastoid"],"instructions_zh":["站直或坐直，肩膀放松。","将头向右倾斜，将右耳靠近右肩。","将右手放在头部左侧，轻轻施加压力以增加拉伸。","保持拉伸 15-30 秒。","在另一侧重复，将头向左倾斜并用左手施加压力。","每侧重复拉伸 2-3 次。"],"kind":"stretch","img":"media/0716-oQRJYkC.jpg","gif":"media/0716-oQRJYkC.gif","poses":"media/0716-oQRJYkC-poses.jpg"},{"id":"0721","name":"side wrist pull stretch","name_zh":"侧向拉腕拉伸","category":"lower arms","equipment":"body weight","target":"forearms","muscle_group":"wrists","secondary_muscles":["wrists","hands"],"instructions_zh":["双脚分开与肩同宽站立，双臂在身前伸展。","将右臂向侧面伸出，与地面平行，手掌朝下。","用左手抓住右手，轻轻地将其拉向身体，感觉右前臂有拉伸感。","保持拉伸 15-30 秒，然后放松。","在另一侧重复。"],"kind":"stretch","img":"media/0721-UtmIqcI.jpg","gif":"media/0721-UtmIqcI.gif","poses":"media/0721-UtmIqcI-poses.jpg"},{"id":"0747","name":"smith behind neck press","name_zh":"史密斯颈后推举","category":"shoulders","equipment":"smith machine","target":"delts","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"instructions_zh":["调整史密斯机的座椅高度，使杠铃与肩部齐平。","双脚分开与肩同宽站立，膝盖稍微弯曲。","正手握住杠铃，握距略宽于肩宽。","将杠铃从架子上抬起并向后退一步，保持稳定的姿势。","将杠铃降低到颈后，保持肘部向前。","将杠铃向上推过头顶，直到双臂完全伸展。","在顶部暂停片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0747-Gpn4ADc.jpg","gif":"media/0747-Gpn4ADc.gif","poses":"media/0747-Gpn4ADc-poses.jpg"},{"id":"0748","name":"smith bench press","name_zh":"史密斯卧推","category":"chest","equipment":"smith machine","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["将史密斯机杆的高度调整至胸部水平。","平躺在长凳上，双脚牢牢踩在地上。","正手握住杠铃，握距略宽于肩宽。","松开杠铃并将其向胸部降低，保持肘部内收。","当杠铃接触到你的胸部时暂停片刻。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"],"kind":"exercise","img":"media/0748-trqKQv2.jpg","gif":"media/0748-trqKQv2.gif","poses":"media/0748-trqKQv2-poses.jpg"},{"id":"0750","name":"smith chair squat","name_zh":"史密斯椅式深蹲","category":"upper legs","equipment":"smith machine","target":"quads","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"instructions_zh":["将史密斯机杆的高度调整到舒适的位置。","站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在上背部，放在斜方肌上。","通过弯曲膝盖和臀部慢慢降低身体，收紧核心并保持挺胸。","继续降低，直到大腿与地面平行，或者尽可能低。","暂停片刻，然后用力推动脚后跟，回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0750-Gu2rNJd.jpg","gif":"media/0750-Gu2rNJd.gif","poses":"media/0750-Gu2rNJd-poses.jpg"},{"id":"0751","name":"smith close-grip bench press","name_zh":"史密斯窄握卧推","category":"upper arms","equipment":"smith machine","target":"triceps","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"instructions_zh":["调整座椅高度，将自己放在长凳上，双脚平放在地面上。","紧紧握住杠铃，握距略窄于肩宽。","将杠铃向胸部降低，保持肘部靠近身体。","在底部停顿片刻，然后将杠铃推回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0751-WcHl7ru.jpg","gif":"media/0751-WcHl7ru.gif","poses":"media/0751-WcHl7ru-poses.jpg"},{"id":"0752","name":"smith deadlift","name_zh":"史密斯硬拉","category":"upper legs","equipment":"smith machine","target":"glutes","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","lower back"],"instructions_zh":["将史密斯机设置为与臀部高度相同的杠铃。","双脚分开与肩同宽站立，脚趾稍微向外。","弯曲臀部和膝盖，保持背部挺直，挺胸，正手握住杠铃，握距略宽于肩宽。","伸展臀部和膝盖，调动核心力量并举起杠铃，保持杠铃靠近身体。","站直，充分伸展臀部和膝盖。","通过弯曲臀部和膝盖来降低杠铃，保持控制并保持背部挺直。","重复所需的重复次数。"],"kind":"exercise","img":"media/0752-UfePqpx.jpg","gif":"media/0752-UfePqpx.gif","poses":"media/0752-UfePqpx-poses.jpg"},{"id":"0777","name":"spell caster","name_zh":"杠铃绕环推","category":"waist","equipment":"dumbbell","target":"abs","muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"instructions_zh":["双脚分开与肩同宽站立，一只手握住哑铃。","稍微弯曲膝盖，腰部向前转动，保持背部挺直。","将哑铃伸向另一只脚的手臂，同时旋转躯干。","返回起始位置并在另一侧重复。","继续交替进行所需的重复次数。"],"kind":"exercise","img":"media/0777-p9cCe2r.jpg","gif":"media/0777-p9cCe2r.gif","poses":"media/0777-p9cCe2r-poses.jpg"},{"id":"0796","name":"standing wheel rollerout","name_zh":"站姿健腹轮","category":"waist","equipment":"wheel roller","target":"abs","muscle_group":"lower back","secondary_muscles":["lower back","shoulders"],"instructions_zh":["首先，站直，双脚分开与肩同宽，滚轮位于您的前方。","弯腰，慢慢向前滚动轮子，保持背部挺直，核心肌群参与。","继续向前滚动，直到感觉到腹肌拉伸并且身体尽可能伸展。","暂停片刻，然后慢慢地将轮子向身体方向滚动，回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0796-KtRomty.jpg","gif":"media/0796-KtRomty.gif","poses":"media/0796-KtRomty-poses.jpg"},{"id":"0811","name":"trap bar deadlift","name_zh":"六角杠硬拉","category":"upper legs","equipment":"trap bar","target":"glutes","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","lower back"],"instructions_zh":["双脚分开与肩同宽站立，将陷阱杆放在你面前的地面上。","弯曲臀部和膝盖，降低身体高度，并用正手握住陷阱杆的手柄。","当你开始通过伸展臀部和膝盖将陷阱杆抬离地面时，保持背部挺直，挺胸。","当你举起时，专注于通过脚后跟发力，并在运动的最高点挤压臀部。","弯曲臀部和膝盖，将陷阱杆放回地面，在整个运动过程中保持背部挺直。","重复所需的重复次数。"],"kind":"exercise","img":"media/0811-jQGwmxN.jpg","gif":"media/0811-jQGwmxN.gif","poses":"media/0811-jQGwmxN-poses.jpg"},{"id":"0833","name":"weighted donkey calf raise","name_zh":"负重驴式提踵","category":"lower legs","equipment":"weighted","target":"calves","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"instructions_zh":["站在一个升高的平台上，脚趾放在边缘，脚后跟悬垂。","抓住一个稳定的物体作为支撑。","伸展脚踝，将脚后跟尽可能抬高。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0833-LmaFNZS.jpg","gif":"media/0833-LmaFNZS.gif","poses":"media/0833-LmaFNZS-poses.jpg"},{"id":"0861","name":"cable seated row","name_zh":"绳索坐姿划船","category":"back","equipment":"cable","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["坐在电缆划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。","正手握住手柄，保持背部挺直，肩膀放松。","将手柄拉向身体，将肩胛骨挤压在一起。","在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0861-fUBheHs.jpg","gif":"media/0861-fUBheHs.gif","poses":"media/0861-fUBheHs-poses.jpg"},{"id":"0868","name":"cable curl","name_zh":"绳索弯举","category":"upper arms","equipment":"cable","target":"biceps","muscle_group":"forearms","secondary_muscles":["forearms"],"instructions_zh":["面对电缆机站立，双脚与肩同宽。","用手握住电缆附件，手掌朝上。","保持肘部靠近身体两侧，上臂保持静止。","呼气并将电缆附件卷向肩膀，收缩二头肌。","在动作的最高点暂停片刻，挤压你的二头肌。","吸气并缓慢地将电缆附件放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0868-G08RZcQ.jpg","gif":"media/0868-G08RZcQ.gif","poses":"media/0868-G08RZcQ-poses.jpg"},{"id":"0970","name":"band assisted pull-up","name_zh":"弹力带辅助引体向上","category":"back","equipment":"band","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["将弹力带固定在上拉杆或坚固的锚点上。","踏上弹力带，手掌背向自己，握住杠铃，双手之间的距离略宽于肩宽。","双臂完全伸展，保持核心收紧，肩膀向下并向后倾斜。","将肩胛骨挤压在一起并将肘部向下推向臀部，将身体向上拉向杠铃杆。","继续拉，直到下巴高于杠铃，然后慢慢降低回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0970-r1XNRYB.jpg","gif":"media/0970-r1XNRYB.gif","poses":"media/0970-r1XNRYB-poses.jpg"},{"id":"0974","name":"band close-grip pulldown","name_zh":"弹力带窄握下拉","category":"back","equipment":"band","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["将弹力带固定在较高的锚点上，例如上拉杆或坚固的横梁。","面向锚点站立，用反手抓住弹力带，双手与肩同宽。","后退一步，在弹力带上产生张力，双脚分开与臀部同宽。","当你将弹力带向下拉向胸部时，收紧你的核心并保持背部挺直，将肩胛骨挤压在一起。","在动作底部暂停片刻，然后慢慢松开弹力带回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0974-DptumMx.jpg","gif":"media/0974-DptumMx.gif","poses":"media/0974-DptumMx-poses.jpg"},{"id":"0975","name":"band close-grip push-up","name_zh":"弹力带窄距俯卧撑","category":"upper arms","equipment":"band","target":"triceps","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"instructions_zh":["将一条带子绕在你的上臂上，就在肘部上方。","采取俯卧撑姿势，双手直接放在肩膀下方，身体从头到脚跟呈一条直线。","弯曲肘部，将胸部降低到地面，保持肘部靠近身体两侧。","推动手掌以伸展手臂并返回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0975-ufaxB52.jpg","gif":"media/0975-ufaxB52.gif","poses":"media/0975-ufaxB52-poses.jpg"},{"id":"0979","name":"band horizontal pallof press","name_zh":"弹力带帕洛夫推","category":"waist","equipment":"band","target":"abs","muscle_group":"obliques","secondary_muscles":["obliques","glutes"],"instructions_zh":["将带子固定在腰部高度的坚固锚点上。","垂直于锚点站立，双脚分开与肩同宽。","用双手抓住带子手柄并远离锚点以在带子中产生张力。","将双手放在胸前，保持肘部弯曲并靠近身体。","调动你的核心并保持稳定的姿势。","将手臂伸直至前方，将弹力带推离身体。","保持伸展姿势几秒钟，专注于保持核心紧张。","慢慢地将双手放回胸前，抵抗弹力带的拉力。","重复所需的重复次数。"],"kind":"exercise","img":"media/0979-9pa4H5m.jpg","gif":"media/0979-9pa4H5m.gif","poses":"media/0979-9pa4H5m-poses.jpg"},{"id":"0983","name":"band kneeling one arm pulldown","name_zh":"弹力带跪姿单臂下拉","category":"back","equipment":"band","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids"],"instructions_zh":["将带子固定在头顶上方坚固的锚点上。","跪下，用一只手握住弹力带，手掌朝下。","将手臂完全伸过头顶，保持肘部稍微弯曲。","调动你的背阔肌，将弹力带拉向你的一侧，使你的肘部靠近你的胸腔。","在底部停顿片刻，然后慢慢释放张力，回到起始位置。","重复所需的重复次数，然后换边。"],"kind":"exercise","img":"media/0983-pmnrOp0.jpg","gif":"media/0983-pmnrOp0.gif","poses":"media/0983-pmnrOp0-poses.jpg"},{"id":"0987","name":"band one arm single leg split squat","name_zh":"弹力带单臂单腿分腿蹲","category":"upper legs","equipment":"band","target":"quads","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"instructions_zh":["双脚分开站立，与臀部同宽，将阻力带绕在脚踝上。","向前伸出一条腿，将脚尖放在长凳上或身后的一步上。","用一只手握住支撑物以保持平衡。","弯曲站立的腿，将身体降低到蹲姿，保持膝盖与脚趾在一条直线上。","推动脚后跟返回到起始位置。","重复所需的重复次数，然后换腿。"],"kind":"exercise","img":"media/0987-arsYEd3.jpg","gif":"media/0987-arsYEd3.gif","poses":"media/0987-arsYEd3-poses.jpg"},{"id":"0988","name":"band one arm standing low row","name_zh":"弹力带单臂站姿低位划船","category":"back","equipment":"band","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"instructions_zh":["将带子固定在腰部高度的稳定锚点上。","面向锚点站立，双脚分开与肩同宽。","用一只手握住弹力带，手掌朝内，然后后退以在弹力带中产生张力。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","将带子拉向腰部，将肩胛骨挤压在一起。","在动作的最高点暂停片刻，然后慢慢松开弹力带回到起始位置。","重复所需的重复次数，然后换边。"],"kind":"exercise","img":"media/0988-km0sQC0.jpg","gif":"media/0988-km0sQC0.gif","poses":"media/0988-km0sQC0-poses.jpg"},{"id":"0991","name":"band pull through","name_zh":"弹力带胯下上拉","category":"upper legs","equipment":"band","target":"glutes","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"instructions_zh":["将阻力带连接到地面上坚固的锚点上。","背对锚点站立，双脚与肩同宽。","向前迈一步，在弹力带中产生张力，保持膝盖稍微弯曲。","铰接臀部并将臀部向后推，保持膝盖轻微弯曲。","降低躯干直到与地面平行，感觉腿筋被拉伸。","向前推动臀部并挤压臀部以返回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0991-VtTbiP3.jpg","gif":"media/0991-VtTbiP3.gif","poses":"media/0991-VtTbiP3-poses.jpg"},{"id":"0994","name":"band reverse wrist curl","name_zh":"弹力带反握腕弯举","category":"lower arms","equipment":"band","target":"forearms","muscle_group":"forearms","secondary_muscles":["forearms"],"instructions_zh":["坐在长凳或椅子上，双脚平放在地面上。","正手握住弹力带，手掌朝下，然后将其缠绕在手指上。","将前臂放在大腿上，手腕悬在边缘上。","慢慢向上弯曲手腕，挤压前臂。","在顶部暂停片刻，然后慢慢将手腕放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/0994-Ezpnw9d.jpg","gif":"media/0994-Ezpnw9d.gif","poses":"media/0994-Ezpnw9d-poses.jpg"},{"id":"0997","name":"band shoulder press","name_zh":"弹力带肩推","category":"shoulders","equipment":"band","target":"delts","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"instructions_zh":["双脚分开与肩同宽站立，将弹力带放在脚下。","手掌朝前握住弹力带，将双手举至肩高，肘部弯曲。","将弹力带压过头顶，充分伸展双臂。","在顶部暂停片刻，然后慢慢将阻力带降低至肩部高度。","重复所需的重复次数。"],"kind":"exercise","img":"media/0997-peAeMR3.jpg","gif":"media/0997-peAeMR3.gif","poses":"media/0997-peAeMR3-poses.jpg"},{"id":"1001","name":"band single leg split squat","name_zh":"弹力带单腿分腿蹲","category":"upper legs","equipment":"band","target":"quads","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"instructions_zh":["双脚分开站立，与臀部同宽，将阻力带绕在脚踝上。","右脚向前迈一大步，左脚向后退一小步。","弯曲膝盖并降低身体，直到右大腿与地面平行，保持左膝盖略高于地面。","推动右脚跟回到起始位置。","在另一侧重复。"],"kind":"exercise","img":"media/1001-y8bYM8w.jpg","gif":"media/1001-y8bYM8w.gif","poses":"media/1001-y8bYM8w-poses.jpg"},{"id":"1003","name":"band squat row","name_zh":"弹力带深蹲划船","category":"upper legs","equipment":"band","target":"glutes","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","back"],"instructions_zh":["将带子固定在腰部高度的坚固锚点上。","面向锚点站立，双脚分开与肩同宽。","双手握住弹力带手柄，手掌相对，双臂向前伸展。","弯曲膝盖并蹲下，保持背部挺直，挺胸。","从蹲姿开始，将弹力带手柄拉向身体，将肩胛骨挤压在一起。","在最高点停顿片刻，然后慢慢释放张力，回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1003-w1NOByi.jpg","gif":"media/1003-w1NOByi.gif","poses":"media/1003-w1NOByi-poses.jpg"},{"id":"1004","name":"band squat","name_zh":"弹力带深蹲","category":"upper legs","equipment":"band","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"instructions_zh":["双脚分开站立，与肩同宽，弹力带放在膝盖上方。","保持挺胸、核心收紧，将臀部向后推，弯曲膝盖，形成下蹲姿势。","确保膝盖位于脚趾上方，并且重量位于脚后跟。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1004-TUZLh71.jpg","gif":"media/1004-TUZLh71.gif","poses":"media/1004-TUZLh71-poses.jpg"},{"id":"1009","name":"band stiff leg deadlift","name_zh":"弹力带直腿硬拉","category":"upper legs","equipment":"band","target":"glutes","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"instructions_zh":["双脚分开站立，与肩同宽，将弹力带绕在脚踝上。","用双手将弹力带放在大腿前面，手掌朝向身体。","保持背部挺直，核心收紧，铰接臀部，慢慢将上半身降低到地面。","当你降低时，将臀部向后推，并让膝盖稍微弯曲。","将弹力带降低至地面，感受腿筋的拉伸。","在底部暂停片刻，然后启动臀肌和腿筋，将上半身抬回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1009-kuMiR2T.jpg","gif":"media/1009-kuMiR2T.gif","poses":"media/1009-kuMiR2T-poses.jpg"},{"id":"1013","name":"band underhand pulldown","name_zh":"弹力带反手下拉","category":"back","equipment":"band","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["将弹力带固定在较高的锚点上，例如上拉杆或坚固的横梁。","面向锚点站立，双脚分开与肩同宽。","反手握住弹力带，双手间距略宽于肩宽。","将手臂完全伸过头顶，保持肘部稍微弯曲。","收紧背阔肌，将弹力带向下拉向胸部，将肩胛骨挤压在一起。","在动作底部停顿片刻，然后慢慢释放张力，回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1013-k6tUeqS.jpg","gif":"media/1013-k6tUeqS.gif","poses":"media/1013-k6tUeqS-poses.jpg"},{"id":"1015","name":"band vertical pallof press","name_zh":"弹力带垂直帕洛夫推","category":"waist","equipment":"band","target":"abs","muscle_group":"obliques","secondary_muscles":["obliques","glutes"],"instructions_zh":["双脚分开与肩同宽站立，将弹力带缠绕在胸部高度的坚固物体上。","用双手握住弹力带并远离锚点，在弹力带中产生张力。","使自己垂直于锚点，一侧面向弹力带。","将双臂伸直在身前，保持双手与胸同高。","收紧核心肌群，将弹力带压离胸部，充分伸展手臂。","保持该姿势几秒钟，然后慢慢将弹力带拉回到胸部。","重复所需的重复次数，然后换边。"],"kind":"exercise","img":"media/1015-G7PXMlT.jpg","gif":"media/1015-G7PXMlT.gif","poses":"media/1015-G7PXMlT-poses.jpg"},{"id":"1022","name":"band standing rear delt row","name_zh":"弹力带站姿后束划船","category":"shoulders","equipment":"band","target":"delts","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids","biceps"],"instructions_zh":["双脚分开与肩同宽站立，将弹力带放在脚下。","双手握住弹力带手柄，手掌相对，双臂向前伸展。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","将弹力带拉向胸部，将肩胛骨挤压在一起。","在最高点停顿片刻，然后慢慢释放张力，回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1022-tc5dYrf.jpg","gif":"media/1022-tc5dYrf.gif","poses":"media/1022-tc5dYrf-poses.jpg"},{"id":"1023","name":"band straight back stiff leg deadlift","name_zh":"弹力带直背直腿硬拉","category":"upper legs","equipment":"band","target":"glutes","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"instructions_zh":["双脚分开与肩同宽站立，将弹力带绕在大腿上。","用双手将弹力带放在大腿前面，手掌朝向身体。","保持背部挺直，膝盖稍微弯曲，铰接臀部并将弹力带降低到地面。","当你降低弹力带时，感受腿筋的拉伸。","启动臀肌和腿筋，将身体抬回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1023-lHeUULr.jpg","gif":"media/1023-lHeUULr.gif","poses":"media/1023-lHeUULr-poses.jpg"},{"id":"1160","name":"burpee","name_zh":"波比跳","category":"cardio","equipment":"body weight","target":"cardiovascular system","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","shoulders","chest"],"instructions_zh":["从站立位置开始，双脚分开与肩同宽。","弯曲膝盖并将双手放在身前的地板上，将身体降低至蹲姿。","将脚踢回到俯卧撑位置。","进行俯卧撑，保持身体呈一条直线。","将双脚跳回蹲姿。","爆发性地跳起，将双臂举过头顶。","轻轻落地并立即回到蹲姿，开始下一次重复。"],"kind":"exercise","img":"media/1160-dK9394r.jpg","gif":"media/1160-dK9394r.gif","poses":"media/1160-dK9394r-poses.jpg"},{"id":"1167","name":"dynamic chest stretch (male)","name_zh":"动态胸部拉伸","category":"chest","equipment":"body weight","target":"pectorals","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"instructions_zh":["站直，双脚分开与肩同宽。","将双臂伸直至两侧，与地面平行。","慢慢地将双臂向前伸，交叉在身体前面。","感受胸部肌肉的伸展。","保持拉伸 10-30 秒。","返回起始位置并重复所需的重复次数。"],"kind":"stretch","img":"media/1167-3uj0Ozg.jpg","gif":"media/1167-3uj0Ozg.gif","poses":"media/1167-3uj0Ozg-poses.jpg"},{"id":"1254","name":"band bench press","name_zh":"弹力带卧推","category":"chest","equipment":"band","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","正手握住带子手柄，间距略宽于肩宽。","充分伸展双臂，将弹力带推离胸部。","慢慢将弹力带放回到胸部，保持肘部呈 90 度角。","重复所需的重复次数。"],"kind":"exercise","img":"media/1254-khlHMqs.jpg","gif":"media/1254-khlHMqs.gif","poses":"media/1254-khlHMqs-poses.jpg"},{"id":"1256","name":"barbell reverse grip decline bench press","name_zh":"杠铃反握下斜卧推","category":"chest","equipment":"barbell","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["躺在倾斜的长凳上，双脚固定，头部低于臀部。","反握抓住杠铃，握距略宽于肩宽。","松开杠铃，慢慢将其降低到胸部，保持肘部内收。","在底部停顿片刻，然后将杠铃推回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1256-DotAgEF.jpg","gif":"media/1256-DotAgEF.gif","poses":"media/1256-DotAgEF-poses.jpg"},{"id":"1257","name":"barbell reverse grip incline bench press","name_zh":"杠铃反握上斜卧推","category":"chest","equipment":"barbell","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["设置一个 45 度角的上斜凳。","躺在长凳上，双脚平放在地上。","反握抓住杠铃，双手分开略宽于肩宽。","松开杠铃，慢慢将其降低到胸部，保持肘部内收。","当杠铃触及胸部时暂停片刻。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"],"kind":"exercise","img":"media/1257-DU7I633.jpg","gif":"media/1257-DU7I633.gif","poses":"media/1257-DU7I633-poses.jpg"},{"id":"1258","name":"barbell wide reverse grip bench press","name_zh":"杠铃宽握反握卧推","category":"chest","equipment":"barbell","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","反握宽握杠铃，握距略宽于肩宽。","将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。","将杠铃慢慢降低到胸部，保持肘部内收，手腕伸直。","当杠铃接触胸部时暂停片刻，然后将其推回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1258-945zpRg.jpg","gif":"media/1258-945zpRg.gif","poses":"media/1258-945zpRg-poses.jpg"},{"id":"1260","name":"cable decline one arm press","name_zh":"绳索下斜单臂推","category":"chest","equipment":"cable","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["将拉线机调整至下降位置。","背对机器站立，用一只手抓住手柄。","将背部靠在下斜长凳上，手臂伸直在身前。","弯曲肘部，将手柄向胸部方向降低，同时保持上臂静止。","在底部暂停片刻，然后将手柄推回到起始位置。","重复所需的重复次数，然后换臂。"],"kind":"exercise","img":"media/1260-KHGNa16.jpg","gif":"media/1260-KHGNa16.gif","poses":"media/1260-KHGNa16-poses.jpg"},{"id":"1261","name":"cable decline press","name_zh":"绳索下斜推","category":"chest","equipment":"cable","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["将拉线机调整至下降位置。","坐在面向缆绳机的下降长凳上。","正手握住手柄并将其置于胸部水平。","将双脚平放在地面上，并将背部牢牢靠在长凳上。","呼气并将手柄推离身体，充分伸展双臂。","动作结束时暂停片刻，挤压胸部肌肉。","吸气并慢慢地将手柄放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1261-2Pya1cP.jpg","gif":"media/1261-2Pya1cP.gif","poses":"media/1261-2Pya1cP-poses.jpg"},{"id":"1265","name":"cable one arm incline press","name_zh":"绳索单臂上斜推","category":"chest","equipment":"cable","target":"pectorals","muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"instructions_zh":["将拉索机调整至低滑轮位置。","坐在倾斜的长凳上，背对缆绳机。","用一只手抓住手柄并将其举至肩膀高度。","将双脚牢牢放在地面上并保持稳定的位置。","向前和向上按下手柄，充分伸展手臂。","在最高点暂停片刻，然后慢慢将手柄放回起始位置。","重复所需的重复次数，然后换边。"],"kind":"exercise","img":"media/1265-GKEH6jj.jpg","gif":"media/1265-GKEH6jj.gif","poses":"media/1265-GKEH6jj-poses.jpg"},{"id":"1266","name":"cable one arm incline press on exercise ball","name_zh":"绳索单臂瑜伽球上斜推","category":"chest","equipment":"cable","target":"pectorals","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"instructions_zh":["坐在健身球上，双脚平放在地上，背部靠在倾斜的长凳上。","一只手握住电缆手柄，将手臂呈 90 度角，肘部弯曲。","向前和向上按下电缆手柄，完全伸展手臂。","在顶部暂停片刻，然后慢慢将拉索手柄放回起始位置。","重复所需的重复次数，然后换到另一只手臂。"],"kind":"exercise","img":"media/1266-6t00BsF.jpg","gif":"media/1266-6t00BsF.gif","poses":"media/1266-6t00BsF-poses.jpg"},{"id":"1267","name":"cable one arm press on exercise ball","name_zh":"绳索单臂瑜伽球推","category":"chest","equipment":"cable","target":"pectorals","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"instructions_zh":["坐在健身球上，双脚平放在地上，背部挺直。","一只手握住电缆手柄，将手臂置于胸部高度，肘部弯曲。","将另一只手放在臀部上以保持稳定。","向前按电缆手柄，完全伸展手臂。","暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数，然后换臂。"],"kind":"exercise","img":"media/1267-MKIelrR.jpg","gif":"media/1267-MKIelrR.gif","poses":"media/1267-MKIelrR-poses.jpg"},{"id":"1268","name":"cable press on exercise ball","name_zh":"绳索瑜伽球卧推","category":"chest","equipment":"cable","target":"pectorals","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"instructions_zh":["坐在健身球上，双脚平放在地上，膝盖呈 90 度角。","将电缆手柄保持在胸部高度，手掌朝下，肘部弯曲。","收紧核心并向前按压缆索手柄，直到手臂完全伸展。","暂停片刻，然后慢慢释放张力，并将电缆手柄拉回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1268-vAwm6rK.jpg","gif":"media/1268-vAwm6rK.gif","poses":"media/1268-vAwm6rK-poses.jpg"},{"id":"1273","name":"clap push up","name_zh":"击掌俯卧撑","category":"chest","equipment":"body weight","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["从高平板支撑位置开始，双手分开略宽于肩宽。","弯曲肘部，将身体降低到地面，保持核心参与。","爆发性地推动手掌，将身体推离地面。","在半空中时，拍手，然后回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1273-wigSg76.jpg","gif":"media/1273-wigSg76.gif","poses":"media/1273-wigSg76-poses.jpg"},{"id":"1274","name":"deep push up","name_zh":"深俯卧撑","category":"chest","equipment":"dumbbell","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["从高平板支撑位置开始，双手分开略宽于肩宽，身体呈一条直线。","弯曲肘部，使胸部靠近地面，使胸部靠近地面。","推动手掌以伸展手臂并返回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1274-vptOQ4N.jpg","gif":"media/1274-vptOQ4N.gif","poses":"media/1274-vptOQ4N-poses.jpg"},{"id":"1275","name":"drop push up","name_zh":"增强式俯卧撑","category":"chest","equipment":"body weight","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["从高平板支撑位置开始，双手分开略宽于肩宽。","将胸部压向地面，保持肘部靠近身体。","当你的胸部刚好高于地面时，迅速将膝盖放在地上。","伸展双臂，将自己推回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1275-Q497lAE.jpg","gif":"media/1275-Q497lAE.gif","poses":"media/1275-Q497lAE-poses.jpg"},{"id":"1281","name":"dumbbell incline one arm press","name_zh":"哑铃上斜单臂推","category":"chest","equipment":"dumbbell","target":"pectorals","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"instructions_zh":["坐在上斜凳上，一只手拿着哑铃，放在大腿上。","仰卧在长凳上，将哑铃置于与肩同高的位置，手掌朝前。","将哑铃向上并稍微向内推，充分伸展手臂。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换到另一只手臂。"],"kind":"exercise","img":"media/1281-rDAiRf9.jpg","gif":"media/1281-rDAiRf9.gif","poses":"media/1281-rDAiRf9-poses.jpg"},{"id":"1282","name":"dumbbell incline one arm press on exercise ball","name_zh":"哑铃上斜瑜伽球单臂推","category":"chest","equipment":"dumbbell","target":"pectorals","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"instructions_zh":["坐在健身球上，一只手拿着哑铃，双脚平放在地上。","慢慢地向前移动你的脚，滚动球，直到你的头、脖子和上背部得到球的支撑。","将哑铃握在与肩同高的位置，手掌朝前。","向上推哑铃，直到手臂完全伸展。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换到另一只手臂。"],"kind":"exercise","img":"media/1282-Bg5JKSH.jpg","gif":"media/1282-Bg5JKSH.gif","poses":"media/1282-Bg5JKSH-poses.jpg"},{"id":"1283","name":"dumbbell incline press on exercise ball","name_zh":"哑铃上斜瑜伽球推","category":"chest","equipment":"dumbbell","target":"pectorals","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"instructions_zh":["坐在健身球上，每只手各握一个哑铃，手掌朝前。","双脚慢慢向前移动，身体沿着球滚动，直到头部、颈部和上背部得到球的支撑。","将哑铃保持在与肩同高的位置，肘部弯曲并指向两侧。","向上推哑铃，充分伸展手臂。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1283-bfiHMpI.jpg","gif":"media/1283-bfiHMpI.gif","poses":"media/1283-bfiHMpI-poses.jpg"},{"id":"1296","name":"exercise ball pike push up","name_zh":"瑜伽球派克俯卧撑","category":"chest","equipment":"stability ball","target":"pectorals","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps","core"],"instructions_zh":["从俯卧撑位置开始，双手放在地板上，小腿放在稳定球上。","收紧核心肌群，将臀部抬向天花板，将球滚向双手。","保持双腿伸直，身体呈屈体姿势，形成倒V字形。","弯曲肘部，将上半身降低到地板上，保持头部与双手在一条直线上。","用手推动并伸展双臂以返回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1296-sVvXT5J.jpg","gif":"media/1296-sVvXT5J.gif","poses":"media/1296-sVvXT5J-poses.jpg"},{"id":"1303","name":"medicine ball chest push from 3 point stance","name_zh":"药球三点式胸前推","category":"chest","equipment":"medicine ball","target":"pectorals","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"instructions_zh":["以三点姿势开始，一只手放在健身球上，另一只手放在地上。","伸展双腿并将身体摆成一条直线。","将胸部压向地面，同时保持背部挺直。","将药球推离身体，完全伸展手臂。","返回起始位置并重复所需的重复次数。"],"kind":"exercise","img":"media/1303-dCJnuVq.jpg","gif":"media/1303-dCJnuVq.gif","poses":"media/1303-dCJnuVq-poses.jpg"},{"id":"1317","name":"barbell reverse grip incline bench row","name_zh":"杠铃反握上斜划船","category":"back","equipment":"barbell","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["设置一个 45 度角的上斜凳。","坐在长凳上，面向靠背，胸部靠在靠背上。","反握（手掌朝下）抓住杠铃，双手距离略宽于肩宽。","保持背部挺直，核心参与。","将杠铃拉向上腹部，将肩胛骨挤压在一起。","在动作的最高点停顿片刻。","慢慢地将杠铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1317-8d8qJQI.jpg","gif":"media/1317-8d8qJQI.gif","poses":"media/1317-8d8qJQI-poses.jpg"},{"id":"1318","name":"cable incline bench row","name_zh":"绳索上斜划船","category":"back","equipment":"cable","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","rear deltoids"],"instructions_zh":["以 45 度角设置一个上斜凳，并将绳索手柄连接到低滑轮上。","坐在长凳上，面向电缆机，双脚平放在地板上，膝盖稍微弯曲。","正手握住电缆手柄，并将双臂完全伸展到身前。","从臀部开始向前倾，同时保持背部挺直，核心肌群参与。","缩回肩胛骨并弯曲肘部，将电缆手柄拉向胸部。","在动作的最高点挤压背部肌肉，然后慢慢伸展手臂回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1318-yaMIo4D.jpg","gif":"media/1318-yaMIo4D.gif","poses":"media/1318-yaMIo4D-poses.jpg"},{"id":"1321","name":"cable rope elevated seated row","name_zh":"绳索绳把垫高坐姿划船","category":"back","equipment":"cable","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["坐在面向电缆机的高架座椅上。","正手握住缆绳手柄，手掌相对。","保持背部挺直并稍微向后倾斜，保持膝盖轻微弯曲。","通过缩回肩胛骨并挤压背部肌肉，将电缆拉向您的身体。","在完全收缩的位置暂停片刻。","慢慢释放压力并将手臂伸回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1321-c8oybX6.jpg","gif":"media/1321-c8oybX6.gif","poses":"media/1321-c8oybX6-poses.jpg"},{"id":"1323","name":"cable rope seated row","name_zh":"绳索绳把坐姿划船","category":"back","equipment":"cable","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["坐在划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。","正手握住缆绳，手掌相对。","保持背部挺直，稍微向前倾斜，肘部保持轻微弯曲。","将缆绳拉向身体，将肩胛骨挤压在一起。","在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1323-SJqRxOt.jpg","gif":"media/1323-SJqRxOt.gif","poses":"media/1323-SJqRxOt-poses.jpg"},{"id":"1324","name":"cable upper row","name_zh":"绳索高位划船","category":"back","equipment":"cable","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"instructions_zh":["将直杆连接到胸部高度的缆绳机上。","面向机器站立，双脚分开与肩同宽。","正手握住杠铃，双手距离略宽于肩宽。","保持背部挺直，核心肌群参与。","将杠铃拉向上胸部，将肩胛骨挤压在一起。","在动作的最高点停顿片刻。","慢慢地将杠铃释放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1324-PQStVXH.jpg","gif":"media/1324-PQStVXH.gif","poses":"media/1324-PQStVXH-poses.jpg"},{"id":"1325","name":"cable wide grip rear pulldown behind neck","name_zh":"绳索宽握颈后下拉","category":"back","equipment":"cable","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"instructions_zh":["调整缆绳机，使下拉杆位于您头部上方的高度。","坐在座椅上，用宽的正手握法抓住下拉杆。","稍微向后倾斜时，保持背部挺直，挺胸。","将杠铃向下拉至上胸部，将肩胛骨挤压在一起。","在动作底部暂停片刻，然后慢慢将杠铃释放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1325-CmEr4pM.jpg","gif":"media/1325-CmEr4pM.gif","poses":"media/1325-CmEr4pM-poses.jpg"},{"id":"1326","name":"chin-up","name_zh":"反握引体向上","category":"back","equipment":"body weight","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["悬挂在引体向上杆上，手掌朝向自己，双手与肩同宽。","启动核心肌群，将身体拉向杠铃杆，以胸部为主导。","继续拉，直到下巴位于杠铃上方。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1326-T2mxWqc.jpg","gif":"media/1326-T2mxWqc.gif","poses":"media/1326-T2mxWqc-poses.jpg"},{"id":"1327","name":"close grip chin-up","name_zh":"窄距反握引体（变式）","category":"back","equipment":"body weight","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["抓住引体向上杆，手掌朝向自己，双手与肩同宽。","悬挂在杠上，双臂完全伸展，双脚离开地面。","收紧背部肌肉，将身体拉向杠铃杆，保持肘部靠近身体。","继续拉，直到下巴位于杠铃上方。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1327-VnfUNW7.jpg","gif":"media/1327-VnfUNW7.gif","poses":"media/1327-VnfUNW7-poses.jpg"},{"id":"1328","name":"dumbbell lying rear delt row","name_zh":"哑铃仰卧后束划船","category":"back","equipment":"dumbbell","target":"upper back","muscle_group":"shoulders","secondary_muscles":["shoulders","biceps"],"instructions_zh":["脸朝下躺在平坦的长凳上，每只手各握一个哑铃，手掌朝内。","将手臂伸直向下伸向地板，肘部保持轻微弯曲。","调动背部肌肉，将哑铃举向胸部，将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1328-XUUD0Fs.jpg","gif":"media/1328-XUUD0Fs.gif","poses":"media/1328-XUUD0Fs-poses.jpg"},{"id":"1344","name":"ez bar reverse grip bent over row","name_zh":"曲杆反握俯身划船","category":"back","equipment":"ez barbell","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["站立，双脚分开与肩同宽，膝盖稍微弯曲。","反手握住 ez 杠铃，手掌朝上，双手与肩同宽。","臀部向前弯曲，保持背部挺直，挺胸，直到躯干几乎与地板平行。","将 ez 杠铃拉向下胸部，将肩胛骨挤压在一起。","在顶部暂停片刻，然后慢慢将 ez 杠铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1344-G8dXpNG.jpg","gif":"media/1344-G8dXpNG.gif","poses":"media/1344-G8dXpNG-poses.jpg"},{"id":"1346","name":"kneeling lat stretch","name_zh":"跪姿背阔肌拉伸","category":"back","equipment":"body weight","target":"lats","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"instructions_zh":["跪在地上，膝盖分开与臀部同宽，脚趾向后。","将双臂伸过头顶，手指交叉。","保持背部挺直，慢慢向右侧倾斜，感受左侧背阔肌的拉伸。","保持伸展动作 20-30 秒，然后回到起始位置。","在左侧重复该拉伸动作，向左侧倾斜，感受右侧背阔肌的拉伸。","继续交替进行所需的重复次数。"],"kind":"stretch","img":"media/1346-f38OEuO.jpg","gif":"media/1346-f38OEuO.gif","poses":"media/1346-f38OEuO-poses.jpg"},{"id":"1359","name":"smith bent over row","name_zh":"史密斯俯身划船","category":"back","equipment":"smith machine","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["将史密斯机设置为与臀部高度相同的杠铃。","面向杠铃站立，双脚分开与肩同宽。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","正手握住杠铃，双手距离略宽于肩宽。","将杠铃拉向下胸部，将肩胛骨挤压在一起。","在顶部暂停片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1359-ZX9UZmj.jpg","gif":"media/1359-ZX9UZmj.gif","poses":"media/1359-ZX9UZmj-poses.jpg"},{"id":"1363","name":"spine stretch","name_zh":"坐姿脊柱拉伸","category":"back","equipment":"body weight","target":"spine","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"instructions_zh":["坐在地上，双腿在身前伸展。","将双手放在身后的地面上，手指指向身体。","启动你的核心并慢慢向后倾斜，保持背部挺直。","继续向后倾斜，直到感觉到脊柱被拉伸。","保持伸展几秒钟，然后慢慢回到起始位置。","重复所需的重复次数。"],"kind":"stretch","img":"media/1363-JbC2iaV.jpg","gif":"media/1363-JbC2iaV.gif","poses":"media/1363-JbC2iaV-poses.jpg"},{"id":"1365","name":"upper back stretch","name_zh":"上背部拉伸","category":"back","equipment":"body weight","target":"upper back","muscle_group":"shoulders","secondary_muscles":["shoulders"],"instructions_zh":["站直，双脚分开与肩同宽。","将双臂伸直在身前，与地面平行。","手指交叉，手掌旋转远离身体。","慢慢地将手臂举过头顶，保持它们伸直并彼此平行。","当你举起手臂时，将肩胛骨挤压在一起。","保持拉伸 15-30 秒，然后松开并重复。"],"kind":"stretch","img":"media/1365-GSDioYu.jpg","gif":"media/1365-GSDioYu.gif","poses":"media/1365-GSDioYu-poses.jpg"},{"id":"1370","name":"barbell floor calf raise","name_zh":"杠铃站姿提踵","category":"lower legs","equipment":"barbell","target":"calves","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"instructions_zh":["将杠铃放在您面前的地板上。","站立，脚掌放在杠铃边缘，脚跟悬垂。","如果需要，请抓住一个稳定的物体以保持平衡。","尽可能高地抬高脚后跟，用小腿来抬起身体。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1370-2IHEa2T.jpg","gif":"media/1370-2IHEa2T.gif","poses":"media/1370-2IHEa2T-poses.jpg"},{"id":"1374","name":"box jump down with one leg stabilization","name_zh":"单腿跳箱下落稳定","category":"lower legs","equipment":"body weight","target":"calves","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","glutes"],"instructions_zh":["站在盒子或平台前，双脚分开与肩同宽。","弯曲膝盖，跳到盒子上，一只脚轻轻落地，另一只脚悬在盒子边缘。","将脚踩在盒子上，将自己稳定在盒子上，同时保持另一只脚离开地面。","保持这个姿势几秒钟，锻炼小腿肌肉以保持平衡。","将放在盒子上的脚慢慢放下，回到起始位置。","用另一条腿重复该练习。"],"kind":"exercise","img":"media/1374-iPm26QU.jpg","gif":"media/1374-iPm26QU.gif","poses":"media/1374-iPm26QU-poses.jpg"},{"id":"1377","name":"calf stretch with hands against wall","name_zh":"靠墙小腿拉伸","category":"lower legs","equipment":"body weight","target":"calves","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"instructions_zh":["面向墙壁站立，双脚分开与臀部同宽。","将双手靠在墙上，与肩同高。","右脚向后退一步，保持脚后跟着地，腿伸直。","弯曲左膝并向前倾斜，保持后腿伸直，脚后跟着地。","保持拉伸 20-30 秒。","换腿并重复拉伸。"],"kind":"stretch","img":"media/1377-m0tCHqc.jpg","gif":"media/1377-m0tCHqc.gif","poses":"media/1377-m0tCHqc-poses.jpg"},{"id":"1379","name":"dumbbell seated calf raise","name_zh":"哑铃坐姿提踵","category":"lower legs","equipment":"dumbbell","target":"calves","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"instructions_zh":["坐在长凳或椅子上，双脚平放在地面上，并将哑铃放在大腿上。","将脚掌放在升高的表面（例如台阶或木块）上，脚跟悬在边缘外。","握住哑铃以保持稳定。","尽可能高地抬高脚后跟，将身体重量转移到脚掌上。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1379-r29jP7S.jpg","gif":"media/1379-r29jP7S.gif","poses":"media/1379-r29jP7S-poses.jpg"},{"id":"1393","name":"smith one leg floor calf raise","name_zh":"史密斯单腿提踵","category":"lower legs","equipment":"smith machine","target":"calves","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"instructions_zh":["将自己放在史密斯机杆下方的地板上，背对机器。","将脚掌放在凸起的表面上，例如举重板或杠铃块。","将史密斯机杆放在小腿上，就在脚踝上方。","用手握住横杆以保持稳定。","伸展脚踝，将脚后跟抬离地面，抬起身体。","在动作的最高点暂停，然后慢慢降低脚跟回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1393-9GXrTE6.jpg","gif":"media/1393-9GXrTE6.gif","poses":"media/1393-9GXrTE6-poses.jpg"},{"id":"1399","name":"bench dip on floor","name_zh":"地板凳上臂屈伸","category":"upper arms","equipment":"body weight","target":"triceps","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"instructions_zh":["坐在长凳或椅子的边缘，双手抓住边缘，手指指向前方。","将臀部滑离长凳，用手支撑体重。","弯曲肘部降低身体，直到上臂与地板平行。","伸直手臂，将自己推回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1399-9RT8oQW.jpg","gif":"media/1399-9RT8oQW.gif","poses":"media/1399-9RT8oQW-poses.jpg"},{"id":"1407","name":"calf push stretch with hands against wall","name_zh":"靠墙小腿推伸","category":"lower legs","equipment":"body weight","target":"calves","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"instructions_zh":["面向墙壁站立，双脚分开与臀部同宽。","将双手靠在墙上，与肩同高。","一只脚向后退一步，脚跟保持在地面上，腿伸直。","稍微弯曲前膝盖并向前倾斜，感觉小腿有拉伸感。","保持拉伸 20-30 秒。","换腿并重复拉伸。"],"kind":"stretch","img":"media/1407-PzNxakt.jpg","gif":"media/1407-PzNxakt.gif","poses":"media/1407-PzNxakt-poses.jpg"},{"id":"1408","name":"band hip lift","name_zh":"弹力带臀桥","category":"upper legs","equipment":"band","target":"glutes","muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"instructions_zh":["仰卧，膝盖弯曲，双脚平放在地上。","将阻力带放在膝盖上方。","调动你的臀肌和核心肌肉。","将脚后跟压入地面，将臀部抬离地板，在顶部挤压臀部。","在顶部暂停片刻，然后慢慢将臀部放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1408-E4R8Hz1.jpg","gif":"media/1408-E4R8Hz1.gif","poses":"media/1408-E4R8Hz1-poses.jpg"},{"id":"1410","name":"barbell lateral lunge","name_zh":"杠铃侧向箭步蹲","category":"upper legs","equipment":"barbell","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"instructions_zh":["双脚分开与肩同宽站立，将杠铃放在上背部。","右脚向一侧迈出一大步，保持左脚踩地。","弯曲右膝，将身体降低到弓步位置，保持左腿伸直。","用右脚推出并返回到起始位置。","在另一侧重复，用左脚迈步。"],"kind":"exercise","img":"media/1410-py1HSzx.jpg","gif":"media/1410-py1HSzx.gif","poses":"media/1410-py1HSzx-poses.jpg"},{"id":"1411","name":"barbell palms down wrist curl over a bench","name_zh":"杠铃正握凳上腕弯举","category":"lower arms","equipment":"barbell","target":"forearms","muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"instructions_zh":["坐在长凳上，双脚平放在地上，前臂放在大腿上，手掌朝下。","正手握住杠铃，双手与肩同宽。","弯曲手腕，将杠铃降低到地面，保持前臂静止。","在底部停顿片刻，然后通过伸展手腕慢慢将杠铃举起。","重复所需的重复次数。"],"kind":"exercise","img":"media/1411-yzYH9pI.jpg","gif":"media/1411-yzYH9pI.gif","poses":"media/1411-yzYH9pI-poses.jpg"},{"id":"1412","name":"barbell palms up wrist curl over a bench","name_zh":"杠铃反握凳上腕弯举","category":"lower arms","equipment":"barbell","target":"forearms","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"instructions_zh":["坐在长凳上，双脚平放在地面上，反手握住杠铃，手掌朝上。","将前臂放在长凳上，让手腕悬在长凳边缘。","保持前臂静止，呼气并尽可能向上弯曲手腕。","保持收缩位置短暂停顿，然后吸气并慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1412-SJAA2IQ.jpg","gif":"media/1412-SJAA2IQ.gif","poses":"media/1412-SJAA2IQ-poses.jpg"},{"id":"1421","name":"modified push up to lower arms","name_zh":"肘撑跪姿俯卧撑","category":"lower arms","equipment":"body weight","target":"forearms","muscle_group":"triceps","secondary_muscles":["triceps","chest","shoulders"],"instructions_zh":["从俯卧撑位置开始，双手直接放在肩膀下方，身体呈一条直线。","弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。","一旦肘部成 90 度角，将前臂放低至地面，将肘部保持在肩膀正下方。","暂停片刻，然后用手掌推动前臂，使其回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1421-arvaszz.jpg","gif":"media/1421-arvaszz.gif","poses":"media/1421-arvaszz-poses.jpg"},{"id":"1424","name":"seated glute stretch","name_zh":"坐姿臀肌拉伸","category":"upper legs","equipment":"body weight","target":"glutes","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"instructions_zh":["坐在地上，双腿在身前伸展。","弯曲右膝，将右脚踝交叉在左大腿上。","将右手放在身后的地面上以获得支撑。","用左手轻轻按下右膝盖以加深伸展。","保持拉伸 30 秒到 1 分钟。","换边并重复。"],"kind":"stretch","img":"media/1424-DeDThfG.jpg","gif":"media/1424-DeDThfG.gif","poses":"media/1424-DeDThfG-poses.jpg"},{"id":"1425","name":"sled 45 degrees one leg press","name_zh":"雪橇机45度单腿蹬","category":"upper legs","equipment":"sled machine","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"instructions_zh":["将雪橇机调整至 45 度角。","坐在雪橇机上，背部靠在垫子上，双脚放在踏板上。","将一只脚放在踏板上并伸展腿，将雪橇推离您。","慢慢弯曲膝盖，将雪橇放回起始位置。","换另一条腿重复上述步骤。","继续交替双腿达到所需的重复次数。"],"kind":"exercise","img":"media/1425-WWD6FzI.jpg","gif":"media/1425-WWD6FzI.gif","poses":"media/1425-WWD6FzI-poses.jpg"},{"id":"1430","name":"chest dip (on dip-pull-up cage)","name_zh":"双杠臂屈伸（综合架）","category":"chest","equipment":"body weight","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["将倾斜杆调整到您可以舒适地握住它们的高度。","站在杠铃之间，将双手放在每个杠铃上，距离略宽于肩宽。","跳起来并伸直双臂，将体重支撑在杠上。","弯曲膝盖并将脚踝交叉在身后。","弯曲肘部降低身体，保持胸部向上，肩膀向下。","继续降低，直到肩膀低于肘部或直到您感到胸部有拉伸感。","推动手掌并伸展肘部，将身体抬回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1430-XgWyAiA.jpg","gif":"media/1430-XgWyAiA.gif","poses":"media/1430-XgWyAiA-poses.jpg"},{"id":"1431","name":"assisted standing chin-up","name_zh":"辅助站姿反握引体","category":"back","equipment":"leverage machine","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["将机器调整至您所需的辅助级别。","站在脚踏板上，正手握住手柄，握距略宽于肩宽。","保持挺胸、肩膀向后，收紧核心肌群，并稍微弯曲膝盖。","弯曲肘部并将肘部向身体两侧压低，将身体向上拉。","继续拉，直到下巴位于杠铃上方。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1431-7OeHptV.jpg","gif":"media/1431-7OeHptV.gif","poses":"media/1431-7OeHptV-poses.jpg"},{"id":"1432","name":"assisted standing pull-up","name_zh":"辅助站姿引体向上","category":"back","equipment":"leverage machine","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["将机器调整至您所需的体重和高度设置。","面向机器站立，双脚分开与肩同宽。","正手握住手柄，握距略宽于肩宽。","启动你的背阔肌和二头肌，并将自己拉向手柄。","在顶部暂停片刻，挤压背部肌肉。","慢慢地将自己放回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1432-f4xtKBj.jpg","gif":"media/1432-f4xtKBj.gif","poses":"media/1432-f4xtKBj-poses.jpg"},{"id":"1435","name":"barbell low bar squat","name_zh":"杠铃低杠位深蹲","category":"upper legs","equipment":"barbell","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"instructions_zh":["双脚分开与肩同宽站立，杠铃放在上背部。","保持挺胸，核心收紧，弯曲膝盖并向后推臀部，慢慢降低身体。","继续降低，直到大腿与地面平行或略低于地面。","暂停片刻，然后用力推动脚后跟，回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1435-bTpEUcm.jpg","gif":"media/1435-bTpEUcm.gif","poses":"media/1435-bTpEUcm-poses.jpg"},{"id":"1436","name":"barbell high bar squat","name_zh":"杠铃高杠位深蹲","category":"upper legs","equipment":"barbell","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"instructions_zh":["站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在上背部，放在斜方肌上。","当你开始蹲下时，启动你的核心并保持胸部挺直，将臀部向后推并弯曲膝盖。","放低身体，直到大腿与地面平行，或者尽可能低到您能舒服的高度。","通过脚后跟站起来，伸展臀部和膝盖。","重复所需的重复次数。"],"kind":"exercise","img":"media/1436-Gnfo4FM.jpg","gif":"media/1436-Gnfo4FM.gif","poses":"media/1436-Gnfo4FM-poses.jpg"},{"id":"1456","name":"barbell standing close grip military press","name_zh":"杠铃站姿窄握推举","category":"shoulders","equipment":"barbell","target":"delts","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"instructions_zh":["双脚分开与肩同宽站立，正手握住杠铃，双手距离略小于肩宽。","将杠铃举至肩膀高度，保持肘部靠近身体。","将杠铃推过头顶，充分伸展双臂。","将杠铃降低回肩部高度。","重复所需的重复次数。"],"kind":"exercise","img":"media/1456-wdRZISl.jpg","gif":"media/1456-wdRZISl.gif","poses":"media/1456-wdRZISl-poses.jpg"},{"id":"1457","name":"barbell standing wide military press","name_zh":"杠铃站姿宽握推举","category":"shoulders","equipment":"barbell","target":"delts","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"instructions_zh":["双脚分开与肩同宽站立，正手握杠铃，握距略宽于肩。","将杠铃举至肩膀高度，保持肘部稍微位于杠铃前方。","将杠铃推过头顶，充分伸展双臂。","将杠铃降低回肩部高度，然后重复所需的重复次数。"],"kind":"exercise","img":"media/1457-Kyd9Rz5.jpg","gif":"media/1457-Kyd9Rz5.gif","poses":"media/1457-Kyd9Rz5-poses.jpg"},{"id":"1461","name":"barbell full squat (back pov)","name_zh":"杠铃全蹲（背面视角）","category":"upper legs","equipment":"barbell","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"instructions_zh":["站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在上背部，将其放在斜方肌或三角肌后束上。","当你开始降低身体时，启动你的核心并保持胸部挺直。","弯曲膝盖和臀部，向后和向下推臀部，就像坐在椅子上一样。","降低身体，直到大腿与地面平行或稍低于地面。","保持膝盖与脚趾对齐，并将重量放在脚后跟上。","通过脚后跟站起来，伸展臀部和膝盖。","重复所需的重复次数。"],"kind":"exercise","img":"media/1461-DhMl549.jpg","gif":"media/1461-DhMl549.gif","poses":"media/1461-DhMl549-poses.jpg"},{"id":"1462","name":"barbell full squat (side pov)","name_zh":"杠铃全蹲（侧面视角）","category":"upper legs","equipment":"barbell","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"instructions_zh":["站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在上背部，将其放在斜方肌或三角肌后束上。","当你开始降低身体时，启动你的核心并保持胸部挺直。","弯曲膝盖和臀部，向后和向下推臀部，就像坐在椅子上一样。","降低身体，直到大腿与地面平行或稍低于地面。","保持膝盖与脚趾对齐，并将重量放在脚后跟上。","通过脚后跟站起来，伸展臀部和膝盖。","重复所需的重复次数。"],"kind":"exercise","img":"media/1462-iYzB0Cz.jpg","gif":"media/1462-iYzB0Cz.gif","poses":"media/1462-iYzB0Cz-poses.jpg"},{"id":"1473","name":"backward jump","name_zh":"后跳","category":"upper legs","equipment":"body weight","target":"quads","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes","calves"],"instructions_zh":["双脚分开与肩同宽站立。","稍微弯曲膝盖，向后跳跃，用双脚蹬地。","脚掌轻轻着地，弯曲膝盖以吸收冲击力。","重复所需的重复次数。"],"kind":"exercise","img":"media/1473-SaDOwk7.jpg","gif":"media/1473-SaDOwk7.gif","poses":"media/1473-SaDOwk7-poses.jpg"},{"id":"1545","name":"barbell full zercher squat","name_zh":"杠铃全泽奇深蹲","category":"upper legs","equipment":"barbell","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"instructions_zh":["站立，双脚分开与肩同宽，脚趾稍微外翻。","将杠铃放在肘部的弯曲处，双手握住杠铃以保持稳定。","当你将臀部向后降低到蹲姿时，启动你的核心并保持胸部抬起。","保持膝盖与脚趾对齐，并将重量放在脚后跟上。","降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。","通过脚跟发力站起来，在动作的最高点挤压臀部。","重复所需的重复次数。"],"kind":"exercise","img":"media/1545-vR1vold.jpg","gif":"media/1545-vR1vold.gif","poses":"media/1545-vR1vold-poses.jpg"},{"id":"1576","name":"leg up hamstring stretch","name_zh":"仰卧腘绳肌拉伸","category":"upper legs","equipment":"body weight","target":"hamstrings","muscle_group":"glutes","secondary_muscles":["glutes"],"instructions_zh":["平躺，双腿伸展。","弯曲一侧膝盖，将其靠近胸部，握住大腿或小腿。","尽可能伸直腿，同时保持腿抬高。","保持拉伸 20-30 秒。","换另一条腿重复上述步骤。"],"kind":"stretch","img":"media/1576-sU5BrfP.jpg","gif":"media/1576-sU5BrfP.gif","poses":"media/1576-sU5BrfP-poses.jpg"},{"id":"1617","name":"dumbbell decline one arm hammer press","name_zh":"哑铃下斜单臂锤式推","category":"upper arms","equipment":"dumbbell","target":"triceps","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"instructions_zh":["躺在下斜长凳上，一只手握住哑铃，放在胸前。","将手臂伸直向上，保持肘部稍微弯曲。","将哑铃向肩膀方向降低，保持肘部靠近身体。","将哑铃推回到起始位置。","重复所需的重复次数，然后换臂。"],"kind":"exercise","img":"media/1617-SHUMp5H.jpg","gif":"media/1617-SHUMp5H.gif","poses":"media/1617-SHUMp5H-poses.jpg"},{"id":"1618","name":"dumbbell incline hammer press on exercise ball","name_zh":"哑铃上斜瑜伽球锤式推","category":"upper arms","equipment":"dumbbell","target":"triceps","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"instructions_zh":["坐在健身球上，双手各握一个哑铃，手掌相对。","双脚向前走，身体沿着球滚动，直到头部、颈部和上背部得到球的支撑。","将哑铃保持在与肩同高的位置，肘部弯曲并指向两侧。","将哑铃向上并稍微向内推，保持手掌相对。","充分伸展双臂，在动作的最高点挤压三头肌。","慢慢地将哑铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1618-wkgnGfb.jpg","gif":"media/1618-wkgnGfb.gif","poses":"media/1618-wkgnGfb-poses.jpg"},{"id":"1619","name":"dumbbell incline one arm hammer press","name_zh":"哑铃上斜单臂锤式推","category":"upper arms","equipment":"dumbbell","target":"triceps","muscle_group":"shoulders","secondary_muscles":["shoulders","chest"],"instructions_zh":["坐在上斜凳上，一只手拿着哑铃，放在大腿上。","向后靠在长凳上，用大腿帮助将哑铃举至肩膀高度。","旋转手腕，使手掌朝内，朝向身体。","将哑铃向上推离身体，完全伸展手臂。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换臂。"],"kind":"exercise","img":"media/1619-LL1UiTX.jpg","gif":"media/1619-LL1UiTX.gif","poses":"media/1619-LL1UiTX-poses.jpg"},{"id":"1620","name":"dumbbell incline one arm hammer press on exercise ball","name_zh":"哑铃上斜瑜伽球单臂锤式推","category":"upper arms","equipment":"dumbbell","target":"triceps","muscle_group":"shoulders","secondary_muscles":["shoulders","chest"],"instructions_zh":["坐在健身球上，一只手拿着哑铃。","双脚向前走，身体向下滚动，直到头部、颈部和上背部得到球的支撑。","握住哑铃，手掌朝内，肘部弯曲成 90 度角。","将哑铃向上推向天花板，伸直手臂。","将哑铃放回起始位置。","重复所需的重复次数，然后换臂。"],"kind":"exercise","img":"media/1620-jDnrkar.jpg","gif":"media/1620-jDnrkar.gif","poses":"media/1620-jDnrkar-poses.jpg"},{"id":"1713","name":"assisted prone lying quads stretch","name_zh":"俯卧股四头肌拉伸","category":"upper legs","equipment":"assisted","target":"quads","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"instructions_zh":["脸朝下躺在地上，双腿伸直。","弯曲左膝，用左手向后抓住左脚或脚踝。","轻轻地将左脚拉向臀肌，感受左股四头肌的拉伸。","保持拉伸 20-30 秒，然后放松。","右腿重复上述动作。"],"kind":"stretch","img":"media/1713-YUYAMEj.jpg","gif":"media/1713-YUYAMEj.gif","poses":"media/1713-YUYAMEj-poses.jpg"},{"id":"1717","name":"cable squat row (with rope attachment)","name_zh":"绳索深蹲划船（绳把）","category":"back","equipment":"cable","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"instructions_zh":["将绳子连接到腰部高度的缆绳机上。","面对电缆机站立，双脚与肩同宽。","弯曲膝盖，将身体降低至蹲姿，保持背部挺直，挺胸。","正手握住绳子，双手与肩同宽。","收紧核心并将绳子拉向身体，将肩胛骨挤压在一起。","保持肘部靠近身体并继续拉，直到双手到达胸部。","在动作的最高点停顿片刻，然后慢慢松开绳子，并将手臂伸回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1717-f7fnAIB.jpg","gif":"media/1717-f7fnAIB.gif","poses":"media/1717-f7fnAIB-poses.jpg"},{"id":"1719","name":"barbell incline close grip bench press","name_zh":"杠铃上斜窄握卧推","category":"upper arms","equipment":"barbell","target":"triceps","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"instructions_zh":["设置一个 45 度角的上斜凳。","躺在长凳上，双脚平放在地上。","紧紧握住杠铃，握距略窄于肩宽。","松开杠铃并将其缓慢降低至胸部，保持肘部靠近身体。","当杠铃触及胸部时暂停片刻。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"],"kind":"exercise","img":"media/1719-gx7s7uF.jpg","gif":"media/1719-gx7s7uF.gif","poses":"media/1719-gx7s7uF-poses.jpg"},{"id":"1723","name":"cable one arm tricep pushdown","name_zh":"绳索单臂肱三头下压","category":"upper arms","equipment":"cable","target":"triceps","muscle_group":"forearms","secondary_muscles":["forearms"],"instructions_zh":["面向缆绳机站立，并在胸部高度处安装直杆附件。","正手握住杠铃，然后后退以在绳索上产生张力。","将双脚分开与肩同宽，并稍微弯曲膝盖。","在整个练习过程中保持背部挺直并保持核心参与。","首先，手臂完全伸展并垂直于地板。","保持上臂静止，呼气并将杠铃向下推，直到手臂完全伸展。","暂停片刻，然后吸气，慢慢回到起始位置。","重复所需的重复次数，然后换臂。"],"kind":"exercise","img":"media/1723-qRZ5S1N.jpg","gif":"media/1723-qRZ5S1N.gif","poses":"media/1723-qRZ5S1N-poses.jpg"},{"id":"1731","name":"dumbbell close grip press","name_zh":"哑铃窄距推举","category":"upper arms","equipment":"dumbbell","target":"triceps","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"instructions_zh":["坐在平坦的长凳上，每只手各拿一个哑铃，放在大腿上。","用你的大腿帮助举起哑铃，一次举起一个哑铃，这样你就可以将它们保持在与肩同宽的位置。","一旦与肩同宽，向前旋转手腕，使手掌背向自己。这将是您的起始位置。","当你吸气时，慢慢地将哑铃降低到你的身边，直到它们与你的胸部齐平。","呼气时，用三头肌将哑铃举回到起始位置。确保只使用三头肌，不要使用前臂或二头肌来帮助举起哑铃。","在收缩位置第二次暂停后，重复该动作达到规定的重复次数。"],"kind":"exercise","img":"media/1731-7jGOBF3.jpg","gif":"media/1731-7jGOBF3.gif","poses":"media/1731-7jGOBF3-poses.jpg"},{"id":"1747","name":"ez bar french press on exercise ball","name_zh":"曲杆瑜伽球法式推举","category":"upper arms","equipment":"ez barbell","target":"triceps","muscle_group":"shoulders","secondary_muscles":["shoulders"],"instructions_zh":["坐在健身球上，正手握住 EZ 杠铃。","向上伸展双臂，保持肘部靠近头部。","弯曲肘部，慢慢将杠铃降低到脑后。","暂停片刻，然后将手臂伸回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1747-CFN9P8G.jpg","gif":"media/1747-CFN9P8G.gif","poses":"media/1747-CFN9P8G-poses.jpg"},{"id":"1749","name":"ez bar standing french press","name_zh":"曲杆站姿法式推举","category":"upper arms","equipment":"ez barbell","target":"triceps","muscle_group":"shoulders","secondary_muscles":["shoulders"],"instructions_zh":["双脚分开与肩同宽站立，正手握住杠铃。","将杠铃举过头顶，充分伸展双臂。","保持上臂靠近头部，弯曲肘部，慢慢将杠铃降低到脑后。","暂停片刻，然后将手臂伸回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1749-1cTf2Ux.jpg","gif":"media/1749-1cTf2Ux.gif","poses":"media/1749-1cTf2Ux-poses.jpg"},{"id":"1751","name":"barbell pin presses","name_zh":"杠铃架上定位推","category":"upper arms","equipment":"barbell","target":"triceps","muscle_group":"shoulders","secondary_muscles":["shoulders"],"instructions_zh":["将杠铃放在与胸部同高的力量架上。","面向杠铃站立，将自己置于杠铃下方，双脚分开与肩同宽。","正手握住杠铃，握距略宽于肩宽。","将杠铃从架子上提起，并将其保持在胸部正上方，双臂完全伸展。","将杠铃向胸部方向降低，保持肘部靠近身体。","当杠铃触及胸部时暂停片刻。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"],"kind":"exercise","img":"media/1751-bndCa3Q.jpg","gif":"media/1751-bndCa3Q.gif","poses":"media/1751-bndCa3Q-poses.jpg"},{"id":"1756","name":"barbell single leg deadlift","name_zh":"杠铃单腿硬拉","category":"upper legs","equipment":"barbell","target":"glutes","muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"instructions_zh":["站立，双脚分开与臀部同宽，正手握住杠铃在大腿前面。","将重心转移到左脚上，并将右脚稍微抬离地面。","臀部向前转动，保持背部挺直，右腿向后伸展以保持平衡。","将杠铃向地面降低，使其靠近身体，左腿稍微弯曲。","在底部暂停片刻，然后启动臀肌和腿筋，将躯干抬回到起始位置。","重复所需的重复次数，然后换边。"],"kind":"exercise","img":"media/1756-gEyURal.jpg","gif":"media/1756-gEyURal.gif","poses":"media/1756-gEyURal-poses.jpg"},{"id":"1760","name":"dumbbell goblet squat","name_zh":"哑铃高脚杯深蹲","category":"upper legs","equipment":"dumbbell","target":"quads","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"instructions_zh":["双脚分开与肩同宽站立，双手握住哑铃垂直放在胸前。","保持胸部挺直，核心收紧，通过向后推臀部并弯曲膝盖，将身体降低至蹲姿。","继续降低，直到大腿与地面平行，或者尽可能低。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/1760-yn8yg1r.jpg","gif":"media/1760-yn8yg1r.gif","poses":"media/1760-yn8yg1r-poses.jpg"},{"id":"2136","name":"dumbbell cuban press v. 2","name_zh":"哑铃古巴推举（变式）","category":"shoulders","equipment":"dumbbell","target":"delts","muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"instructions_zh":["双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高，手掌朝下。","保持核心收紧，背部挺直，将哑铃垂直推过头顶，直到手臂完全伸展。","旋转手腕，使手掌朝前。","将哑铃放回至肩膀高度，将手腕旋转回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/2136-BqgCRif.jpg","gif":"media/2136-BqgCRif.gif","poses":"media/2136-BqgCRif-poses.jpg"},{"id":"2137","name":"dumbbell arnold press","name_zh":"哑铃阿诺德推举","category":"shoulders","equipment":"dumbbell","target":"delts","muscle_group":"triceps","secondary_muscles":["triceps","upper chest"],"instructions_zh":["坐在有背部支撑的长凳上，双手各握一个哑铃，与肩同高，手掌朝向身体，肘部弯曲。","向上推哑铃，直到手臂完全伸展，手掌朝前。","抬起时旋转手腕，使手掌在动作的最高点朝前。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/2137-Xy4jlWA.jpg","gif":"media/2137-Xy4jlWA.gif","poses":"media/2137-Xy4jlWA-poses.jpg"},{"id":"2138","name":"stationary bike run v. 3","name_zh":"固定单车骑行","category":"cardio","equipment":"stationary bike","target":"cardiovascular system","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"instructions_zh":["调整座椅高度和位置以确保正确对齐。","将脚放在踏板上，并用带子（如果有）将其固定。","以舒适的速度开始踩踏板。","保持稳定的节奏并根据需要增加阻力。","调动核心肌肉以保持稳定性和正确的姿势。","继续踩踏板达到所需的锻炼时间。","逐渐减小阻力并减速，然后完全停止。","锻炼后伸展双腿并放松。"],"kind":"exercise","img":"media/2138-H1PESYI.jpg","gif":"media/2138-H1PESYI.gif","poses":"media/2138-H1PESYI-poses.jpg"},{"id":"2141","name":"walk elliptical cross trainer","name_zh":"椭圆机漫步","category":"cardio","equipment":"elliptical machine","target":"cardiovascular system","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"instructions_zh":["将椭圆机的阻力水平和倾斜度调整到您想要的设置。","踩上机器的踏板并轻轻握住手柄。","首先用脚向下压，然后将手柄拉向身体。","继续这个动作，交替推和拉，以模拟行走或跑步动作。","在整个练习过程中保持稳定的步伐并保持核心参与。","继续进行有氧运动所需的持续时间。","下车前逐渐降低机器的强度和速度。"],"kind":"exercise","img":"media/2141-rjtuP6X.jpg","gif":"media/2141-rjtuP6X.gif","poses":"media/2141-rjtuP6X-poses.jpg"},{"id":"2144","name":"cable seated chest press","name_zh":"绳索坐姿夹胸推","category":"chest","equipment":"cable","target":"pectorals","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"instructions_zh":["将座椅高度和电缆手柄调整至舒适的位置。","坐在长凳上，背部挺直，双脚平放在地板上。","正手握住电缆手柄，与肩同高。","向前推动手柄并使其远离身体，充分伸展双臂。","暂停片刻，然后慢慢将手柄放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/2144-nIR4Rwl.jpg","gif":"media/2144-nIR4Rwl.gif","poses":"media/2144-nIR4Rwl-poses.jpg"},{"id":"2187","name":"barbell reverse close-grip bench press","name_zh":"杠铃反握窄握卧推","category":"upper arms","equipment":"barbell","target":"triceps","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"instructions_zh":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","反握抓住杠铃，双手与肩同宽。","将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。","慢慢地将杠铃向胸部降低，保持肘部靠近身体。","当杠铃位于胸部正上方时，暂停片刻。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"],"kind":"exercise","img":"media/2187-YqJw82s.jpg","gif":"media/2187-YqJw82s.gif","poses":"media/2187-YqJw82s-poses.jpg"},{"id":"2204","name":"roller body saw","name_zh":"滚轴体锯","category":"waist","equipment":"roller","target":"abs","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps","core"],"instructions_zh":["从平板支撑位置开始，前臂放在滚轴上，身体呈一条直线。","启动你的核心并缓慢向前滚动滚轮，在保持控制的同时尽可能地伸展你的身体。","在最远点暂停片刻，然后慢慢地将滚轮滚回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/2204-XeMvLgE.jpg","gif":"media/2204-XeMvLgE.gif","poses":"media/2204-XeMvLgE-poses.jpg"},{"id":"2271","name":"left hook. boxing","name_zh":"拳击左勾拳","category":"shoulders","equipment":"body weight","target":"delts","muscle_group":"biceps","secondary_muscles":["biceps","triceps","forearms"],"instructions_zh":["双脚分开与肩同宽站立，膝盖稍微弯曲。","左手举起以保护脸部，右手握住下巴。","旋转臀部并以左脚为轴心，同时以出拳动作向前伸展左臂。","扭转你的躯干并调动你的核心肌肉以产生出拳的力量。","将手臂拉回到起始位置，然后重复所需的重复次数。"],"kind":"exercise","img":"media/2271-hoXt6wv.jpg","gif":"media/2271-hoXt6wv.gif","poses":"media/2271-hoXt6wv-poses.jpg"},{"id":"2287","name":"lever alternate leg press","name_zh":"器械交替腿举","category":"upper legs","equipment":"leverage machine","target":"quads","muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"instructions_zh":["将杠杆机的座椅和脚踏平台调整到您想要的位置。","坐在机器上，背部靠在靠背上，双脚放在脚踏板上。","将手放在机器的手柄或侧面以保持稳定性。","将一只脚推到脚平台上，伸展腿直到几乎完全伸直。","暂停片刻，然后慢慢弯曲腿，回到起始位置。","换另一条腿重复上述步骤。","继续交替双腿达到所需的重复次数。"],"kind":"exercise","img":"media/2287-V07qpXy.jpg","gif":"media/2287-V07qpXy.gif","poses":"media/2287-V07qpXy-poses.jpg"},{"id":"2289","name":"lever calf press","name_zh":"器械小腿推举","category":"lower legs","equipment":"leverage machine","target":"calves","muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"instructions_zh":["调整杠杆机的座椅，使肩膀与杠杆垫对齐。","将脚趾放在杠杆垫上，脚跟悬在边缘上。","抓住手柄或侧面支撑以保持稳定性。","伸展脚踝，收缩小腿肌肉，将杠杆垫向下推。","在动作的底部停顿片刻。","让脚后跟重新抬起，慢慢回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/2289-7B4F5nZ.jpg","gif":"media/2289-7B4F5nZ.gif","poses":"media/2289-7B4F5nZ-poses.jpg"},{"id":"2311","name":"walking on stepmill","name_zh":"楼梯机爬楼","category":"cardio","equipment":"stepmill machine","target":"cardiovascular system","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"instructions_zh":["将步进机调整到舒适的水平。","走上机器，将双手放在扶手上以获得支撑。","开始行走时，将一只脚放在台阶上，然后将另一只脚放在台阶上，双腿交替。","保持直立姿势并锻炼核心肌肉。","继续步行所需的时间或距离。","当您对锻炼感到更加舒适时，逐渐增加强度或速度。","完成练习后记得冷静下来并伸展身体。"],"kind":"exercise","img":"media/2311-j9Q5crt.jpg","gif":"media/2311-j9Q5crt.gif","poses":"media/2311-j9Q5crt-poses.jpg"},{"id":"2330","name":"cable lat pulldown full range of motion","name_zh":"绳索背阔肌全程下拉","category":"back","equipment":"cable","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"instructions_zh":["坐在高位下拉机上，膝盖位于护垫下方。","正手握住电缆杆，握距略宽于肩宽。","稍微向后倾斜，挺胸，保持下背部轻微的拱形。","将杠铃向下拉至上胸部，将肩胛骨挤压在一起。","在动作底部暂停片刻，然后慢慢松开杠铃回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/2330-LEprlgG.jpg","gif":"media/2330-LEprlgG.gif","poses":"media/2330-LEprlgG-poses.jpg"},{"id":"2364","name":"assisted wide-grip chest dip (kneeling)","name_zh":"辅助跪姿宽握双杠臂屈伸","category":"chest","equipment":"leverage machine","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["将机器调整到您想要的高度，并将膝盖固定在垫子上。","宽握手柄并保持肘部稍微弯曲。","弯曲肘部降低身体，直到上臂与地板平行。","伸展双臂，将自己推回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/2364-PnZJIrk.jpg","gif":"media/2364-PnZJIrk.gif","poses":"media/2364-PnZJIrk-poses.jpg"},{"id":"2398","name":"close-grip push-up (on knees)","name_zh":"跪姿窄距俯卧撑","category":"upper arms","equipment":"body weight","target":"triceps","muscle_group":"chest","secondary_muscles":["chest","shoulders"],"instructions_zh":["首先双手和膝盖着地，双手与肩同宽，膝盖与臀部同宽。","弯曲肘部，将上身压向地面，使其靠近身体两侧。","当你的胸部刚好高于地面时，暂停片刻。","推动手掌以伸直手臂并返回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/2398-v3vLFW0.jpg","gif":"media/2398-v3vLFW0.gif","poses":"media/2398-v3vLFW0-poses.jpg"},{"id":"2405","name":"cable triceps pushdown (v-bar) (with arm blaster)","name_zh":"绳索肱三下压（V杆+固定带）","category":"upper arms","equipment":"cable","target":"triceps","muscle_group":"forearms","secondary_muscles":["forearms"],"instructions_zh":["在最高设置下将 V 形杆附件连接到电缆机上。","面对电缆机站立，双脚与肩同宽。","正手握住 V 形杆，手掌朝下，双手与肩同宽。","在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。","收紧三头肌并呼气，同时向下推 V 形杆，直到手臂完全伸展。","在动作的底部暂停片刻，挤压你的三头肌。","吸气，同时缓慢地将 V 形杆返回到起始位置，保持控制。","重复所需的重复次数。"],"kind":"exercise","img":"media/2405-OxJk1fg.jpg","gif":"media/2405-OxJk1fg.gif","poses":"media/2405-OxJk1fg-poses.jpg"},{"id":"2406","name":"cable reverse grip triceps pushdown (sz-bar) (with arm blaster)","name_zh":"绳索反握肱三下压（Z杆+固定带）","category":"upper arms","equipment":"cable","target":"triceps","muscle_group":"forearms","secondary_muscles":["forearms"],"instructions_zh":["在最高设置下将直杆连接到电缆机上。","面对电缆机站立，双脚与肩同宽。","反手握住杠铃，手掌朝上，双手与肩同宽。","在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。","启动你的三头肌，慢慢地向下推杠铃，直到你的手臂完全伸展。","在底部暂停片刻，然后慢慢地将杠铃返回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/2406-ThKP69G.jpg","gif":"media/2406-ThKP69G.gif","poses":"media/2406-ThKP69G-poses.jpg"},{"id":"2462","name":"chest dip on straight bar","name_zh":"直杆双杠臂屈伸","category":"chest","equipment":"body weight","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["手掌朝下，双臂完全伸展，抓住双杠。","弯曲膝盖并交叉脚踝。","弯曲手臂，降低身体，直到肩膀低于肘部。","伸直手臂，将自己推回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/2462-LQFOrMn.jpg","gif":"media/2462-LQFOrMn.gif","poses":"media/2462-LQFOrMn-poses.jpg"},{"id":"2464","name":"cable thibaudeau kayak row","name_zh":"绳索皮划艇划船","category":"back","equipment":"cable","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"instructions_zh":["将电缆手柄连接到低滑轮上，面向机器坐着，双脚平放在地板上。","用右手抓住手柄，完全伸展手臂，保持肘部轻微弯曲。","从臀部开始向前倾斜，保持背部挺直并收紧腹肌。","缩回肩胛骨并弯曲肘部，将手柄拉向躯干，保持手臂靠近身体。","在动作的最高点挤压背部肌肉，然后慢慢回到起始位置。","重复所需的重复次数，然后换边并用左臂执行。"],"kind":"exercise","img":"media/2464-ZgwWBoC.jpg","gif":"media/2464-ZgwWBoC.gif","poses":"media/2464-ZgwWBoC-poses.jpg"},{"id":"2466","name":"bridge - mountain climber (cross body)","name_zh":"桥式交叉登山跑","category":"waist","equipment":"body weight","target":"abs","muscle_group":"glutes","secondary_muscles":["glutes","quadriceps","hamstrings","shoulders","triceps"],"instructions_zh":["从高平板支撑位置开始，双手直接放在肩膀下方，身体呈一条直线。","启动你的核心并将右脚抬离地面，将右膝移向左肘。","将右脚放回到起始位置，然后将左脚朝向右肘重复该动作。","继续交替两侧，以受控的速度移动。","保持臀部水平，避免臀部抬得太高或下垂得太低。","在整个练习过程中保持稳定的呼吸模式。","重复所需的重复次数。"],"kind":"exercise","img":"media/2466-9c6T1YX.jpg","gif":"media/2466-9c6T1YX.gif","poses":"media/2466-9c6T1YX-poses.jpg"},{"id":"2612","name":"jump rope","name_zh":"跳绳","category":"cardio","equipment":"rope","target":"cardiovascular system","muscle_group":"calves","secondary_muscles":["calves","quadriceps","hamstrings","glutes"],"instructions_zh":["双手握住跳绳的手柄，掌心向内。","站立，双脚分开与肩同宽，膝盖稍微弯曲。","将绳子甩过头顶，当绳子靠近你的脚时跳过它。","轻轻地用脚掌着地，当绳子再次绕回时重复跳跃。","继续跳跃所需的持续时间或重复次数。"],"kind":"exercise","img":"media/2612-e1e76I2.jpg","gif":"media/2612-e1e76I2.gif","poses":"media/2612-e1e76I2-poses.jpg"},{"id":"2616","name":"cable lateral pulldown with v-bar","name_zh":"绳索V杆高位下拉","category":"back","equipment":"cable","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["坐在电缆下拉机上，用正手抓住 V 形杆附件。","调整护膝，使大腿固定在其下方。","保持背部挺直并稍微向后倾斜。","将 V 形杆向下拉至上胸部，同时保持肘部靠近身体。","在动作底部挤压背部肌肉。","慢慢地将 v 形杆返回到起始位置，然后重复所需的重复次数。"],"kind":"exercise","img":"media/2616-4c9BhzB.jpg","gif":"media/2616-4c9BhzB.gif","poses":"media/2616-4c9BhzB-poses.jpg"},{"id":"2705","name":"dumbbell lying pronation on floor","name_zh":"哑铃地板仰卧旋前","category":"lower arms","equipment":"dumbbell","target":"forearms","muscle_group":"biceps","secondary_muscles":["biceps","triceps"],"instructions_zh":["平躺在地板上，脸朝下，双臂伸直在身前，每只手各握一个哑铃。","旋转手掌，使其朝下朝向地板。","保持手臂伸直，收缩前臂将哑铃提离地板。","继续举起，直到前臂完全收缩并且哑铃与肩部齐平。","保持一会儿，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/2705-7RWNjiB.jpg","gif":"media/2705-7RWNjiB.gif","poses":"media/2705-7RWNjiB-poses.jpg"},{"id":"2798","name":"barbell squat jump step rear lunge","name_zh":"杠铃深蹲跳接后箭步蹲","category":"upper legs","equipment":"barbell","target":"quads","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"instructions_zh":["首先，双脚分开与肩同宽站立，将杠铃放在上背部。","弯曲膝盖并将臀部向后推，将身体降低至蹲姿。","向上爆炸，尽可能高地跳离地面。","双脚轻轻落地，然后立即单腿向后退一步，形成反向弓步。","降低身体，直到大腿前侧与地面平行，保持背部挺直。","推动前脚跟以返回到起始位置。","在另一条腿上重复跳跃和弓步序列。","继续交替双腿达到所需的重复次数。"],"kind":"exercise","img":"media/2798-RYcV1kH.jpg","gif":"media/2798-RYcV1kH.gif","poses":"media/2798-RYcV1kH-poses.jpg"},{"id":"2810","name":"barbell split squat v. 2","name_zh":"杠铃分腿蹲（变式）","category":"upper legs","equipment":"barbell","target":"quads","muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"instructions_zh":["首先，双脚分开与肩同宽站立，将杠铃放在上背部。","右脚向前迈出一大步，保持躯干直立。","弯曲膝盖和臀部，降低身体，直到右大腿与地面平行。","暂停片刻，然后推动右脚跟回到起始位置。","左腿向前重复此动作，达到所需的重复次数。"],"kind":"exercise","img":"media/2810-HBYyX94.jpg","gif":"media/2810-HBYyX94.gif","poses":"media/2810-HBYyX94-poses.jpg"},{"id":"3017","name":"barbell pendlay row","name_zh":"杠铃彭德莱划船","category":"back","equipment":"barbell","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["双脚分开与肩同宽站立，膝盖稍微弯曲。","臀部向前弯曲，保持背部挺直，挺胸。","正手握住杠铃，握距略宽于肩宽。","将杠铃拉向上腹部，将肩胛骨挤压在一起。","将杠铃降低回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/3017-r0z6xzQ.jpg","gif":"media/3017-r0z6xzQ.gif","poses":"media/3017-r0z6xzQ-poses.jpg"},{"id":"3019","name":"bench pull-ups","name_zh":"凳上引体向上","category":"back","equipment":"body weight","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["将自己置于与胸部同高的横杆或坚固的水平表面下方。","正手握住杠铃或杠铃表面，握距略宽于肩宽。","双臂完全伸展，身体伸直。","将肩胛骨挤压在一起并弯曲肘部，将胸部拉向杠铃或地面。","继续拉，直到下巴位于杆或表面上方。","有控制地降低自己回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/3019-mExgrF9.jpg","gif":"media/3019-mExgrF9.gif","poses":"media/3019-mExgrF9-poses.jpg"},{"id":"3116","name":"band fixed back underhand pulldown","name_zh":"弹力带固定反手下拉","category":"back","equipment":"band","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"instructions_zh":["将带子固定在头顶上方坚固的锚点上。","面向锚点站立，双脚分开与肩同宽。","反手握住弹力带，双手间距略宽于肩宽。","后退一步，在弹力带上产生张力，保持手臂完全伸展。","启动你的核心并将肩胛骨挤压在一起。","将弹力带向下拉向胸部，用肘部引导。","在动作的底部暂停片刻，感受背阔肌的收缩。","慢慢释放带子的张力并返回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/3116-ZH68exZ.jpg","gif":"media/3116-ZH68exZ.gif","poses":"media/3116-ZH68exZ-poses.jpg"},{"id":"3117","name":"band fixed back close grip pulldown","name_zh":"弹力带固定窄握下拉","category":"back","equipment":"band","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["将弹力带固定在您上方的固定点上，例如上拉杆或坚固的横梁。","坐在面向乐队的长凳或椅子上，双脚平放在地上，膝盖弯曲。","紧紧握住弹力带，手掌朝向您。","保持背部挺直并启动核心肌群。","将弹力带向下拉向胸部，将肩胛骨挤压在一起。","在动作的底部暂停片刻，感受背阔肌的收缩。","慢慢地将弹力带释放回起始位置，在整个运动过程中保持控制。","重复所需的重复次数。"],"kind":"exercise","img":"media/3117-4LoWllp.jpg","gif":"media/3117-4LoWllp.gif","poses":"media/3117-4LoWllp-poses.jpg"},{"id":"3156","name":"bodyweight standing close-grip one arm row","name_zh":"自重站姿窄握单臂划船","category":"back","equipment":"body weight","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["双脚分开与肩同宽站立，膝盖稍微弯曲，一只手握住哑铃，握姿中立。","臀部向前弯曲，保持背部挺直，核心肌群参与。","将哑铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换边。"],"kind":"exercise","img":"media/3156-v2DfH14.jpg","gif":"media/3156-v2DfH14.gif","poses":"media/3156-v2DfH14-poses.jpg"},{"id":"3158","name":"bodyweight standing close-grip row","name_zh":"自重站姿窄握划船","category":"back","equipment":"body weight","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["站立，双脚分开与肩同宽，膝盖稍微弯曲。","腰部向前弯曲，保持背部挺直，核心肌群参与。","将双臂伸直在身前，紧紧抓住杆或手柄。","将杠铃或手柄拉向身体，将肩胛骨挤压在一起。","在动作的最高点停顿片刻，然后慢慢松开并回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/3158-tig3PXb.jpg","gif":"media/3158-tig3PXb.gif","poses":"media/3158-tig3PXb-poses.jpg"},{"id":"3161","name":"bodyweight standing one arm row (with towel)","name_zh":"自重站姿单臂划船（毛巾）","category":"back","equipment":"body weight","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["双脚分开与肩同宽站立，膝盖微曲，单手握住毛巾。","臀部向前弯曲，保持背部挺直，核心肌群参与。","将毛巾拉向胸部，将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢将毛巾放回起始位置。","重复所需的重复次数，然后换到另一只手臂。"],"kind":"exercise","img":"media/3161-O4oIqQD.jpg","gif":"media/3161-O4oIqQD.gif","poses":"media/3161-O4oIqQD-poses.jpg"},{"id":"3162","name":"bodyweight standing one arm row","name_zh":"自重站姿单臂划船","category":"back","equipment":"body weight","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["双脚分开与肩同宽站立，膝盖稍微弯曲，一手握住哑铃。","臀部向前弯曲，保持背部挺直，核心肌群参与。","让哑铃垂直悬挂在您面前，手臂完全伸展。","将哑铃向上拉向胸部，保持肘部靠近身体。","在动作的最高点将肩胛骨挤压在一起。","将哑铃放回起始位置。","重复所需的重复次数，然后换边。"],"kind":"exercise","img":"media/3162-xbkPfaw.jpg","gif":"media/3162-xbkPfaw.gif","poses":"media/3162-xbkPfaw-poses.jpg"},{"id":"3165","name":"bodyweight standing row (with towel)","name_zh":"自重站姿划船（毛巾）","category":"back","equipment":"body weight","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"instructions_zh":["双脚分开与肩同宽站立，双手握住毛巾放在身前。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","将毛巾拉向胸部，将肩胛骨挤压在一起。","在最高点停顿片刻，然后慢慢释放张力，回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/3165-uTv34oq.jpg","gif":"media/3165-uTv34oq.gif","poses":"media/3165-uTv34oq-poses.jpg"},{"id":"3166","name":"bodyweight standing row","name_zh":"自重站姿划船","category":"back","equipment":"body weight","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"instructions_zh":["站立，双脚分开与肩同宽，膝盖稍微弯曲。","正手握住杆或手柄，手掌朝下。","保持背部挺直，核心参与。","将杠铃或手柄拉向身体，将肩胛骨挤压在一起。","在动作的最高点停顿片刻。","慢慢释放并伸展双臂回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/3166-wd4ds3s.jpg","gif":"media/3166-wd4ds3s.gif","poses":"media/3166-wd4ds3s-poses.jpg"},{"id":"3167","name":"bodyweight squatting row (with towel)","name_zh":"自重蹲姿划船（毛巾）","category":"back","equipment":"body weight","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"instructions_zh":["双脚分开与肩同宽站立，手掌朝下，将毛巾放在身前。","弯曲膝盖，将身体降低至蹲姿，保持背部挺直，挺胸。","当你下蹲时，同时将毛巾拉向胸部，将肩胛骨挤压在一起。","在深蹲底部停顿片刻，然后慢慢回到起始位置，同时伸展双臂。","重复所需的重复次数。"],"kind":"exercise","img":"media/3167-BReCuOn.jpg","gif":"media/3167-BReCuOn.gif","poses":"media/3167-BReCuOn-poses.jpg"},{"id":"3168","name":"bodyweight squatting row","name_zh":"自重蹲姿划船","category":"back","equipment":"body weight","target":"upper back","muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"instructions_zh":["双脚分开与肩同宽站立，伸直手臂抓住坚固的物体或悬挂训练器。","将身体降低至蹲姿，保持背部挺直，膝盖位于脚趾后面。","从蹲姿开始，将身体向上拉向物体或悬挂训练器，将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/3168-3xK09Sk.jpg","gif":"media/3168-3xK09Sk.gif","poses":"media/3168-3xK09Sk-poses.jpg"},{"id":"3216","name":"chest tap push-up (male)","name_zh":"击胸俯卧撑","category":"chest","equipment":"body weight","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"instructions_zh":["从高平板支撑位置开始，双手分开略宽于肩宽，身体呈一条直线。","弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。","当你降低身体时，用右手拍打胸部。","将自己推回到起始位置。","重复这个动作，这次用左手敲击胸部。","继续交替进行所需的重复次数。"],"kind":"exercise","img":"media/3216-7E06s6d.jpg","gif":"media/3216-7E06s6d.gif","poses":"media/3216-7E06s6d-poses.jpg"},{"id":"3220","name":"astride jumps (male)","name_zh":"分腿跳跃","category":"cardio","equipment":"body weight","target":"cardiovascular system","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"instructions_zh":["双脚分开与肩同宽站立。","弯曲膝盖并将身体降低至蹲姿。","爆发性向上跳跃，伸展双腿和手臂。","在空中时，将双腿分开，并将双臂向两侧伸出。","双脚分开与肩同宽，轻轻落地，弯曲膝盖以吸收冲击力。","重复所需的重复次数。"],"kind":"exercise","img":"media/3220-f9lVSSI.jpg","gif":"media/3220-f9lVSSI.gif","poses":"media/3220-f9lVSSI-poses.jpg"},{"id":"3293","name":"archer pull up","name_zh":"弓箭手引体向上","category":"back","equipment":"body weight","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["首先，用正手握法悬挂在引体向上杆上，握距略宽于肩宽。","启动你的核心并将肩胛骨向下拉和向后拉。","当你站起来时，弯曲一只手臂并将肘部移向身体一侧，同时保持另一只手臂伸直。","继续拉，直到下巴位于杠铃上方并且弯曲的手臂完全弯曲。","有控制地放低自己，伸直弯曲的手臂并在另一侧重复该动作。","每次重复时交替进行。"],"kind":"exercise","img":"media/3293-72BC5Za.jpg","gif":"media/3293-72BC5Za.gif","poses":"media/3293-72BC5Za-poses.jpg"},{"id":"3294","name":"archer push up","name_zh":"弓箭手俯卧撑","category":"chest","equipment":"body weight","target":"pectorals","muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"instructions_zh":["从俯卧撑位置开始，双手分开略宽于肩宽。","将一只手臂伸直至一侧，与地面平行。","弯曲肘部降低身体，保持背部挺直，核心参与。","推回到起始位置。","在另一侧重复上述步骤，将另一只手臂伸出到一侧。","继续交替进行所需的重复次数。"],"kind":"exercise","img":"media/3294-A9qxk2F.jpg","gif":"media/3294-A9qxk2F.gif","poses":"media/3294-A9qxk2F-poses.jpg"},{"id":"3305","name":"barbell thruster","name_zh":"杠铃蹲推","category":"shoulders","equipment":"barbell","target":"delts","muscle_group":"quadriceps","secondary_muscles":["quadriceps","glutes","hamstrings","core"],"instructions_zh":["首先，双脚分开与肩同宽站立，正手握住杠铃，与肩同高。","弯曲膝盖并将臀部向后推，降低至蹲姿。","当你到达深蹲底部时，爆发性地通过脚后跟站起来，同时将杠铃压过头顶。","当你回到深蹲位置时，将杠铃降低到肩膀高度。","重复所需的重复次数。"],"kind":"exercise","img":"media/3305-f7Y9eDZ.jpg","gif":"media/3305-f7Y9eDZ.gif","poses":"media/3305-f7Y9eDZ-poses.jpg"},{"id":"3360","name":"bear crawl","name_zh":"熊爬","category":"cardio","equipment":"body weight","target":"cardiovascular system","muscle_group":"core","secondary_muscles":["core","shoulders","triceps"],"instructions_zh":["从四肢着地开始，双手直接放在肩膀下方，膝盖直接放在臀部下方。","将膝盖稍微抬离地面，保持背部平坦并收紧核心。","同时向前移动右手和左脚，然后是左手和右脚。","继续向前爬行，手脚交替动作。","在整个练习过程中保持稳定的节奏并保持核心紧张。","继续所需的距离或时间。"],"kind":"exercise","img":"media/3360-0Yz8WdV.jpg","gif":"media/3360-0Yz8WdV.gif","poses":"media/3360-0Yz8WdV-poses.jpg"},{"id":"3543","name":"bodyweight drop jump squat","name_zh":"自重增强式深蹲跳","category":"upper legs","equipment":"body weight","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"instructions_zh":["双脚分开与肩同宽站立。","弯曲膝盖并将臀部向后推，将身体降低至蹲姿。","爆发性地跳起来，伸展臀部、膝盖和脚踝。","在半空中时，快速将双脚并拢。","脚掌轻轻着地，然后立即回到蹲姿。","重复所需的重复次数。"],"kind":"exercise","img":"media/3543-wfotm7S.jpg","gif":"media/3543-wfotm7S.gif","poses":"media/3543-wfotm7S-poses.jpg"},{"id":"3545","name":"dumbbell incline alternate press","name_zh":"哑铃上斜交替推","category":"chest","equipment":"dumbbell","target":"pectorals","muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"instructions_zh":["坐在上斜凳上，每只手各拿一个哑铃，放在大腿上。","向后靠在长凳上，用大腿帮助将哑铃举至肩高，手掌朝前。","到达肩膀高度后，旋转手腕，使手掌朝前。","用胸部和肩膀将哑铃向上推，充分伸展手臂。","将哑铃放回起始位置，保持肘部稍微弯曲。","重复所需的重复次数，交替手臂。"],"kind":"exercise","img":"media/3545-TVdivgY.jpg","gif":"media/3545-TVdivgY.gif","poses":"media/3545-TVdivgY-poses.jpg"},{"id":"3563","name":"cable one arm pulldown","name_zh":"绳索单臂下拉","category":"back","equipment":"cable","target":"lats","muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"instructions_zh":["将单个手柄连接到高滑轮电缆机上。","面向机器站立，双脚分开与肩同宽。","正手握住手柄并完全伸展手臂。","保持背部挺直，核心肌群参与。","将手柄向一侧拉，同时保持肘部靠近身体。","在动作底部暂停片刻，挤压背阔肌。","慢慢松开手柄回到起始位置。","重复所需的重复次数。","换边并用另一只手臂重复练习。"],"kind":"exercise","img":"media/3563-U5INZY6.jpg","gif":"media/3563-U5INZY6.gif","poses":"media/3563-U5INZY6-poses.jpg"},{"id":"3635","name":"dumbbell contralateral forward lunge","name_zh":"哑铃对侧前箭步蹲","category":"upper legs","equipment":"dumbbell","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"instructions_zh":["双脚分开与肩同宽站立，每只手各握一个哑铃。","右脚向前迈出一步，保持背部挺直并启动核心。","弯曲双膝降低身体，直到右大腿与地面平行。","推动右脚跟回到起始位置。","左腿重复上述动作。","交替腿进行所需的重复次数。"],"kind":"exercise","img":"media/3635-ecl28tP.jpg","gif":"media/3635-ecl28tP.gif","poses":"media/3635-ecl28tP-poses.jpg"},{"id":"3642","name":"weighted stretch lunge","name_zh":"箭步蹲髋屈肌拉伸","category":"upper legs","equipment":"weighted","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"instructions_zh":["双脚分开与肩同宽站立。","右脚向前迈出一步，保持背部挺直。","弯曲膝盖降低身体，直到右大腿与地面平行。","推动右脚跟回到起始位置。","左腿重复上述动作。","继续交替双腿达到所需的重复次数。"],"kind":"stretch","img":"media/3642-13VW2VO.jpg","gif":"media/3642-13VW2VO.gif","poses":"media/3642-13VW2VO-poses.jpg"},{"id":"3643","name":"weighted cossack squats (male)","name_zh":"负重哥萨克深蹲","category":"upper legs","equipment":"weighted","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"instructions_zh":["站立时双脚分开比肩宽，脚趾稍微向外。","用双手将重物放在胸前。","将您的体重转移到一侧，并通过弯曲您转移一侧的膝盖来降低身体，同时保持另一条腿伸直。","尽可能降低身体高度，同时保持平衡并挺胸。","推动弯曲腿的脚跟以返回到起始位置。","在另一侧重复，双腿之间交替。"],"kind":"exercise","img":"media/3643-GWoKnIm.jpg","gif":"media/3643-GWoKnIm.gif","poses":"media/3643-GWoKnIm-poses.jpg"},{"id":"3697","name":"cable kneeling rear delt row (with rope) (male)","name_zh":"绳索跪姿后束划船（绳把）","category":"shoulders","equipment":"cable","target":"delts","muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids","biceps"],"instructions_zh":["将绳索手柄连接到低电缆滑轮上，面向机器跪下。","以中立握法（手掌相对）抓住绳子，并将双臂完全伸展到身前。","保持背部挺直，核心收紧，通过收缩肩胛骨将绳子拉向身体。","在动作结束时将肩胛骨挤压在一起并保持短暂的停顿。","慢慢释放张力并回到起始位置。","重复所需的重复次数。"],"kind":"exercise","img":"media/3697-G61cXLk.jpg","gif":"media/3697-G61cXLk.gif","poses":"media/3697-G61cXLk-poses.jpg"},{"id":"3769","name":"curtsey squat","name_zh":"后交叉深蹲","category":"upper legs","equipment":"body weight","target":"glutes","muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"instructions_zh":["双脚分开与肩同宽站立。","右脚向斜后方跨出一步，跨过身体，交叉在左腿后面。","弯曲双膝，就像行屈膝礼一样，将身体降低到地面。","保持躯干直立，将体重放在前脚上。","推动前脚返回起始位置。","在另一侧重复，用左脚斜向后方跨过身体。"],"kind":"exercise","img":"media/3769-gUjqdei.jpg","gif":"media/3769-gUjqdei.gif","poses":"media/3769-gUjqdei-poses.jpg"}];